        def start_drag(e)
          %x{
            var ev = #{e} || window.event;
            if (!ev) return;

            var target = ev.target || ev.srcElement;
            if (target) {
              var tag = (target.tagName || '').toUpperCase();
              if (tag === 'BUTTON' || tag === 'INPUT' || (target.closest && target.closest('button'))) {
                return;
              }
            }

            var header = ev.currentTarget;
            var hud = document.getElementById('action_floating_window') || (header && header.parentElement);
            if (!hud) return;

            if (ev.preventDefault) ev.preventDefault();
            header.style.cursor = 'grabbing';

            var rect = hud.getBoundingClientRect();
            var shiftX = ev.clientX - rect.left;
            var shiftY = ev.clientY - rect.top;

            hud.style.position = 'fixed';
            hud.style.left = rect.left + 'px';
            hud.style.top = rect.top + 'px';
            hud.style.margin = '0';
            hud.style.transform = 'none';

            function onMouseMove(moveEv) {
              var mEv = moveEv || window.event;
              if (mEv.preventDefault) mEv.preventDefault();

              var newLeft = mEv.clientX - shiftX;
              var newTop = mEv.clientY - shiftY;
              var maxLeft = window.innerWidth - 80;
              var maxTop = window.innerHeight - 30;

              if (newLeft < 10) newLeft = 10;
              if (newLeft > maxLeft) newLeft = maxLeft;
              if (newTop < 0) newTop = 0;
              if (newTop > maxTop) newTop = maxTop;

              hud.style.left = newLeft + 'px';
              hud.style.top = newTop + 'px';
            }

            function onMouseUp() {
              document.removeEventListener('mousemove', onMouseMove, true);
              document.removeEventListener('mouseup', onMouseUp, true);
              window.removeEventListener('mousemove', onMouseMove, true);
              window.removeEventListener('mouseup', onMouseUp, true);

              header.style.cursor = 'grab';

              try {
                localStorage.setItem(
                  'action_window_pos',
                  JSON.stringify({
                    left: hud.style.left,
                    top: hud.style.top
                  })
                );
              } catch (err) {}
            }

            document.addEventListener('mousemove', onMouseMove, true);
            document.addEventListener('mouseup', onMouseUp, true);
            window.addEventListener('mousemove', onMouseMove, true);
            window.addEventListener('mouseup', onMouseUp, true);
          }
        end

        def start_resize(e)
          %x{
            var ev = #{e} || window.event;
            if (!ev) return;
            if (ev.native) ev = ev.native;

            if (ev.preventDefault) ev.preventDefault();
            if (ev.stopPropagation) ev.stopPropagation();

            var hud = document.getElementById('action_floating_window');
            if (!hud) return;

            var point = ev.touches && ev.touches.length ? ev.touches[0] : ev;
            var rect = hud.getBoundingClientRect();
            var startX = point.clientX;
            var startY = point.clientY;
            var startW = rect.width;
            var startH = rect.height;

            document.body.style.userSelect = 'none';
            document.body.style.cursor = 'nwse-resize';

            function onMove(moveEv) {
              var movePoint = moveEv.touches && moveEv.touches.length ? moveEv.touches[0] : moveEv;
              if (!movePoint) return;
              if (moveEv.preventDefault) moveEv.preventDefault();

              var maxW = Math.max(300, window.innerWidth - rect.left - 10);
              var maxH = Math.max(160, window.innerHeight - rect.top - 10);
              var newW = Math.max(300, Math.min(maxW, startW + (movePoint.clientX - startX)));
              var newH = Math.max(160, Math.min(maxH, startH + (movePoint.clientY - startY)));

              hud.style.width = newW + 'px';
              hud.style.height = newH + 'px';
              hud.style.maxWidth = 'none';
              hud.style.maxHeight = 'none';
            }

            function onUp() {
              document.removeEventListener('mousemove', onMove, true);
              document.removeEventListener('mouseup', onUp, true);
              document.removeEventListener('touchmove', onMove, true);
              document.removeEventListener('touchend', onUp, true);
              document.removeEventListener('touchcancel', onUp, true);

              document.body.style.userSelect = '';
              document.body.style.cursor = '';

              try {
                localStorage.setItem(
                  'action_window_size',
                  JSON.stringify({
                    width: hud.style.width,
                    height: hud.style.height
                  })
                );
              } catch (err) {}
            }

            document.addEventListener('mousemove', onMove, true);
            document.addEventListener('mouseup', onUp, true);
            document.addEventListener('touchmove', onMove, { capture: true, passive: false });
            document.addEventListener('touchend', onUp, true);
            document.addEventListener('touchcancel', onUp, true);
          }
        end
