        def active_routes
          @routes.select { |r| r.chains.any? }
        end

        def actions_for(entity)
          return [] unless entity

          actions = []
          if @game.round.respond_to?(:actions_for)
            begin
              actions.concat(Array(@game.round.actions_for(entity)))
            rescue NotImplementedError, StandardError
            end
          end

          step = active_step_for(entity) || (@game.round.respond_to?(:active_step) ? @game.round.active_step : nil)
          if step.respond_to?(:actions)
            begin
              actions.concat(Array(step.actions(entity)))
            rescue NotImplementedError, StandardError
            end
          end

          actions.compact.map(&:to_s).uniq
        rescue NotImplementedError, StandardError
          []
        end

        def active_step_for(entity)
          return nil unless @game.round.respond_to?(:active_step)

          begin
            @game.round.active_step(entity)
          rescue ArgumentError
            @game.round.active_step
          rescue NotImplementedError, StandardError
            nil
          end
        end

        def my_turn?
          is_hotseat = @game_data && (@game_data[:mode] == :hotseat || @game_data['mode'] == 'hotseat')
          return true if is_hotseat

          user_id = @user&.dig('id') || @user&.dig(:id)
          user_name = @user&.dig('name') || @user&.dig(:name)
          return false unless user_id || user_name

          if @game.respond_to?(:active_players_id) && @game.active_players_id&.any?
            active_ids = @game.active_players_id.map(&:to_s)
            return true if user_id && active_ids.include?(user_id.to_s)
            return true if user_name && active_ids.include?(user_name.to_s)
          end

          p = active_player
          if p
            p_name = (p.respond_to?(:name) && p.name ? p.name.to_s : '')
            p_id = (p.respond_to?(:id) && p.id ? p.id.to_s : '')

            return true if user_name && !p_name.empty? && p_name.casecmp(user_name.to_s).zero?
            return true if user_id && !p_id.empty? && p_id == user_id.to_s

            players_list = @game_data && (@game_data['players'] || @game_data[:players])
            if players_list.is_a?(Array)
              my_rec = players_list.find { |h| (h['id'] || h[:id]).to_s == user_id.to_s }
              rec_name = my_rec&.dig('name') || my_rec&.dig(:name)
              return true if rec_name && !p_name.empty? && p_name.casecmp(rec_name.to_s).zero?
            end
          end

          false
        end

        def corporate_action_entities
          step = @game.round.active_step
          return [] unless step

          target = current_entity
          target = step.current_entity if !corporation_or_minor?(target) && step.respond_to?(:current_entity)
          return [] unless corporation_or_minor?(target)

          candidate = target
          player = active_player

          candidate_step = active_step_for(candidate) || step

          player_actions = player ? actions_for(player).compact.map(&:to_s) : []
          global_actions = candidate_step.respond_to?(:current_actions) ? (candidate_step.current_actions || []).map(&:to_s) : []
          candidate_actions = (actions_for(candidate).compact.map(&:to_s) + player_actions + global_actions).uniq

          round_steps = @game.round.respond_to?(:steps) ? (@game.round.steps || []) : []
          issue_step = round_steps.find do |s|
            s.respond_to?(:issuable_shares) || s.respond_to?(:issuable_bundles)
          end || candidate_step

          redeem_step = round_steps.find do |s|
            s.respond_to?(:redeemable_shares) || s.respond_to?(:redeemable_bundles)
          end || candidate_step

          issuable = begin
            res = []
            if issue_step.respond_to?(:issuable_shares)
              res = begin; issue_step.issuable_shares(candidate) || []; rescue ArgumentError; issue_step.issuable_shares || []; end
            elsif issue_step.respond_to?(:issuable_bundles)
              res = begin; issue_step.issuable_bundles(candidate) || []; rescue ArgumentError; issue_step.issuable_bundles || []; end
            end
            res = @game.issuable_shares(candidate) || [] if res.empty? && @game.respond_to?(:issuable_shares)
            res
          rescue StandardError
            []
          end

          redeemable = begin
            res = []
            if redeem_step.respond_to?(:redeemable_shares)
              res = begin; redeem_step.redeemable_shares(candidate) || []; rescue ArgumentError; redeem_step.redeemable_shares || []; end
            elsif redeem_step.respond_to?(:redeemable_bundles)
              res = begin; redeem_step.redeemable_bundles(candidate) || []; rescue ArgumentError; redeem_step.redeemable_bundles || []; end
            end
            res = @game.redeemable_shares(candidate) || [] if res.empty? && @game.respond_to?(:redeemable_shares)
            res
          rescue StandardError
            []
          end

          can_issue =
            (candidate_actions &
             %w[issue issue_shares reissue reissue_shares corporate_sell_shares sell_shares]).any? &&
            issuable.compact.any?

          can_redeem =
            (candidate_actions &
             %w[redeem redeem_shares corporate_buy_shares buy_shares]).any? &&
            redeemable.compact.any?

          can_issue || can_redeem ? [[candidate, candidate_actions]] : []
        end

        def active_player
          entity = current_entity
          return nil unless entity

          if entity.respond_to?(:player?) && entity.player?
            entity
          elsif entity.respond_to?(:player) && entity.player
            entity.player
          elsif entity.respond_to?(:owner) && entity.owner.respond_to?(:player?) && entity.owner.player?
            entity.owner
          end
        end

        def company?(entity)
          return false unless entity

          entity.is_a?(Engine::Company) ||
            (entity.respond_to?(:company?) && entity.company?) ||
            (!entity.respond_to?(:corporation?) && !entity.respond_to?(:minor?) && (entity.respond_to?(:value) || entity.respond_to?(:desc)))
        end

        def corporation_or_minor?(entity)
          return false unless entity

          (entity.respond_to?(:corporation?) && entity.corporation?) ||
            (entity.respond_to?(:minor?) && entity.minor?) ||
            (defined?(Engine::Corporation) && entity.is_a?(Engine::Corporation)) ||
            (defined?(Engine::Minor) && entity.is_a?(Engine::Minor))
        end

        def step_description(step)
          return nil unless step.respond_to?(:description)

          step.description
        rescue NotImplementedError, ScriptError, StandardError
          nil
        end

        def home_token_step?(step, actions)
          actions.include?('place_token') && (
            step&.class&.name =~ /HomeToken|Home/i ||
            step_description(step) =~ /Home/i ||
            (step.respond_to?(:home_token?) && (begin; step.home_token?; rescue ScriptError, StandardError; false; end))
          )
        end

        def render_action_row(label, children)
          is_arr = `Array.isArray(#{children})`
          items = (is_arr ? children : [children]).compact
          return nil if items.empty?

          h(:div, {
              style: {
                display: 'grid',
                gridTemplateColumns: '7.5rem minmax(0, 1fr)',
                alignItems: 'start',
                columnGap: '0.75rem',
                width: '100%',
                maxWidth: '100%',
                margin: '0',
                padding: '0.35rem 0',
                boxSizing: 'border-box',
              },
            }, [
            h(:span, {
                style: {
                  fontSize: '0.88rem',
                  fontWeight: '650',
                  color: '#334155',
                  textAlign: 'left',
                  paddingTop: '0.28rem',
                  lineHeight: '1.25',
                },
              }, label),
            h(:div, {
                style: {
                  display: 'flex',
                  flexDirection: 'row',
                  flexWrap: 'wrap',
                  alignItems: 'center',
                  gap: '0.45rem',
                  minWidth: '0',
                  maxWidth: '100%',
                },
              }, items),
          ])
        end

        def render_generic_choice(step, entity)
          return nil unless step && entity

          prompt = if step.respond_to?(:choice_name) && step.choice_name
                     step.choice_name
                   elsif (desc = step_description(step))
                     desc
                   else
                     'Choice:'
                   end

          raw_choices = begin
            if step.respond_to?(:choices_for)
              begin
                step.choices_for(entity)
              rescue ArgumentError
                step.choices_for
              end
            elsif step.respond_to?(:choices)
              begin
                step.choices(entity)
              rescue ArgumentError
                step.choices
              end
            end
          rescue StandardError
            nil
          end

          return nil unless raw_choices && !raw_choices.empty?

          label = prompt.to_s.strip
          label = "#{label}:" unless label.end_with?(':', '?')

          button_style = {
            padding: '0 12px',
            height: '1.85rem',
            fontSize: '0.85rem',
            fontWeight: 'bold',
            backgroundColor: '#2563eb',
            color: '#ffffff',
            border: '1px solid #1d4ed8',
            borderRadius: '4px',
            cursor: 'pointer',
            boxShadow: '0 1px 2px rgba(0,0,0,0.05)',
            display: 'inline-flex',
            alignItems: 'center',
            justifyContent: 'center',
            lineHeight: '1',
          }

          buttons = case raw_choices
                    when Hash
                      raw_choices.map do |val, text|
                        btn_click = -> { process_action(Engine::Action::Choose.new(entity, choice: val)) }
                        h(:button, {
                            style: button_style,
                            on: { click: btn_click },
                          }, text.to_s)
                      end
                    when Array
                      raw_choices.map do |val|
                        btn_click = -> { process_action(Engine::Action::Choose.new(entity, choice: val)) }
                        h(:button, {
                            style: button_style,
                            on: { click: btn_click },
                          }, val.to_s)
                      end
                    else
                      []
                    end

          return nil if buttons.empty?

          render_action_row(label, buttons)
        end

        # Actions exposed by the engine that are not player-facing turn controls.
        # These must never trigger the native-view fallback warning.
        def background_action?(action)
          name = action.to_s
          %w[end_game log message].include?(name) || name.start_with?('program_')
        end

        def unhandled_actions(actions, handled = [])
          Array(actions)
            .compact
            .map(&:to_s)
            .uniq
            .reject { |action| background_action?(action) }
            .reject { |action| handled.include?(action) }
        end

        # A normal Stock Round turn is status-first. This row deliberately
        # contains neutral text rather than controls.
        def render_possibility_reminder(title, labels, hint: nil)
          labels = Array(labels).compact.uniq
          return nil if labels.empty?

          items = labels.map do |label|
            h(:div, {
                style: {
                  display: 'flex',
                  alignItems: 'baseline',
                  gap: '0.45rem',
                  minHeight: '1.25rem',
                  color: '#475569',
                  fontSize: '0.84rem',
                  fontWeight: '600',
                  lineHeight: '1.25',
                },
              }, [
                h(:span, { style: { color: '#94a3b8', fontWeight: '700', flexShrink: '0' } }, '•'),
                h(:span, label),
              ])
          end

          h(:div, {
