        def render_par_step(step, entity, corporation)
          return h(:div) unless step && corporation

          par_nodes = if step.respond_to?(:get_par_prices_with_help)
                        step.get_par_prices_with_help(entity, corporation)
                      elsif step.respond_to?(:get_par_prices)
                        step.get_par_prices(entity, corporation)
                      elsif step.respond_to?(:par_prices)
                        begin
                          step.par_prices(entity, corporation)
                        rescue ArgumentError
                          step.par_prices(corporation)
                        end
                      elsif @game.respond_to?(:par_prices)
                        @game.par_prices(corporation)
                      else
                        @game.stock_market.par_prices
                      end

          if @game.respond_to?(:par_chart)
            par_nodes = par_nodes.reject do |node|
              p_obj = node.is_a?(Array) ? node.first : node
              slots = @game.par_chart[p_obj]
              slots&.none?(&:nil?)
            end
          end

          corp_badge = render_major_railcard(
            corporation,
            nil,
            ['major-railcard'],
            "cmd_par_corporation_#{corporation.id}"
          )

          is_free_par = step.class.name.include?('CompanyPendingPar') ||
                        (step.respond_to?(:companies_pending_par) && step.companies_pending_par&.any?)

          buttons = par_nodes.map do |node|
            price = node.is_a?(Array) ? node[0] : node
            help = node.is_a?(Array) ? node[1] : nil
            price_val = price.respond_to?(:price) ? price.price : price

            price_str = @game.format_currency(price_val)
            label = help ? "#{price_str} (#{help})" : price_str

            multiplier = if corporation.respond_to?(:presidents_percent) && corporation.respond_to?(:share_percent)
                           (corporation.presidents_percent / corporation.share_percent).to_i
                         elsif corporation.respond_to?(:shares) && corporation.shares.first&.president
                           corporation.shares.first.num_shares || 2
                         else
                           2
                         end
            cost = price_val * multiplier
            can_afford = is_free_par || (entity.respond_to?(:cash) ? entity.cash : 0) >= cost

            click_handler = lambda {
              slot = (@game.par_chart[price].index(nil) if @game.respond_to?(:par_chart) && @game.par_chart[price])
              args = { corporation: corporation, share_price: price }
              args[:slot] = slot if slot
              process_action(Engine::Action::Par.new(entity, **args))
            }

            h(:button, {
                attrs: { disabled: !can_afford },
                style: {
                  height: '1.85rem',
                  padding: '0 8px',
                  fontSize: '0.85rem',
                  fontWeight: 'bold',
                  fontFamily: FONT_MONEY,
                  backgroundColor: can_afford ? '#2563eb' : '#e9ecef',
                  color: can_afford ? '#ffffff' : '#9ca3af',
                  border: can_afford ? '1px solid #1d4ed8' : '1px solid #ced4da',
                  borderRadius: '4px',
                  cursor: can_afford ? 'pointer' : 'not-allowed',
                  opacity: can_afford ? '1' : '0.6',
                  whiteSpace: 'nowrap',
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  boxShadow: can_afford ? '0 1px 2px rgba(0,0,0,0.05)' : 'none',
                },
                on: can_afford ? { click: click_handler } : {},
              }, label)
          end

          h(:div, {
              style: {
                display: 'flex',
                flexDirection: 'column',
                gap: '0.35rem',
                width: '100%',
                alignItems: 'flex-start',
              },
            }, [
            render_action_row('Select Par Price:', [corp_badge, *buttons]),
          ])
        end

        def resolve_pending_par_corporation(step, _entity = nil)
          return nil unless step

          # 1. Direct corporation pending on step
          if step.respond_to?(:corporation_pending_par) && (corp = step.corporation_pending_par) && (corp.respond_to?(:corporation?) && corp.corporation?)
            return corp
          end

          if step.respond_to?(:par_corporation) && (corp = step.par_corporation) && (corp.respond_to?(:corporation?) && corp.corporation?)
            return corp
          end

          if step.respond_to?(:parring) && (corp = step.parring) && (corp.respond_to?(:corporation?) && corp.corporation?)
            return corp
          end

          # 2. Companies specifically pending par on step (e.g. 1830 B&O in CompanyPendingPar)
          pending_companies = []
          if step.respond_to?(:companies_pending_par) && (cp = step.companies_pending_par)
            pending_companies.concat(Array(cp))
          end

          # If the step is specifically a PendingPar step, also check step.company or step.auctioning
          if step.class.name.to_s.include?('PendingPar')
            %i[company last_company auctioning].each do |m|
              if step.respond_to?(m) && (c = begin; step.send(m); rescue StandardError; nil; end)
                pending_companies.concat(Array(c))
              end
            end
          end

          pending_companies.compact.each do |c|
            abilities = []
            abilities.concat(Array(c.abilities)) if c.respond_to?(:abilities)
            abilities.concat(Array(c.all_abilities)) if c.respond_to?(:all_abilities)

            abilities.each do |a|
              next unless a.respond_to?(:shares)

              Array(a.shares).each do |sh|
                return sh.corporation if sh.respond_to?(:corporation) && sh.corporation && !sh.corporation.ipoed
              end
            end
          end

          # 3. Only if in an auction/draft round with a single auctioning corporation
          if step.respond_to?(:auctioning_corporation) && (corp = step.auctioning_corporation) && (corp.respond_to?(:corporation?) && corp.corporation?)
            return corp
          end

          nil
        end

