        def render_buy_tokens(step, entity)
          return nil unless entity && step

          tokens = if step.respond_to?(:buyable_tokens)
                     step.buyable_tokens(entity) || []
                   elsif step.respond_to?(:available_tokens)
                     step.available_tokens(entity) || []
                   elsif step.respond_to?(:tokens)
                     step.tokens(entity) || []
                   else
                     []
                   end

          return nil if tokens.empty?

          token_cost_fn = lambda do |num|
            if step.respond_to?(:token_cost)
              begin
                step.token_cost(entity) * num
              rescue ArgumentError
                step.token_cost * num
              end
            elsif step.respond_to?(:price_for_tokens)
              step.price_for_tokens(entity, num)
            elsif tokens.first.respond_to?(:price) && tokens.first.price
              tokens.first.price * num
            else
              0
            end
          end

          buttons = tokens.map.with_index(1) do |token, num|
            price = token_cost_fn.call(num)
            price_str = price.positive? ? @game.format_currency(price) : 'Free'
            can_afford = (entity.respond_to?(:cash) ? entity.cash : 0) >= price

            click_handler = lambda {
              process_action(Engine::Action::BuyToken.new(entity, token: token, price: price))
            }

            card_classes = %w[game-card action-buy]
            card_classes << 'clickable' if can_afford
            card = render_railcard(num.to_s, card_classes, (can_afford ? click_handler : nil))

            h(:div, { style: { display: 'inline-flex', alignItems: 'center', gap: '0.3rem', margin: '0 0.2rem' } }, [
              card,
              h(:span, {
                  style: {
                    fontFamily: FONT_MONEY,
                    color: can_afford ? COLOR_MONEY : '#9ca3af',
                    fontWeight: 'bold',
                    fontSize: '0.85rem',
                    whiteSpace: 'nowrap',
                  },
                }, price_str),
            ])
          end

          render_action_row('Number of Tokens to Buy:', buttons)
        end

        def render_buyable_trains(step, entity)
          return nil unless entity && step
          return nil unless step.respond_to?(:buyable_trains)

          step_buyable = begin
            step.buyable_trains(entity) || []
          rescue StandardError
            []
          end

          return nil if step_buyable.empty?

          depot = @game.depot
          train_boxes = []

          buying_power =
            if step.respond_to?(:buying_power)
              begin
                step.buying_power(entity)
              rescue StandardError
                entity.cash
              end
            elsif @game.respond_to?(:buying_power)
              begin
                @game.buying_power(entity)
              rescue StandardError
                entity.cash
              end
            else
              entity.cash
            end

          buying_power = buying_power.to_i

          must_buy =
            begin
              step.respond_to?(:must_buy_train?) &&
                step.must_buy_train?(entity)
            rescue StandardError
              false
            end

          ebuy_active = must_buy

          if step.respond_to?(:ebuy_president_can_contribute?)
            begin
              ebuy_active ||= step.ebuy_president_can_contribute?(entity.owner)
            rescue StandardError
            end
          end

          if step.respond_to?(:president_may_contribute?)
            begin
              ebuy_active ||= step.president_may_contribute?(entity)
            rescue StandardError
            end
          end

          depot_trains = []
          other_trains = []

          step_buyable.each do |train|
            from_depot =
              begin
                train.respond_to?(:from_depot?) && train.from_depot?
              rescue StandardError
                false
              end

            from_depot ||= train.owner == depot if depot

            if from_depot
              depot_trains << train
            else
              other_trains << train
            end
          end

          unique_depot_trains = depot_trains.uniq do |train|
            is_pool =
              depot.respond_to?(:discarded) &&
              depot.discarded.include?(train)

            [is_pool ? :pool : :fresh, train.name]
          end

          unique_depot_trains.each do |train|
            can_buy =
              begin
                !step.respond_to?(:can_buy_train?) ||
                  step.can_buy_train?(entity, train)
              rescue StandardError
                true
              end

            next unless can_buy

            variants = []

            variants = []
            variants_are_engine_filtered = false

            if step.respond_to?(:buyable_train_variants) &&
               train.respond_to?(:variants)
              begin
                allowed_variants =
                  step.buyable_train_variants(train, entity) || []

                raw_variants = train.variants || {}

                raw_variants.each do |name, data|
                  next unless allowed_variants.include?(data)

                  variant_name =
                    if data.respond_to?(:[])
                      data[:name] ||
                        data['name'] ||
                        name
                    else
                      name
                    end

                  variant_price =
                    if data.respond_to?(:[])
                      data[:price] ||
                        data['price'] ||
                        train.price
                    else
                      train.price
                    end

                  variants << {
                    name: variant_name,
                    price: variant_price,
                  }
                end

                variants_are_engine_filtered = true
              rescue StandardError
                variants = []
                variants_are_engine_filtered = false
              end
            end

            if variants.empty? &&
               !variants_are_engine_filtered &&
               train.respond_to?(:names_to_prices)
              begin
                names_to_prices = train.names_to_prices

                if names_to_prices && !names_to_prices.empty?
                  variants = names_to_prices.map do |name, price|
                    {
                      name: name,
                      price: price,
                    }
                  end
                end
              rescue StandardError
                variants = []
              end
            end

            if variants.empty? &&
               !variants_are_engine_filtered &&
               train.respond_to?(:variants)
              begin
                raw_variants = train.variants

                if raw_variants.respond_to?(:each)
                  raw_variants.each do |name, data|
                    variant_name =
                      if data.respond_to?(:[])
                        data[:name] ||
                          data['name'] ||
                          name
                      else
                        name
                      end

                    variant_price =
                      if data.respond_to?(:[])
                        data[:price] ||
                          data['price'] ||
                          train.price
                      else
                        train.price
                      end

                    variants << {
                      name: variant_name,
                      price: variant_price,
                    }
                  end
                end
              rescue StandardError
                variants = []
              end
            end

            if variants.empty? && !variants_are_engine_filtered
              variants = [
                {
                  name: train.name,
                  price: train.price,
                },
              ]
            end

            next if variants.empty?

            is_pool =
              depot.respond_to?(:discarded) &&
              depot.discarded.include?(train)

            source_tag = is_pool ? 'Pool' : 'Bank'

            variants.each do |variant_info|
              if variant_info.respond_to?(:[])
                variant_name =
                  variant_info[:name] ||
                  variant_info['name'] ||
                  train.name

                price =
                  variant_info[:price] ||
                  variant_info['price'] ||
                  train.price
              else
                variant_name = train.name
                price = train.price
              end

              price = price.to_i
              can_afford = price <= buying_power

              if !can_afford && ebuy_active && step.respond_to?(:can_ebuy?)
                can_afford = begin
                  step.can_ebuy?(entity, train) &&
                    (
                      !step.respond_to?(:min_depot_price) ||
                      price == step.min_depot_price
                    )
                rescue StandardError
                  false
                end
              end

              next unless can_afford

              variant_str = variant_name.to_s

              variant_param =
                variant_str == train.name.to_s ? nil : variant_str

              wrapper_id =
                "cmd_train_#{train.id}_#{variant_str.tr('/', '_')}"

              click_handler = lambda do
                remember_card_transfer(
                  kind: :train,
                  item_id: train.id,
                  source_type: (is_pool ? :train_pool : :train_fresh),
                  variant: variant_str,
                  source_selector: "##{wrapper_id}"
                )

                process_action(
                  Engine::Action::BuyTrain.new(
                    entity,
                    train: train,
                    price: price,
                    variant: variant_param
                  )
                )
              end

              card = render_railcard(
                variant_str,
                %w[game-card action-buy clickable card-train],
                click_handler,
                nil,
                nil,
                wrapper_id,
                nil,
                entity: train
              )

              train_boxes << h(
                :div,
                {
                  style: {
                    display: 'inline-flex',
                    flexDirection: 'row',
                    alignItems: 'center',
                    gap: '0.4rem',
                  },
                },
                [
                  card,
                  h(
                    :span,
                    {
                      style: {
                        fontSize: '0.85rem',
                        color: '#475569',
                        fontWeight: 'bold',
                        whiteSpace: 'nowrap',
                      },
                    },
                    source_tag
                  ),
                  h(
                    :span,
                    {
                      style: {
                        fontFamily: FONT_MONEY,
                        color: COLOR_MONEY,
                        fontWeight: 'bold',
                        fontSize: '0.85rem',
                        whiteSpace: 'nowrap',
                      },
                    },
                    @game.format_currency(price)
                  ),
                ]
              )
            end
          end

          operating_player =
            if entity.respond_to?(:player?) && entity.player?
              entity
            elsif entity.respond_to?(:owner)
              entity.owner
            end

          other_trains.each do |train|
            seller = train.owner

            next unless seller
            next if seller == entity

            if operating_player &&
               seller.respond_to?(:owner) &&
               seller.owner != operating_player
              next
            end

            can_buy =
              begin
                !step.respond_to?(:can_buy_train?) ||
                  step.can_buy_train?(entity, train)
              rescue StandardError
                false
              end

            next unless can_buy

            min_price = 1
            max_price = buying_power

            if step.respond_to?(:spend_minmax)
              begin
                min_price, max_price =
                  step.spend_minmax(entity, train)
              rescue StandardError
              end
            elsif step.respond_to?(:max_price)
              begin
                max_price =
                  step.max_price(entity, train)
              rescue StandardError
              end
            end

            next if min_price.nil? || max_price.nil?
            next if max_price < min_price

            wrapper_id =
              "cmd_other_train_#{seller.id}_#{train.id}"

            click_handler = lambda do
              menu_title =
                "Buy #{train.name} from #{seller.name} " \
                "(#{min_price}-#{max_price}):"

              show_price_dialog(
                menu_title,
                min_price,
                max_price,
                min_price,
                lambda do |price_value|
                  status_source_selector =
                    "#train_wrapper_#{seller.id}_#{train.id}"
                  remember_card_transfer(
                    kind: :train,
                    item_id: train.id,
                    source_type: :corporation,
                    source_id: seller.id,
                    variant: train.name,
                    source_selector: status_source_selector
                  )

                  process_action(
                    Engine::Action::BuyTrain.new(
                      entity,
                      train: train,
                      price: price_value
                    )
                  )
                end
              )
            end

            card = render_railcard(
              train.name,
              %w[game-card action-buy clickable card-train],
              click_handler,
              nil,
              nil,
              wrapper_id,
              nil,
              entity: train
            )

            train_boxes << h(
              :div,
              {
                style: {
                  display: 'inline-flex',
                  flexDirection: 'row',
                  alignItems: 'center',
                  gap: '0.4rem',
                },
              },
              [
                card,
                h(
                  :span,
                  {
                    style: {
                      fontSize: '0.85rem',
                      color: '#475569',
                      fontWeight: 'bold',
                      whiteSpace: 'nowrap',
                    },
                  },
                  seller.respond_to?(:id) ? seller.id.to_s : seller.name.to_s
                ),
              ]
            )
          end

          return nil if train_boxes.empty?

          render_action_row('Buy Train:', train_boxes)
        end

        def render_issue_shares(step, entity)
          entity ||= current_entity
          return nil unless entity && step

          player = active_player
          player_actions = player ? actions_for(player).compact.map(&:to_s) : []
          global_actions = step.respond_to?(:current_actions) ? (step.current_actions || []).map(&:to_s) : []
          entity_actions = actions_for(entity).compact.map(&:to_s)

          available_actions = (entity_actions + player_actions + global_actions).uniq

          round_steps = @game.round.respond_to?(:steps) ? (@game.round.steps || []) : []
          issue_step = round_steps.find do |s|
            s.respond_to?(:issuable_shares) || s.respond_to?(:issuable_bundles)
          end || step

          redeem_step = round_steps.find do |s|
            s.respond_to?(:redeemable_shares) || s.respond_to?(:redeemable_bundles)
          end || step

          issuable_bundles = begin
            bundles = []
            if issue_step.respond_to?(:issuable_shares)
              bundles = begin
                issue_step.issuable_shares(entity) || []
              rescue ArgumentError
                issue_step.issuable_shares || []
              end
            elsif issue_step.respond_to?(:issuable_bundles)
              bundles = begin
                issue_step.issuable_bundles(entity) || []
              rescue ArgumentError
                issue_step.issuable_bundles || []
              end
            end
            bundles = @game.issuable_shares(entity) || [] if bundles.empty? && @game.respond_to?(:issuable_shares)

            bundles.compact.map do |raw|
              if defined?(Engine::ShareBundle) && raw.is_a?(Engine::ShareBundle)
                raw
              elsif raw.respond_to?(:to_bundle)
                raw.to_bundle
              else
                Engine::ShareBundle.new(Array(raw))
              end
            end.uniq do |b|
              [b.respond_to?(:percent) ? b.percent : b.shares.size, b.respond_to?(:price) ? b.price : 0]
            end
          rescue StandardError
            []
          end || []

          rows = []

          can_issue = (
            available_actions &
            %w[
            issue
            issue_shares
            reissue_shares
            reissue
            corporate_sell_shares
            sell_shares
            ]
          ).any?

          if issuable_bundles.any? && can_issue
            issue_buttons = issuable_bundles.map do |bundle|
              shares = bundle.shares.flatten.compact
              num =
                if bundle.respond_to?(:num_shares)
                  bundle.num_shares
                else
                  shares.size
                end

              price =
                if bundle.respond_to?(:price)
                  bundle.price
                elsif bundle.respond_to?(:share_price) && bundle.share_price
                  bundle.share_price.price * num
                elsif entity.respond_to?(:share_price) && entity.share_price
                  entity.share_price.price * num
                else
                  0
                end

              share_price =
                if bundle.respond_to?(:share_price) && bundle.share_price
                  bundle.share_price
                elsif entity.respond_to?(:share_price)
                  entity.share_price
                end

              percent = (bundle.percent if bundle.respond_to?(:percent))
              pct_str = percent ? "#{percent}%" : "#{num}S"
              price_str = @game.format_currency(price)

              click_handler = lambda do
                acting_entity =
                  if entity.respond_to?(:corporation?) && entity.corporation?
                    entity
                  else
                    @game.current_entity || current_entity
                  end

                all_actions = (
                  actions_for(acting_entity) +
                  actions_for(entity) +
                  (step.respond_to?(:current_actions) ? (step.current_actions || []) : [])
                ).compact.map(&:to_s).uniq

                action =
                  if all_actions.include?('reissue_shares') && defined?(Engine::Action::ReissueShares)
                    Engine::Action::ReissueShares.new(acting_entity, shares: shares, bundle: bundle)
                  elsif all_actions.include?('reissue') && defined?(Engine::Action::Reissue)
                    Engine::Action::Reissue.new(acting_entity, shares: shares, bundle: bundle)
                  elsif all_actions.include?('issue_shares') && defined?(Engine::Action::IssueShares)
                    Engine::Action::IssueShares.new(acting_entity, shares: shares, bundle: bundle)
                  elsif all_actions.include?('issue') && defined?(Engine::Action::Issue)
                    Engine::Action::Issue.new(acting_entity, shares: shares, bundle: bundle)
                  elsif all_actions.include?('corporate_sell_shares') && defined?(Engine::Action::CorporateSellShares)
                    Engine::Action::CorporateSellShares.new(acting_entity, shares: shares, bundle: bundle)
                  else
                    Engine::Action::SellShares.new(
                      acting_entity,
                      bundle: bundle,
                      shares: shares,
                      share_price: share_price,
                      percent: percent
                    )
                  end

                process_action(action)
              end

              card = render_railcard(
                pct_str,
                %w[game-card action-sell clickable],
                click_handler
              )

              h(
                :div,
                {
                  style: {
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '0.3rem',
                    margin: '0 0.2rem',
                  },
                },
                [
                  card,
                  h(
                    :span,
                    {
                      style: {
                        fontFamily: FONT_MONEY,
                        color: COLOR_MONEY,
                        fontWeight: 'bold',
                        fontSize: '0.85rem',
                        whiteSpace: 'nowrap',
                      },
                    },
                    price_str
                  ),
                ]
              )
            end

            corp_tag = @game.round.stock? ? " (#{entity.name})" : ''
            rows << render_action_row("Issue#{corp_tag}:", issue_buttons)

          end

          redeemable_bundles = begin
            bundles = []
            if redeem_step.respond_to?(:redeemable_shares)
              bundles = begin
                redeem_step.redeemable_shares(entity) || []
              rescue ArgumentError
                redeem_step.redeemable_shares || []
              end
            elsif redeem_step.respond_to?(:redeemable_bundles)
              bundles = begin
                redeem_step.redeemable_bundles(entity) || []
              rescue ArgumentError
                redeem_step.redeemable_bundles || []
              end
            end
            bundles = @game.redeemable_shares(entity) || [] if bundles.empty? && @game.respond_to?(:redeemable_shares)
            if bundles.empty? && redeem_step.respond_to?(:buyable_shares)
              bundles = begin
                redeem_step.buyable_shares(entity) || []
              rescue ArgumentError
                redeem_step.buyable_shares || []
              end
            end

            bundles.compact.map do |raw|
              if defined?(Engine::ShareBundle) && raw.is_a?(Engine::ShareBundle)
                raw
              elsif raw.respond_to?(:to_bundle)
                raw.to_bundle
              else
                Engine::ShareBundle.new(Array(raw))
              end
            end.uniq do |b|
              owner_id = b.respond_to?(:owner) && b.owner.respond_to?(:id) ? b.owner.id : nil
              [owner_id, b.respond_to?(:percent) ? b.percent : b.shares.size, b.respond_to?(:price) ? b.price : 0]
            end
          rescue StandardError
            []
          end || []

          can_redeem = (available_actions & %w[redeem redeem_shares corporate_buy_shares buy_shares]).any?
          if redeemable_bundles.any? && can_redeem
            redeem_buttons = redeemable_bundles.map do |bundle|
              num = if bundle.respond_to?(:num_shares)
                      bundle.num_shares
                    else
                      (bundle.respond_to?(:shares) ? bundle.shares.size : 1)
                    end
              pct_str = bundle.respond_to?(:percent) && bundle.percent ? "#{bundle.percent}%" : "#{num}S"
              price = if bundle.respond_to?(:price)
                        bundle.price
                      elsif bundle.respond_to?(:share_price) && bundle.share_price
                        bundle.share_price.price * num
                      elsif entity.respond_to?(:share_price) && entity.share_price
                        entity.share_price.price * num
                      else
                        0
                      end

              share_price = if bundle.respond_to?(:share_price) && bundle.share_price
                              bundle.share_price
                            elsif entity.respond_to?(:share_price)
                              entity.share_price
                            end

              percent = (bundle.percent if bundle.respond_to?(:percent))

              owner_label = if bundle.respond_to?(:owner) && bundle.owner && bundle.owner != @game.share_pool
                              " (#{bundle.owner.name})"
                            else
                              ''
                            end
              price_str = "#{@game.format_currency(price)}#{owner_label}"
              can_afford = (entity.respond_to?(:cash) ? entity.cash : 0) >= price

              click_handler = lambda do
                acting_entity = entity.respond_to?(:corporation?) && entity.corporation? ? entity : (@game.current_entity || current_entity)
                all_actions = (actions_for(acting_entity) + actions_for(entity) + (step.respond_to?(:current_actions) ? (step.current_actions || []) : [])).compact.map(&:to_s).uniq

                shares = bundle.shares.flatten.compact
                action_kwargs = {
                  bundle: bundle,
                  shares: shares,
                  share_price: share_price,
                  percent: percent,
                }.compact

                action =
                  if all_actions.include?('redeem_shares') && defined?(Engine::Action::RedeemShares)
                    Engine::Action::RedeemShares.new(acting_entity, **action_kwargs)
                  elsif all_actions.include?('redeem') && defined?(Engine::Action::Redeem)
                    Engine::Action::Redeem.new(acting_entity, **action_kwargs)
                  elsif all_actions.include?('corporate_buy_shares') && defined?(Engine::Action::CorporateBuyShares)
                    Engine::Action::CorporateBuyShares.new(acting_entity, **action_kwargs)
                  else
                    Engine::Action::BuyShares.new(acting_entity, **action_kwargs)
                  end

                process_action(action)
              end

              card_classes = %w[game-card action-buy]
              card_classes << 'clickable' if can_afford
              card = render_railcard(pct_str, card_classes, (can_afford ? click_handler : nil))
              h(:div, { style: { display: 'inline-flex', alignItems: 'center', gap: '0.3rem', margin: '0 0.2rem' } }, [
                card,
                h(:span, { style: { fontFamily: FONT_MONEY, color: can_afford ? COLOR_MONEY : '#9ca3af', fontWeight: 'bold', fontSize: '0.85rem', whiteSpace: 'nowrap' } }, price_str),
              ])
            end

            corp_tag = @game.round.stock? ? " (#{entity.name})" : ''
            rows << render_action_row("Redeem#{corp_tag}:", redeem_buttons)
          elsif (available_actions & %w[redeem redeem_shares]).any?
            rows << render_action_row('Redeem:', [
              h(:span, { style: { color: '#888', fontStyle: 'italic', fontSize: '0.85rem' } }, 'No redeemable shares available'),
            ])
          end
          return nil if rows.empty?

          h(:div, { style: { display: 'flex', flexDirection: 'column', gap: '0.25rem', width: '100%' } }, rows.compact)
        end

        def saved_window_geometry
          geom = %x{
            (function() {
              var res = {
                top: '80px',
                right: '20px',
                left: 'auto',
                width: '400px',
                height: '550px'
              };
              try {
                var savedPos = JSON.parse(localStorage.getItem('action_window_pos') || '{}');
                var savedSize = JSON.parse(localStorage.getItem('action_window_size') || '{}');

                var w = parseFloat(savedSize.width);
                var h = parseFloat(savedSize.height);
                var l = parseFloat(savedPos.left);
                var t = parseFloat(savedPos.top);

                var maxW = Math.max(300, (window.innerWidth || 1200) - 20);
                var maxH = Math.max(160, (window.innerHeight || 800) - 20);

                if (isFinite(w) && w >= 300) {
                  w = Math.min(w, maxW);
                  res.width = Math.round(w) + 'px';
                } else {
                  w = 400;
                }

                if (isFinite(h) && h >= 160) {
                  h = Math.min(h, maxH);
                  res.height = Math.round(h) + 'px';
                } else {
                  h = 550;
                }

                if (isFinite(l)) {
                  var maxLeft = Math.max(10, (window.innerWidth || 1200) - w - 10);
                  l = Math.max(10, Math.min(l, maxLeft));
                  res.left = Math.round(l) + 'px';
                  res.right = 'auto';
                }

                if (isFinite(t)) {
                  var maxTop = Math.max(0, (window.innerHeight || 800) - 40);
                  t = Math.max(0, Math.min(t, maxTop));
                  res.top = Math.round(t) + 'px';
                }
              } catch (e) {}
              return res;
            })()
          }
          Native(geom)
        end

        def apply_saved_geometry_to_dom
          %x{
            try {
              var hud = document.getElementById('action_floating_window');
              if (!hud) return;

              var savedPos = JSON.parse(localStorage.getItem('action_window_pos') || '{}');
              var savedSize = JSON.parse(localStorage.getItem('action_window_size') || '{}');

              var width = parseFloat(savedSize.width);
              var height = parseFloat(savedSize.height);
              var left = parseFloat(savedPos.left);
              var top = parseFloat(savedPos.top);

              if (isFinite(width)) {
                width = Math.max(300, Math.min(width, Math.max(300, window.innerWidth - 20)));
                hud.style.width = Math.round(width) + 'px';
                hud.style.maxWidth = 'none';
              }

              if (isFinite(height)) {
                height = Math.max(160, Math.min(height, Math.max(160, window.innerHeight - 20)));
                hud.style.height = Math.round(height) + 'px';
                hud.style.maxHeight = 'none';
              }

              var currentWidth = hud.getBoundingClientRect().width || width || 400;

              if (isFinite(left)) {
                left = Math.max(10, Math.min(left, Math.max(10, window.innerWidth - currentWidth - 10)));
                hud.style.left = Math.round(left) + 'px';
                hud.style.right = 'auto';
              }

              if (isFinite(top)) {
                top = Math.max(0, Math.min(top, Math.max(0, window.innerHeight - 40)));
                hud.style.top = Math.round(top) + 'px';
              }
            } catch (err) {
              console.warn('Could not restore action window position or size:', err);
            }
          }
        end

