        def remember_card_transfer(kind:, item_id:, source_type:, source_id: nil, variant: nil, source_selector: nil)
          transfer = {
            kind: kind.to_s,
            item_id: item_id.to_s,
            source_type: source_type.to_s,
            source_id: source_id&.to_s,
            variant: variant&.to_s,
          }

          %x{
            if (typeof window !== 'undefined') {
              window._railcard_last_transfer_time = Date.now();
              window._railcard_pending_transfer = #{transfer};

              var selector = String(#{source_selector} || '').trim();

              if (selector) {
                window._railcard_pending_source = selector;

                var el = null;
                var dashboardRoot = document.getElementById('viz-master-frame');

                if (selector.charAt(0) === '#') {
                  var spaceIdx = selector.indexOf(' ');
                  var rawId = spaceIdx === -1 ? selector.substring(1) : selector.substring(1, spaceIdx);
                  el = document.getElementById(rawId);
                }

                if (!el) {
                  try {
                    el = dashboardRoot ? dashboardRoot.querySelector(selector) : null;
                  } catch (err) {
                    el = null;
                  }
                }

                if (el) {
                  var card = (el.matches && el.matches('.game-card')) ? el : (el.querySelector ? el.querySelector('.game-card') : null);

                  if (!card || card.id === 'bank' || card.id === 'extra_cards') {
                    window._railcard_pending_source_rect = null;
                    return;
                  }

                  var r = card.getBoundingClientRect();
                  window._railcard_pending_source_rect = {
                    left: r.left,
                    top: r.top,
                    width: r.width,
                    height: r.height
                  };
                }
              }
            }
          }
        end

        def remaining_subsidiary_cost(step, entity)
          return nil unless step

          %i[remaining remaining_cash remaining_cost needed_cash cash_owed cash_needed cost amount].each do |m|
            next unless step.respond_to?(m)

            val = begin
              step.send(m)
            rescue ArgumentError
              begin; step.send(m, entity); rescue StandardError; nil; end
            rescue StandardError
              nil
            end
            return val.to_i if val.is_a?(Numeric)
          end

          if step.respond_to?(:winning_bid) && step.winning_bid
            wb = step.winning_bid
            bid_val = wb.respond_to?(:price) ? wb.price : wb.to_i
            corp = step.respond_to?(:corporation) ? step.corporation : nil
            assigned_val = corp&.companies ? corp.companies.sum { |c| c.value || 0 } : 0
            return [bid_val - assigned_val, 0].max
          end

          nil
        end

