        # Deterministically checks whether clicking the Progress Control will finish
        # the player's current turn (no subsequent steps for this entity, and control
        # does not immediately stay with the same player).
        def will_end_player_turn?(step, entity, phase, _actions)
          return false unless entity && step && @game.round

          # 1. Stock Round: Passing in a stock round always finishes the player's turn
          return phase != :par if @game.round.respond_to?(:stock?) && @game.round.stock?

          # 2. Operating Round: Check if any subsequent step in the round will still
          #    activate/block for this same entity after the current step finishes.
          if @game.round.respond_to?(:operating?) && @game.round.operating? && @game.round.respond_to?(:steps)
            steps = @game.round.steps || []
            cur_idx = steps.index(step)
            return false unless cur_idx

            remaining_steps = steps[(cur_idx + 1)..-1] || []

            # Exclude passive company-ability steps that stay open all OR unless they are the only thing left
            has_next_step_for_entity = remaining_steps.any? do |s|
              next false if s.respond_to?(:passed?) && s.passed?
              next false if /Special|Ability|TrackAndToken/i.match?(s.class.name)

              s_actions = begin
                s.actions(entity)
              rescue StandardError
                []
              end
              s_actions && !s_actions.empty?
            end

            return false if has_next_step_for_entity

            # Also check if Dividend will unlock BuyTrain next (since BuyTrain.actions(entity)
            # only activates once Dividend is completed)
            if phase == :dividend
              will_unlock_train_or_post = remaining_steps.any? do |s|
                (s.is_a?(Engine::Step::BuyTrain) && (!s.respond_to?(:can_buy_train?) || s.can_buy_train?(entity))) ||
                  (s.respond_to?(:buyable_companies) && s.buyable_companies(entity)&.any?)
              end
              return false if will_unlock_train_or_post
            end

            # If no steps remain for this corporation, check if the NEXT operating corporation
            # belongs to the exact same player (if so, the player's turn continues!).
            if @game.round.respond_to?(:entities) && @game.round.respond_to?(:entity_index)
              next_ent = @game.round.entities[@game.round.entity_index + 1]
              return false if next_ent && active_player && next_ent.respond_to?(:owner) && next_ent.owner == active_player
            end

            return true
          end

          false
        rescue StandardError
          false
        end

        def render_command_content
          step = @game.round.active_step
          entity = current_entity
          entity_id = entity&.id

          price_dialog_style = h(:style, {}, '
            #viz-master-frame .modal-overlay,
            #viz-master-frame .dialog-overlay,
            #viz-master-frame .price-dialog-overlay,
            #viz-master-frame .snabberb-modal-overlay {
              background: transparent !important;
              background-color: transparent !important;
              backdrop-filter: none !important;
            }

            /* Action Hub manifesto: objects retain identity; controls show meaning. */
            #action_floating_window button {
              transition: background-color 120ms ease, border-color 120ms ease,
                          box-shadow 120ms ease, filter 120ms ease;
            }
            #action_floating_window button:hover:not(:disabled) {
              filter: brightness(0.96);
            }
            #action_floating_window button:focus-visible,
            #action_floating_window .clickable:focus-visible {
              outline: 3px solid rgba(37, 99, 235, 0.28);
              outline-offset: 2px;
            }
            #action_floating_window .action-buy {
              border: 3px solid #15803d !important;
              box-shadow: 0 0 0 1px rgba(21, 128, 61, 0.14) !important;
            }
            #action_floating_window .action-sell {
              border: 3px solid #dc2626 !important;
              box-shadow: 0 0 0 1px rgba(220, 38, 38, 0.14) !important;
            }
          ')

          # Invalidate cached routes when undo/redo reconstructs the game.
          if @cmd_route_game_instance && !@cmd_route_game_instance.equal?(@game)
            store(:routes, [], skip: true)
            store(:selected_route, nil, skip: true)
            store(:last_routed_action_id, nil, skip: true)
            store(:cmd_router_generation, @cmd_router_generation.to_i + 1, skip: true)
            store(:cmd_router_running, false, skip: true)
          end
          store(:cmd_route_game_instance, @game, skip: true)

          if Lib::Storage['cmd_last_entity_id']&.to_s != entity_id&.to_s
            Lib::Storage['cmd_last_entity_id'] = entity_id
            @routes = []
            store(:routes, @routes, skip: true)
            store(:show_manual_routes, false, skip: true)
            store(:selected_company, nil, skip: true)
          end

          last_action =
            (@game.raw_actions.last if @game.respond_to?(:raw_actions) && @game.raw_actions)

          last_action_id = if last_action.is_a?(Hash)
                             last_action['id'] || last_action[:id] || 0
                           elsif last_action.respond_to?(:id)
                             last_action.id
                           elsif @game_data && @game_data['actions']
                             @game_data['actions'].last&.fetch('id', 0) || 0

                           else
                             0
                           end

          actions = actions_for(entity)

          is_draft = step&.class&.name =~ /Draft/i ||
                             (step_description(step) =~ /Draft/i) ||
                             (@game.respond_to?(:round) && @game.round.class.name =~ /Draft/i)

          is_home_token = home_token_step?(step, actions)

          phase = :waiting
          if actions.include?('lay_tile')
            phase = :build_track
          elsif is_home_token
            phase = :home_token
          elsif actions.include?('place_token')
            phase = :place_token
          elsif actions.include?('run_routes')
            phase = :run_routes
          elsif actions.include?('dividend') || actions.include?('payout') || actions.include?('withhold') || actions.include?('half') || actions.include?('split')
            phase = :dividend
          elsif actions.include?('buy_train')
            phase = :buy_train
          elsif actions.include?('discard_train')
            phase = :discard_train
          elsif actions.include?('buy_token')
            phase = :buy_token
          elsif actions.include?('issue_shares') || actions.include?('reissue_shares') || actions.include?('reissue')
            phase = :issue_shares
          elsif actions.include?('redeem_shares') || actions.include?('redeem')
            phase = :redeem
          elsif actions.include?('par') && resolve_pending_par_corporation(step, entity)
            phase = :par

          elsif actions.include?('corporate_buy_shares') || actions.include?('buy_shares')
            phase = :buy_shares
          elsif is_draft
            phase = :choose
          elsif actions.include?('choose')
            phase = :choose
          elsif actions.include?('bid')
            is_acq = @game.round.class.name =~ /Acquisition|Merger/i ||
                     step&.class&.name =~ /Acquire|Acquisition/i ||
                     (step.respond_to?(:description) && step.description =~ /Acquire/i)
            phase = is_acq ? :acquisition : :bid
          elsif actions.include?('assign')
            phase = :assign
          elsif actions.include?('merge') || actions.include?('convert')
            phase = :merge
          elsif actions.include?('take_loan') || actions.include?('payoff_loan')
            phase = :loan
          end

          player_name = entity&.owner&.name || ''

          if entity.respond_to?(:color)
            bg_color = entity.color || '#4169e1'
            text_color = entity.text_color || 'white'
          else
            bg_color = '#333333'
            text_color = 'white'
            player_name = entity&.name || ''
          end

          base_revenue = 0
          if active_routes.any? && !@cmd_router_running
            active_routes.each do |r|
              base_revenue += r.revenue if r.chains.any?
            rescue Engine::GameError, StandardError
            end
          end
          if phase == :dividend && base_revenue.zero? && entity.respond_to?(:operating_history)
            operating = entity.operating_history || {}
            base_revenue = (operating[operating.keys.max]&.revenue || 0).to_i
          end

          storage_key = "rev_override_#{entity&.id}"
          last_base_key = "last_base_rev_#{entity&.id}"
          if Lib::Storage[last_base_key]&.to_i != base_revenue
            Lib::Storage[storage_key] = base_revenue
            Lib::Storage[last_base_key] = base_revenue
          end

          current_revenue = Lib::Storage[storage_key].to_i
          formatted_revenue = @game.respond_to?(:format_revenue_currency) ? @game.format_revenue_currency(current_revenue) : @game.format_currency(current_revenue)

          game_finished = @game.finished

          player_display_name = active_player&.name || (entity.respond_to?(:name) ? entity.name : nil) || player_name
          zone_1 = render_operating_identity_panel(entity, player_display_name, bg_color, text_color)
          show_manual_routes = @show_manual_routes || Lib::Storage['cmd_manual_routes'] == true || Lib::Storage['cmd_manual_routes'] == 'true'
          zone_2_content = []

          # Always expose map-based OR possibilities in the Action Hub. Some games
          # use specialised Operating round subclasses, so this belongs at the
          # command-content level rather than inside Engine::Round::Operating dispatch.
          is_operating_round = (@game.round.respond_to?(:operating?) && @game.round.operating?) ||
                               clean_round_name == 'Operating Round'
          if !game_finished && is_operating_round
            map_possibilities = []
            map_possibilities << 'Lay tile' if actions.include?('lay_tile')
            map_possibilities << 'Lay token' if actions.include?('place_token')
            if map_possibilities.any?
              zone_2_content << render_possibility_reminder(
                'Operating Round Possible Actions',
                map_possibilities,
                hint: 'Use the highlighted locations on the map.'
              )
            end
          end

          if game_finished
            zone_2_content << h(:div, {
                                  style: {
                                    width: '100%',
                                    height: '100%',
                                    display: 'flex',
                                    flexDirection: 'row',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    gap: '0.75rem',
                                  },
                                }, [
              h(:strong, { style: { fontSize: '1rem', color: '#0f172a' } }, 'End of Game'),
              h(:button, {
                  style: {
                    height: '1.65rem',
                    padding: '0 12px',
                    fontSize: '0.82rem',
                    fontWeight: 'bold',
                    backgroundColor: '#ffffff',
                    color: '#334155',
                    border: '1px solid #94a3b8',
                    borderRadius: '4px',
                    cursor: 'pointer',
                  },
                  on: {
                    click: lambda {
                      Lib::Storage['show_results_overlay'] = true
                      update
                    },
                  },
                }, 'Show Results'),
              (Lib::Storage['show_results_overlay'] ? h(View::Game::Dashboard::ResultsOverlay, game: @game) : nil),
            ].compact)
          end

          if !game_finished && phase == :run_routes
            if @cmd_router_running
              zone_2_content << h(:div, { style: { padding: '0.2rem', textAlign: 'center', color: '#666', fontStyle: 'italic', fontSize: '0.9rem' } }, '🔄 Computing optimal network tracks...')
            elsif show_manual_routes
              zone_2_content << render_action_row('Revenue:', [
                h(:div, { style: { fontSize: '1.2rem', fontWeight: 'bold', color: COLOR_MONEY, fontFamily: FONT_MONEY, minWidth: '4.5rem', textAlign: 'center', height: '1.8rem', display: 'inline-flex', alignItems: 'center', justifyContent: 'center' } }, formatted_revenue),
                h(:button, {
                    style: {
                      padding: '0 8px',
                      height: '1.8rem',
                      fontSize: '0.8rem',
                      fontWeight: 'bold',
                      backgroundColor: '#ffffff',
                      color: '#334155',
                      border: '1px solid #94a3b8',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      marginLeft: '0.4rem',
                      display: 'inline-flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                    },
                    on: {
                      click: lambda {
                        if (@routes.nil? || @routes.empty?) && entity
                          @routes = @game.routes_for(entity)
                          store(:routes, @routes)
                        end
                        target_route = @selected_route || @routes&.first
                        store(:selected_route, target_route) if target_route
                        store(:show_manual_routes, true)
                        Lib::Storage['cmd_manual_routes'] = true
                        update
                      },
                    },
                  }, 'Close Manual'),
              ])
            else
              spinner_items = [
                h(:button, {
                    style: { width: '1.8rem', height: '1.8rem', fontSize: '1.1rem', fontWeight: 'bold', cursor: 'pointer', backgroundColor: '#e0e0e0', border: '1px solid #999', borderRadius: '4px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', padding: '0', lineHeight: '1' },
                    on: {
                      click: lambda {
                        Lib::Storage[storage_key] = [current_revenue - 10, 0].max
                        update
                      },
                    },
                  }, '-'),
                h(:div, { style: { fontSize: '1.2rem', fontWeight: 'bold', color: COLOR_MONEY, fontFamily: FONT_MONEY, minWidth: '4.5rem', textAlign: 'center', height: '1.8rem', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', lineHeight: '1' } }, formatted_revenue),
                h(:button, {
                    style: { width: '1.8rem', height: '1.8rem', fontSize: '1.1rem', fontWeight: 'bold', cursor: 'pointer', backgroundColor: '#e0e0e0', border: '1px solid #999', borderRadius: '4px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', padding: '0', lineHeight: '1' },
                    on: {
                      click: lambda {
                        Lib::Storage[storage_key] = current_revenue + 10
                        update
                      },
                    },
                  }, '+'),
                h(:button, {
                    style: {
                      padding: '0 8px',
                      height: '1.8rem',
                      fontSize: '0.8rem',
                      fontWeight: 'bold',
                      backgroundColor: '#ffffff',
                      color: '#334155',
                      border: '1px solid #94a3b8',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      marginLeft: '0.4rem',
                      display: 'inline-flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      lineHeight: '1',
                    },
                    on: {
                      click: lambda {
                        store(:show_manual_routes, true)
                        Lib::Storage['cmd_manual_routes'] = true
                        update
                      },
                    },
                  }, 'Calculate Manually'),
              ]

              zone_2_content << render_action_row('Revenue:', spinner_items)
            end
          elsif phase == :dividend
            raw_options = if step.respond_to?(:dividend_options)
                            step.dividend_options(entity)
                          elsif step.respond_to?(:dividend_types)
                            step.dividend_types
                          else
                            []
                          end
            options = (raw_options.is_a?(Hash) ? raw_options.keys : Array(raw_options)).map(&:to_s)
            half_kind = options.include?('split') ? 'split' : 'half'

            zone_2_content << h(:div, { style: { display: 'flex', flexDirection: 'row', justifyContent: 'center', gap: '0.5rem', width: '100%', maxWidth: '520px', margin: '0 auto' } }, [
              (h(:button, { style: { flex: '1', padding: '0.45rem 0.6rem', fontSize: '1.1rem', fontWeight: 'bold', backgroundColor: '#2563eb', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }, on: { click: -> { process_action(Engine::Action::Dividend.new(entity, kind: 'payout', extra_revenue: current_revenue - base_revenue)) } } }, 'Pay Out Full') if actions.include?('payout') || options.include?('payout') || actions.include?('dividend')),
              (h(:button, { style: { flex: '1', padding: '0.45rem 0.6rem', fontSize: '1.1rem', fontWeight: 'bold', backgroundColor: '#2563eb', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }, on: { click: -> { process_action(Engine::Action::Dividend.new(entity, kind: 'withhold', extra_revenue: current_revenue - base_revenue)) } } }, 'Hold Revenue') if actions.include?('withhold') || options.include?('withhold') || actions.include?('dividend')),
              (h(:button, { style: { flex: '1', padding: '0.45rem 0.6rem', fontSize: '1.1rem', fontWeight: 'bold', backgroundColor: '#2563eb', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }, on: { click: -> { process_action(Engine::Action::Dividend.new(entity, kind: half_kind, extra_revenue: current_revenue - base_revenue)) } } }, 'Split / Half') if actions.include?('half') || actions.include?('split') || options.include?('half') || options.include?('split')),
            ].compact)
          end

          unless game_finished
            ground_truth_actions = begin
              render_ground_truth_actions(actions, step)
            rescue StandardError, NotImplementedError => e
              `console.error("Dashboard command action rendering failed:", #{e.message}, #{e.backtrace})`

              h(
                :div,
                {
                  attrs: { class: 'dashboard-command-render-fallback' },
                  style: {
                    width: '100%',
                    padding: '0.35rem',
                    color: '#64748b',
                    fontSize: '0.85rem',
                    fontStyle: 'italic',
                  },
                },
                'No dashboard action controls available for this step.'
              )
            end

            zone_2_content << ground_truth_actions if ground_truth_actions

          end
          zone_2 = h(:div, {
                       style: {
                         flex: '1 1 auto',
                         width: '100%',
                         display: 'flex',
                         flexDirection: 'column',
                         alignItems: 'stretch',
                         justifyContent: 'flex-start',
                         padding: '0.85rem 1rem',
                         boxSizing: 'border-box',
                         overflowY: 'auto',
                         backgroundColor: '#ffffff',
                       },
                     }, [
              h(:div, {
                  style: {
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '0.55rem',
                    width: '100%',
                    boxSizing: 'border-box',
                  },
                }, zone_2_content.compact),
            ])
          advance_text = 'Pass'
          advance_color = '#e0e0e0'
          advance_text_color = '#a0a0a0'
          advance_disabled = true
          advance_action = -> {}

          if actions.include?('pass') && !emergency_train_sale_context?(step, entity)
            advance_disabled = false

            advance_action = -> { process_action(Engine::Action::Pass.new(entity)) }

            case phase
            when :build_track then advance_text = 'Skip'
            when :place_token then advance_text = 'Skip'
            when :buy_train then advance_text = 'Done'
            when :discard_train then advance_text = 'Done'
            when :issue_shares then advance_text = 'Skip'
            when :redeem then advance_text = 'Skip'
            when :par then advance_text = 'Skip'
            when :merge then advance_text = 'Done / Pass'
            when :loan then advance_text = 'Done'
            when :buy_shares then advance_text = 'Done'
            when :choose, :bid, :acquisition then advance_text = is_draft ? 'Pass / Blank' : 'Pass'
            when :assign
              offer_for_sale = begin
                step.respond_to?(:merger_auto_pass_entity) && step.merger_auto_pass_entity
              rescue StandardError
                nil
              end
              if offer_for_sale && step&.class&.name =~ /Acquire|Acquisition/i
                advance_text = 'Pass (Do Not Offer)'
              else
                rem_val = remaining_subsidiary_cost(step, entity)
                advance_text = rem_val&.positive? ? "OK (Pay #{@game.format_currency(rem_val)})" : 'OK'
              end
            end
          elsif phase == :run_routes && actions.include?('run_routes') && !@cmd_router_running
            advance_disabled = false

            advance_text = "Submit #{formatted_revenue}"
            advance_action = lambda {
              routes_to_submit = active_routes
              process_action(Engine::Action::RunRoutes.new(
                entity,
                routes: routes_to_submit,
                extra_revenue: @game.extra_revenue(entity, routes_to_submit) + (current_revenue - base_revenue)
              ))
            }
          elsif phase == :dividend
            dividend_options = step.respond_to?(:dividend_options) ? step.dividend_options(entity).map(&:to_s) : []
            if actions.include?('payout') || dividend_options.include?('payout') || actions.include?('dividend')
              advance_disabled = false

              advance_text = 'Pay Out Full'
              advance_action = lambda {
                process_action(Engine::Action::Dividend.new(
                  entity,
                  kind: 'payout',
                  extra_revenue: current_revenue - base_revenue
                ))
              }
            end
          end
          unless advance_disabled
            if my_turn?
              advance_color = '#2563eb'
              advance_text_color = '#ffffff'
            else
              advance_color = '#808080'
              advance_text_color = '#ffffff'

              `console.log("NOT MY TURN", #{active_player&.name}, #{@user&.dig('name')})`
            end
          end

          ends_turn = !advance_disabled && my_turn? && will_end_player_turn?(step, entity, phase, actions)
          button_label = ends_turn ? "#{advance_text} · End Turn" : advance_text
          advance_tooltip = if ends_turn
                              'Clicking this ends your turn (Action Hub will close and you cannot undo once the next player acts).'
                            end

          advance_children = if ends_turn
                               [
                                 h(:span, {
                                     style: {
                                       display: 'inline-flex',
                                       alignItems: 'center',
                                       justifyContent: 'center',
                                       width: '1.25rem',
                                       height: '1.25rem',
                                       borderRadius: '50%',
                                       backgroundColor: '#fbbf24',
                                       color: '#0f172a',
                                       fontWeight: '900',
                                       fontSize: '0.88rem',
                                       lineHeight: '1',
                                       marginRight: '0.45rem',
                                       flexShrink: '0',
                                       boxShadow: '0 0 0 2px rgba(255,255,255,0.35)',
                                     },
                                   }, '!'),
                                 h(:span, "#{advance_text} · End Turn"),
                               ]
                             else
                               [advance_text]
                             end

          advance_tooltip = if ends_turn
                              'Clicking this ends your turn (Action Hub will close and you cannot undo once the next player acts).'
                            end

          has_abilities = !game_finished && !actions.include?('choose') && entity && (@game.companies || []).any? do |c|
            next false if c.respond_to?(:closed?) && c.closed?

            is_owner = c.owner == entity || (entity.respond_to?(:owner) && c.owner && c.owner == entity.owner)
            next false unless is_owner

            abilities = (c.respond_to?(:all_abilities) ? c.all_abilities : []).dup
            abilities.concat(c.abilities || []) if c.respond_to?(:abilities)

            abilities.any? do |a|
              next false if a.respond_to?(:passive?) && a.passive?
              next false if a.respond_to?(:passive) && a.passive
              next false if a.respond_to?(:closed?) && a.closed?
              next false if a.respond_to?(:used?) && a.used?

              true
            end
          end

          zone_3 = h(:div, { style: { flex: '0 0 auto', display: 'flex', flexDirection: 'column', padding: '0.65rem 1rem', boxSizing: 'border-box', gap: '0.65rem', width: '100%', backgroundColor: '#f8fafc', borderTop: '1px solid #e2e8f0' } }, [
            (render_zone3_abilities(entity) if has_abilities),
            h(:div, { style: { display: 'flex', flexDirection: 'row', alignItems: 'center', justifyContent: 'flex-start', gap: '0.6rem', width: '100%' } }, [
              h(:div, {
                  attrs: { class: 'cmd-undo-redo-wrapper' },
                  style: { flex: '0 0 auto' },
                }, [
                h(:style, {}, '
                  .cmd-undo-redo-wrapper #history,
                  .cmd-undo-redo-wrapper .history,
                  .cmd-undo-redo-wrapper input,
                  .cmd-undo-redo-wrapper button:not(#undo):not(#redo) {
                    display: none !important;
                  }
                  .cmd-undo-redo-wrapper,
                  .cmd-undo-redo-wrapper * {
                    box-sizing: border-box !important;
                  }
                  .cmd-undo-redo-wrapper,
                  .cmd-undo-redo-wrapper div,
                  .cmd-undo-redo-wrapper #history_and_undo,
                  .cmd-undo-redo-wrapper .history_and_undo {
                    display: flex !important;
                    flex-direction: row !important;
                    flex-wrap: nowrap !important;
                    align-items: center !important;
                    justify-content: flex-start !important;
                    gap: 0.35rem !important;
                    width: auto !important;
                    min-width: auto !important;
                    max-width: max-content !important;
                    margin: 0 !important;
                    padding: 0 !important;
                    border: none !important;
                    background: transparent !important;
                    box-shadow: none !important;
                  }
                  .cmd-undo-redo-wrapper button#undo,
                  .cmd-undo-redo-wrapper button#redo {
                    display: inline-flex !important;
                    flex: 0 0 3.2rem !important;
                    width: 3.2rem !important;
                    min-width: 3.2rem !important;
                    max-width: 3.2rem !important;
                    height: 2.2rem !important;
                    min-height: 2.2rem !important;
                    max-height: 2.2rem !important;
                    justify-content: center !important;
                    align-items: center !important;
                    padding: 0 4px !important;
                    font-size: 0.85rem !important;
                    font-weight: bold !important;
                    background-color: #ffffff !important;
                    color: #212529 !important;
                    border: 1px solid #ced4da !important;
                    border-radius: 4px !important;
                    cursor: pointer !important;
                    margin: 0 !important;
                    line-height: 1 !important;
                    box-shadow: 0 1px 2px rgba(0,0,0,0.05) !important;
                  }
                  .cmd-undo-redo-wrapper button#undo:hover:not(:disabled),
                  .cmd-undo-redo-wrapper button#redo:hover:not(:disabled) {
                    background-color: #e9ecef !important;
                    border-color: #adb5bd !important;
                  }
                  .cmd-undo-redo-wrapper button#undo:disabled,
                  .cmd-undo-redo-wrapper button#redo:disabled {
                    background-color: #f1f3f5 !important;
                    color: #adb5bd !important;
                    cursor: not-allowed !important;
                    opacity: 0.6 !important;
                    box-shadow: none !important;
                  }
                '),
                h(HistoryAndUndo, last_action_id: last_action_id),
              ]),
              h(:button, { attrs: { id: 'btn-action-hub-history', type: 'button', title: 'Game History' }, style: { height: '2.2rem', padding: '0 10px', fontWeight: 'bold', cursor: 'pointer' }, on: { click: -> { store(:show_history_overlay, @show_history_overlay != true) } } }, 'History'),
              h(:div, { style: { marginLeft: 'auto' } }),
              h(:button, {
                  style: {
                    flex: '0 0 auto',
                    minWidth: '7.5rem',
                    height: '2.35rem',
                    padding: '0 1.1rem',
                    fontSize: '0.9rem',
                    fontWeight: 'bold',
                    backgroundColor: advance_color,
                    color: advance_text_color,
                    border: advance_disabled ? '1px solid #cbd5e1' : '1px solid #1d4ed8',
                    borderRadius: '6px',
                    cursor: advance_disabled ? 'not-allowed' : 'pointer',
                    boxShadow: advance_disabled ? 'none' : '0 2px 5px rgba(15,23,42,0.18)',
                    whiteSpace: 'nowrap',
                  },
                  attrs: {
                    id: 'btn-action-hub-default',
                    disabled: advance_disabled,
                    title: advance_tooltip,
                  }.compact,
                  on: { click: advance_action },
                }, button_label),
            ]),
          ].compact)
          current_action_id = @game.respond_to?(:raw_actions) && @game.raw_actions ? @game.raw_actions.size : last_action_id
          routed_token = "#{entity&.id}_#{current_action_id}"

          # 1. Never compute routes while scrubbing or reviewing historical actions
          is_viewing_history = !Lib::Params['action'].nil? && !Lib::Params['action'].to_s.empty?
          is_game_1862 = @game.class.name.to_s.include?('1862') || @game_data&.dig('title').to_s.include?('1862')

          if phase == :run_routes && @last_routed_action_id != routed_token && !@cmd_router_running && !is_viewing_history
            store(:last_routed_action_id, routed_token, skip: true)

            # In 1862, bypass auto-router to avoid intractable combinatorial lock
            if is_game_1862
              store(:show_manual_routes, true, skip: true)
              Lib::Storage['cmd_manual_routes'] = true
            else
              store(:cmd_router_running, true, skip: false)

              train_count = entity.respond_to?(:trains) ? entity.trains.size : 1
              has_d_train = entity.respond_to?(:trains) && entity.trains.any? { |t| t.name.to_s.upcase.include?('D') }

              # Preserve existing routes if company already has multi-train routes running
              routes_seed = []
              if train_count < 3 && !has_d_train
                @routes.each(&:reset!) if @routes&.any?
                @game.reset_adjustable_trains!(entity, @routes) if @game.respond_to?(:reset_adjustable_trains!)
                @routes = []
                store(:routes, @routes, skip: true)
                store(:selected_route, nil, skip: true)
              else
                routes_seed = @routes.select { |r| r.chains.any? }
              end

              router_generation = @cmd_router_generation.to_i
              router_game = @game

              lambda {
                `setTimeout(function() {`
                begin
                  next unless @cmd_router_generation.to_i == router_generation &&
                              @game.equal?(router_game)

                  flash_cb = lambda do |msg|
                    store(:flash_opts, { message: msg }, skip: false)
                  end
                  router = Engine::AutoRouter.new(@game, flash_cb)
                  router_entity = @game.current_entity || entity

                  # Strict timeout: 4s path + 6s route = 10s maximum total cutoff
                  p_timeout = 4
                  r_timeout = 6

                  router.compute(
                    router_entity,
                    routes: routes_seed,
                    path_timeout: p_timeout,
                    route_timeout: r_timeout,
                    callback: lambda do |computed_routes|
                      next unless @cmd_router_generation.to_i == router_generation &&
                                  @game.equal?(router_game)

                      routes_list = computed_routes || routes_seed || []
                      store(:routes, routes_list, skip: true)
                      store(:selected_route, routes_list.first, skip: true)

                      auto_rev = 0
                      routes_list.each do |r|
                        auto_rev += r.revenue if r.chains.any?
                      rescue Engine::GameError, StandardError
                      end

                      storage_key = "rev_override_#{entity&.id}"
                      last_base_key = "last_base_rev_#{entity&.id}"
                      Lib::Storage[storage_key] = auto_rev
                      Lib::Storage[last_base_key] = auto_rev

                      store(:cmd_router_running, false)
                      update
                    end
                  )
                rescue StandardError
                  store(:cmd_router_running, false)
                  update
                end
                `}, 50);`
              }.call
            end
          end

          overlays = []
          overlays << h(View::Game::Dashboard::ManualRouteOverlay, game: @game, entity: entity, routes: @routes, selected_route: @selected_route) if show_manual_routes

          h(:div, {
              attrs: { id: 'dashboard-command-panel-bar' },
              style: {
                display: 'flex',
                flexDirection: 'column',
                width: '100%',
                height: '100%',
                boxSizing: 'border-box',
                backgroundColor: '#fff',
                position: 'relative',
                zIndex: 99_999,
                overflow: 'hidden',
                pointerEvents: 'auto',
              },
            }, [
              price_dialog_style,
              zone_1,
              zone_2,
              zone_3,
              *overlays,
            ].compact)
        end
      end
    end
  end
end

