module View
  module Game
    module StockMarketAnimation
      def self.capture_pre_render
        %x{
          window._stockMarketTokens = window._stockMarketTokens || {};

          var dashboardRoot = window.document.getElementById('viz-master-frame');
          if (!dashboardRoot) return;
          var oldClones = dashboardRoot.querySelectorAll('.stock-market-anim-clone');
          for (var k = 0; k < oldClones.length; k++) {
            if (oldClones[k].parentNode) {
              oldClones[k].parentNode.removeChild(oldClones[k]);
            }
          }

          var tokens = dashboardRoot.querySelectorAll('.stock-market-token');
          for (var i = 0; i < tokens.length; i++) {
            var token = tokens[i];
            token.style.opacity = '1';
            var id = token.getAttribute('data-corp') || token.id;
            if (id) {
              var r = token.getBoundingClientRect();
              if (r.width > 0 && r.height > 0) {
                window._stockMarketTokens[id] = {
                  left: r.left,
                  top: r.top,
                  width: r.width,
                  height: r.height,
                  src: token.getAttribute('src') || token.getAttribute('href') || ''
                };
              }
            }
          }
        }
      end

      def self.animate_movements
        %x{
          window.requestAnimationFrame(function() {
            window.requestAnimationFrame(function() {
              if (!window._stockMarketTokens) return;
              var dashboardRoot = window.document.getElementById('viz-master-frame');
              if (!dashboardRoot) return;
              var newTokens = dashboardRoot.querySelectorAll('.stock-market-token');

              for (var i = 0; i < newTokens.length; i++) {
                (function(token) {
                  var id = token.getAttribute('data-corp') || token.id;
                  var prev = window._stockMarketTokens[id];
                  if (!prev) return;

                  var curr = token.getBoundingClientRect();
                  if (curr.width === 0 || curr.height === 0) return;

                  var dx = prev.left - curr.left;
                  var dy = prev.top - curr.top;
                  var dist = Math.sqrt(dx * dx + dy * dy);

                  if (dist > 3) {
                    var clone;
                    var isImg = token.tagName.toLowerCase() === 'img';
                    if (isImg) {
                      clone = token.cloneNode(true);
                    } else {
                      clone = window.document.createElement('img');
                      clone.src = prev.src || token.getAttribute('href') || '';
                      clone.style.borderRadius = '50%';
                    }

                    clone.className = 'stock-market-anim-clone';
                    clone.removeAttribute('id');
                    clone.removeAttribute('data-corp');

                    clone.style.position = 'fixed';
                    clone.style.left = prev.left + 'px';
                    clone.style.top = prev.top + 'px';
                    clone.style.width = prev.width + 'px';
                    clone.style.height = prev.height + 'px';
                    clone.style.zIndex = '999999';
                    clone.style.pointerEvents = 'none';
                    clone.style.margin = '0';
                    clone.style.boxSizing = 'border-box';
                    clone.style.outline = '3px solid #38bdf8';
                    clone.style.outlineOffset = '2px';
                    clone.style.borderRadius = '50%';

                    dashboardRoot.appendChild(clone);
                    token.style.opacity = '0';

                    var deltaX = curr.left - prev.left;
                    var deltaY = curr.top - prev.top;

                    var keyframes = [
                      {
                        transform: 'translate(0px, 0px) scale(1)',
                        filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.35))',
                        offset: 0
                      },
                      {
                        transform: 'translate(0px, -26px) scale(2.0)',
                        filter: 'drop-shadow(0 28px 24px rgba(0,0,0,0.65))',
                        offset: 0.22
                      },
                      {
                        transform: 'translate(' + deltaX + 'px, ' + (deltaY - 26) + 'px) scale(2.0)',
                        filter: 'drop-shadow(0 28px 24px rgba(0,0,0,0.65))',
                        offset: 0.76
                      },
                      {
                        transform: 'translate(' + deltaX + 'px, ' + (deltaY + 2) + 'px) scale(1.06)',
                        filter: 'drop-shadow(0 4px 6px rgba(0,0,0,0.35))',
                        offset: 0.92
                      },
                      {
                        transform: 'translate(' + deltaX + 'px, ' + deltaY + 'px) scale(1)',
                        filter: 'drop-shadow(0 2px 4px rgba(0,0,0,0.35))',
                        offset: 1
                      }
                    ];

                    var anim = clone.animate(keyframes, {
                      duration: 600,
                      easing: 'cubic-bezier(0.25, 1, 0.35, 1)',
                      fill: 'forwards'
                    });

                    var finishHandler = function() {
                      token.style.opacity = '1';
                      if (clone.parentNode) {
                        clone.parentNode.removeChild(clone);
                      }
                    };

                    anim.onfinish = finishHandler;
                    anim.oncancel = finishHandler;
                  }
                })(newTokens[i]);
              }
            });
          });
        }
      end
    end

    class DashboardStock < Snabberb::Component
      include Lib::Settings

      needs :game
      needs :user, default: nil, store: true
      needs :show_bank, default: false
      needs :explain_colors, default: true

      COLOR_MAP = {
        red: '#ffaaaa',
        blue: '#35a7ff',
        brown: '#8b4513',
        orange: '#ffbb55',
        yellow: '#ffff99',
        black: '#000000',
        gray: '#888888',
        green: '#aaffaa',
        white: '#ffffff',
        olive: '#d1e189',
        purple: '#9a4eae',
        peach: '#ffe5b4',
      }.freeze

      PAD = 4
      BORDER = 1
      WIDTH_TOTAL = 50
      TOKEN_SIZE = 30
      TOKEN_SIZES = { small: 30, medium: 35, large: 40 }.freeze

      VERTICAL_TOKEN_PAD = 4
      MIN_NUM_TOKENS = 3
      PRICE_HEIGHT = 20
      MIN_TOKENS_HEIGHT = MIN_NUM_TOKENS * (TOKEN_SIZE + VERTICAL_TOKEN_PAD)

      HEIGHT_TOTAL = 50
      TOKEN_PAD = 3
      BOX_WIDTH = WIDTH_TOTAL - (2 * BORDER)
      LEFT_MARGIN = TOKEN_PAD
      RIGHT_MARGIN = BOX_WIDTH - TOKEN_PAD
      LEFT_TOKEN_POS = LEFT_MARGIN
      RIGHT_TOKEN_POS = RIGHT_MARGIN - TOKEN_SIZE
      MID_TOKEN_POS = (LEFT_TOKEN_POS + RIGHT_TOKEN_POS) / 2
      TOKEN_BORDER_WIDTH = 2

      HEX_WIDTH_TOTAL = 20
      HEX_PAD_FROM_CENTER = (HEX_WIDTH_TOTAL / 2) - BORDER
      HEX_HALF_TOKEN = TOKEN_SIZE / 2
      HEX_MID_TOKEN_POS = -HEX_HALF_TOKEN
      HEX_LEFT_TOKEN_POS = HEX_MID_TOKEN_POS - HEX_PAD_FROM_CENTER
      HEX_RIGHT_TOKEN_POS = HEX_MID_TOKEN_POS + HEX_PAD_FROM_CENTER
      HEX_TOKEN_BORDER_WIDTH = 2

      TOKEN_STYLE_1D = {
        textAlign: 'center',
        lineHeight: '0',
      }.freeze

      PRICE_STYLE_1D = {
        fontSize: '100%',
        textAlign: 'center',
      }.freeze

      PRICE_STYLE_INFO = {
        fontSize: '80%',
        textAlign: 'center',
        position: 'absolute',
        bottom: "#{PAD}px",
        width: "#{WIDTH_TOTAL - (2 * PAD) - (2 * BORDER)}px",
      }.freeze

      def active_corporations(corporations)
        corporations.reject(&:closed?)
      end

      def box_style_1d
        {
          position: 'relative',
          display: 'inline-block',
          padding: "#{PAD}px",
          margin: '0',
          verticalAlign: 'top',
          width: "#{WIDTH_TOTAL - (2 * PAD) - (2 * BORDER)}px",
          border: "solid #{BORDER}px rgba(0,0,0,0.2)",
          color: color_for(:font2),
        }
      end

      def box_height_1d
        tokens_height = [*@game.stock_market.market.first.map do |p|
                           active_corporations(p.corporations).sum do |c|
                             TOKEN_SIZES[@game.corporation_size(c)] + VERTICAL_TOKEN_PAD
                           end
                         end,
                         MIN_TOKENS_HEIGHT].max
        "#{tokens_height + VERTICAL_TOKEN_PAD + PRICE_HEIGHT - (2 * BORDER)}px"
      end

      CROSSHATCH_TYPES = %i[par_overlap convert_range].freeze
      BORDER_TYPES = %i[max_price max_price_1].freeze

      def cell_style(box_style, types)
        normal_types = types.reject { |t| BORDER_TYPES.include?(t) }
        color = @game.class::STOCKMARKET_COLORS[normal_types&.first]
        color_to_use = color ? COLOR_MAP[color] : color_for(:bg2)

        style = if !!normal_types.intersect?(CROSSHATCH_TYPES) && normal_types.size > 1
                  secondary = @game.class::STOCKMARKET_COLORS[(normal_types & CROSSHATCH_TYPES).first]
                  secondary_color = secondary ? COLOR_MAP[secondary] : color_for(:bg2)
                  box_style.merge(background: "repeating-linear-gradient(45deg, #{color_to_use}, #{color_to_use} 10px,
                    #{secondary_color} 10px, #{secondary_color} 20px)")
                else
                  box_style.merge(backgroundColor: color_to_use)
                end

        if types.intersect?(BORDER_TYPES)
          style[:borderRightWidth] = "#{BORDER * 4}px"
          style[:borderRightColor] = @game.class::STOCKMARKET_COLORS[(types & BORDER_TYPES).first]
          style[:width] = "#{WIDTH_TOTAL - (2 * PAD) - (2 * BORDER) - 3}px"
        end
        if color == :black
          style[:color] = 'gainsboro'
          style[:borderColor] = color_for(:font)
        end

        style
      end

      def grid_1d_price(price)
        if price.acquisition?
          h(:div, { style: PRICE_STYLE_1D }, 'Acq.')
        elsif price.type == :safe_par
          h(:div, { style: PRICE_STYLE_1D.merge(textDecoration: 'underline') }, price.price)
        else
          h(:div, { style: PRICE_STYLE_1D }, price.price)
        end
      end

      def operated?(corporation)
        return false unless @game.round.operating?

        order = @game.round.entities.index(corporation)
        idx = @game.round.entities.index(@game.round.current_entity)
        order < idx if order && idx
      end

      def token_props(corporation, index = nil, num = nil, spacing = nil)
        props = {
          attrs: {
            id: "stock-token-#{corporation.id}",
            class: 'stock-market-token',
            'data-corp': corporation.id,
            src: logo_for_user(corporation),
            title: corporation.name,
            width: "#{TOKEN_SIZES[@game.corporation_size(corporation)]}px",
          },
          style: {
            marginTop: "#{VERTICAL_TOKEN_PAD}px",
            cursor: 'pointer',
            pointerEvents: 'auto',
          },
        }
        if index
          props[:attrs][:width] = "#{TOKEN_SIZE}px"
          # // --- START FIX ---
          props[:style] = {
            position: 'absolute',
            left: num > 1 ? "#{LEFT_TOKEN_POS + ((num - index - 1) * spacing)}px" : "#{MID_TOKEN_POS}px",
            top: "#{PAD + 12}px",
            zIndex: num - index,
            cursor: 'pointer',
            pointerEvents: 'auto',
          }
          # // --- END FIX ---
        end
        if operated?(corporation)
          props[:attrs][:title] = "#{corporation.name} has operated"
          props[:style][:opacity] = '0.6'
          props[:style][:clipPath] = 'polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)'
          border = 'dashed'
        end
        if (show_player_colors = setting_for(:show_player_colors, @game))
          border_color = if show_player_colors && (owner = corporation.owner) && @game.players.include?(owner)
                           player_colors(@game.players)[owner]
                         else
                           'transparent'
                         end
          props[:style][:border] = "#{TOKEN_BORDER_WIDTH}px #{border || 'solid'} #{border_color}"
          props[:style][:borderRadius] = props[:attrs][:width]
          props[:style][:boxSizing] = 'border-box'
          props[:style][:clipPath] = 'none'
        end

        props
      end

      def token_svgs(corporation, index = nil, num = nil, spacing = nil)
        width = TOKEN_SIZES[@game.corporation_size(corporation)]

        props = {
          attrs: {
            id: "stock-token-#{corporation.id}",
            class: 'stock-market-token',
            'data-corp': corporation.id,
            href: logo_for_user(corporation),
            title: corporation.name,
            width: "#{width}px",
            x: "#{HEX_MID_TOKEN_POS}px",
            y: "#{HEX_MID_TOKEN_POS}px",
          },
        }

        x_translation = !index.nil? && num > 1 ? HEX_MID_TOKEN_POS - (HEX_LEFT_TOKEN_POS + (index * spacing)) : 0

        border_color = if setting_for(:show_player_colors, @game) && (owner = corporation.owner) && @game.players.include?(owner)
                         player_colors(@game.players)[owner]
                       else
                         'transparent'
                       end
        if operated?(corporation)
          props[:attrs][:title] = "#{corporation.name} has operated"
          props[:attrs]['clip-path'] = 'polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%)'

          under_shape = [
            h(:polygon, {
                attrs: {
                  points: "-#{(width / 2) + 1},0 0,#{(width / 2) + 1} #{(width / 2) + 1},0 0,-#{(width / 2) + 1}",
                  stroke: corporation.color,
                  'stroke-width': 2,
                  fill: 'transparent',
                },
              }),
            h(:polygon, {
                attrs: {
                  points: "-#{(width / 2) + 1},0 0,#{(width / 2) + 1} #{(width / 2) + 1},0 0,-#{(width / 2) + 1}",
                  stroke: border_color,
                  'stroke-width': 2,
                  fill: 'transparent',
                  'stroke-dasharray': '4',
                },
              }),
          ]
        else
          under_shape = [h(:circle, {
                             attrs: {
                               cx: 0,
                               cy: 0,
                               stroke: border_color,
                               'stroke-width': 2,
                               fill: 'transparent',
                               r: "#{width / 2}px",
                             },
                           })]
        end

        g_props = {
          attrs: {
            transform: "translate(#{x_translation},0)",
            class: 'stock-market-token',
            'data-corp': corporation.id,
          },
          style: { cursor: 'pointer', pointerEvents: 'auto' },
        }

        # Ensure under_shape elements have pointer-events: none
        under_shape.each do |node|
          %x{
            if (!#{node}.data) #{node}.data = {};
            if (!#{node}.data.attrs) #{node}.data.attrs = {};
            #{node}.data.attrs['pointer-events'] = 'none';
          }
        end

        h(:g, g_props, [h(:image, props), *under_shape])
      end

      def par_bars(colors)
        bar_style = {
          border: '1px solid black',
          height: '3px',
          margin: '1px',
        }

        bars = colors.map do |color|
          bar_style[:backgroundColor] = color

          h(:div, { style: bar_style })
        end
        h(:div, bars)
      end

      def grid_1d
        row = @game.stock_market.market.first.map do |price|
          tokens = active_corporations(price.corporations).map { |corporation| h(:img, token_props(corporation)) }

          box_style = box_style_1d
          box_style[:height] = box_height_1d
          box_style = box_style.merge('margin-right': '10px') unless price.normal_movement?

          elements = [grid_1d_price(price)]
          unless (colors = @game.market_par_bars(price)).empty?
            elements << par_bars(colors)
          end
          elements << h(:div, { style: TOKEN_STYLE_1D }, tokens)

          h(:div, { style: cell_style(box_style, price.types) }, elements)
        end

        rows = row.size < 60 ? [row] : [row.shift((row.size / 2.0).ceil), row]
        rows.map { |r| h(:div, { style: { width: 'max-content' } }, r) }
      end

      def grid_zigzag(zigzag)
        box_style = box_style_1d

        half_box_style = box_style_1d
        half_box_style[:width] = "#{(WIDTH_TOTAL / 2) - (2 * PAD) - (2 * BORDER)}px"

        box_height = box_height_1d
        box_style[:height] = box_height
        half_box_style[:height] = box_height

        row0 = []
        row1 = [h(:div, style: cell_style(half_box_style, @game.stock_market.market.first.first.types))]

        @game.stock_market.market.first.each_with_index do |price, idx|
          tokens = active_corporations(price.corporations).map { |corporation| h(:img, token_props(corporation)) }

          cell_elements = [h(:div, { style: PRICE_STYLE_1D }, price.price),
                           h(:div, { style: TOKEN_STYLE_1D }, tokens)]
          cell_elements << h(:div, { style: PRICE_STYLE_INFO }, price.info) if price.info

          element = h(:div, { style: cell_style(box_style, price.types) }, cell_elements)
          if idx.even?
            row0 << element
          else
            row1 << element
          end
        end

        shorter_row = row1.size > row0.size ? row0 : row1
        shorter_row << h(:div, style: cell_style(half_box_style, @game.stock_market.market.first.last.types))

        rows = zigzag == :flip ? [row1, row0] : [row0, row1]
        rows.map { |row| h(:div, { style: { width: 'max-content' } }, row) }
      end

      def cell_style_hex(types)
        normal_types = types.reject { |t| BORDER_TYPES.include?(t) }
        color = @game.class::STOCKMARKET_COLORS[normal_types&.first]
        color_to_use = color ? COLOR_MAP[color] : color_for(:bg2)

        output = {}
        output[:fill] = color_to_use
        output[:stroke] = '#B0B0B0'
        output['stroke-width'] = 2
        output
      end

      def grid_hex
        size = 40
        col_spacing = (size * Math.sqrt(3)).round(2)
        row_spacing = (size * 3 / 2).round(2)
        num_rows = @game.stock_market.market.size
        max_cols = @game.stock_market.market.map.with_index { |r, i| r.size + ((num_rows - (i + 1)) / 2.0) }.max

        props = {
          attrs: {
            id: 'hex-market',
            width: (col_spacing * max_cols).to_s,
            height: (row_spacing * (num_rows + 0.5)).to_s,
          },
        }

        text_props = {
          attrs: {
            'dominant-baseline': 'middle',
            'text-anchor': 'middle',
            'font-size': '80%',
            transform: "translate(0, -#{row_spacing * 0.4})",
          },
        }

        col_border = 0
        row_border = row_spacing

        market_hexes = []
        @game.stock_market.market.each_with_index do |row, r_index|
          c_offset = (num_rows - r_index) / 2.0
          row.each_with_index do |price, c_index|
            next if price.nil?

            corporations = active_corporations(price.corporations)
            num = corporations.size
            spacing = num > 1 ? (HEX_RIGHT_TOKEN_POS - HEX_LEFT_TOKEN_POS) / (num - 1) : 0
            tokens = corporations.reverse.map.with_index { |corp, index| token_svgs(corp, index, num, spacing) }

            market_hexes <<
              h(:g,
                {
                  attrs: {
                    transform: "translate(#{col_spacing * (c_index + c_offset)}, #{row_spacing * (r_index - 0.25)})",
                  },
                },
                [h(:polygon,
                   {
                     attrs: {
                       transform: 'rotate(30)', points: Lib::Hex.points(scale: size / 100)
                     }.merge(cell_style_hex(price.types)),
                   }),
                 *tokens,
                 h(:text, text_props, price.price)])
          end
        end

        [h(:svg, props, [h(:g, { attrs: { transform: "translate(#{col_border},#{row_border})" } }, market_hexes)])]
      end

      def grid_2d
        (@game.stock_market.market + [[]]).each_cons(2).with_index.map do |rows, row_i|
          row_prices, next_row = rows
          first_price = true

          row = row_prices.each_with_index.map do |price, col_i|
            if price
              corporations = active_corporations(price.corporations)
              num = corporations.size
              spacing = num > 1 ? (RIGHT_TOKEN_POS - LEFT_TOKEN_POS) / (num - 1) : 0
              tokens = corporations.map.with_index { |corp, index| h(:img, token_props(corp, index, num, spacing)) }

              if first_price && !next_row.empty? && next_row[col_i]
                align = { left: 0, bottom: 0 }
                arrow = '⭣'
              elsif !row_i.zero? && @game.stock_market.right_ledge?([row_i, col_i])
                align = { right: 0, top: 0 }
                arrow = '⭡'
              else
                align = {}
                arrow = ''
              end

              first_price = false

              # // --- START FIX ---
              h(:div, { style: cell_style(@box_style_2d, price.types) },
                [
                  h('div.xsmall_font', { style: { fontSize: '11px', lineHeight: '12px', textAlign: 'center' } },
                    price.price),
                  h(:div, tokens),
                  h(:div, { style: { color: '#00000060', position: 'absolute', 'font-size': '170%' }.merge(align) },
                    arrow),
                  price.info ? h(:div, { style: PRICE_STYLE_INFO }, price.info) : nil,
                ].compact)
              # // --- END FIX ---
            else
              h(:div, { style: @space_style_2d }, '')
            end
          end

          h(:div, { style: { width: 'max-content' } }, row)
        end
      end

      def logo_for_user(entity)
        setting_for(:simple_logos, @game) ? entity.simple_logo : entity.logo
      end

      def render_legend
        return nil unless @explain_colors
        return nil unless @game.class.const_defined?(:MARKET_TEXT)

        type_text = @game.class::MARKET_TEXT

        type_to_first_col = {}
        @game.stock_market.market.reverse.flatten.compact.each do |sp|
          this_col = sp.coordinates ? sp.coordinates[1] : 0
          sp.types&.each do |t|
            min_col = type_to_first_col[t]
            type_to_first_col[t] = this_col if !min_col || this_col < min_col
          end
        end

        types_in_market = type_to_first_col.sort_by { |_t, col| col }.map(&:first).select do |t|
          type_text[t] || type_text[t.to_s] || type_text[t.to_sym]
        end

        return nil if types_in_market.empty?

        legend_items = types_in_market.map do |type|
          label_text = type_text[type] || type_text[type.to_s] || type_text[type.to_sym]

          line_props = {
            style: {
              display: 'flex',
              flexDirection: 'row',
              gap: '0.65rem',
              alignItems: 'center',
            },
          }

          h(:div, line_props, [
            h(:div, { style: cell_style(@box_style_2d, [type]) }, []),
            h(:div, {
                style: {
                  color: '#111827',
                  fontSize: '0.86rem',
                  fontWeight: '500',
                  lineHeight: '1.2',
                  whiteSpace: 'nowrap',
                },
              }, label_text),
          ])
        end

        legend_props = {
          attrs: { id: 'legend' },
          style: {
            display: 'flex',
            flexDirection: 'column',
            gap: '0.75rem',
            marginLeft: '1.5rem',
            alignSelf: 'flex-start',
          },
        }

        h('div#legend', legend_props, legend_items)
      end

      def timeline_cell_props(type, current, color = nil)
        bg_color, font_color, justify =
          case type
          when :SR, :PRE
            [color_for(:green), contrast_on(color_for(:green)), 'space-between']
          when :Export
            [color_for(:yellow), contrast_on(color_for(:yellow)), 'center']
          when :End
            [color_for(:blue), contrast_on(color_for(:blue)), 'space-between']
          else
            if color
              [color_for(color), contrast_on(color_for(color)), 'space-between']
            else
              [color_for(:bg2), color_for(:font2), 'space-between']
            end
          end

        props = {
          style: {
            display: 'flex',
            flexDirection: 'column',
            boxSizing: 'border-box',
            height: '3.2em',
            padding: '3px 6px',
            border: '1px solid rgba(0,0,0,0.2)',
            justifyContent: justify,
            backgroundColor: bg_color,
            color: font_color,
            fontSize: '0.85rem',
          },
        }
        if current
          props[:style].merge!(
            {
              fontWeight: 'bold',
              border: "3px solid #{color_for(:red)}",
              padding: '1px 4px',
            }
          )
        end

        props
      end

      def render_timeline
        has_progress = @game.respond_to?(:show_progress_bar?) && @game.show_progress_bar? && @game.respond_to?(:progress_information)
        has_timeline_events = @game.respond_to?(:timeline) && !@game.timeline.empty?

        return nil unless has_progress || has_timeline_events

        children = [
          h(:h4, {
              style: {
                margin: '0 0 0.4rem 0',
                fontSize: '0.95rem',
                fontWeight: 'bold',
                color: '#111827',
              },
            }, 'Timeline'),
        ]

        if has_progress
          train_export = h(:div, [
            h(:img, {
                attrs: {
                  src: '/icons/train_export.svg',
                  width: '14px',
                },
              }),
          ])

          bar_cells = @game.progress_information.flat_map.with_index do |item, index|
            cells = []
            is_current = @game.respond_to?(:round_counter) && @game.round_counter == index
            cells << h(:div, timeline_cell_props(item[:type], is_current, item[:color]), [
              h('div.center', { style: { fontSize: '0.8rem' } }, item[:value] || ' '),
              h('div.nowrap', { style: { fontSize: '0.8rem' } }, "#{item[:type]} #{item[:name]}"),
            ])
            if item[:exportAfter]
              cells << h(:div, timeline_cell_props(:Export, false), [
                item[:exportAfterValue] ? h(:div, item[:exportAfterValue]) : nil,
                train_export,
              ].compact)
            end
            cells
          end

          children << h(:div, {
                          style: {
                            display: 'flex',
                            flexDirection: 'row',
                            width: 'max-content',
                            overflow: 'visible',
                            border: '1px solid #cbd5e1',
                            borderRadius: '4px',
                            overflowX: 'hidden',
                          },
                        }, bar_cells)
        end

        if has_timeline_events
          event_lines = @game.timeline.map do |line|
            h(:div, {
                style: {
                  fontSize: '0.82rem',
                  lineHeight: '1.35',
                  color: '#334155',
                  marginTop: '0.2rem',
                },
              }, line)
          end
          children << h(:div, { style: { marginTop: '0.4rem' } }, event_lines)
        end

        h(:div, {
            attrs: { id: 'dashboard-market-timeline' },
            style: {
              width: 'max-content',
              display: 'flex',
              flexDirection: 'column',
              backgroundColor: '#f8fafc',
              border: '1px solid #e2e8f0',
              borderRadius: '6px',
              padding: '0.6rem 0.85rem',
              boxSizing: 'border-box',
            },
          }, children)
      end

      def self.install_marker_pulse
        %x{
          if (typeof window === 'undefined') return;
          if (window.__symmetric_marker_pulse_installed) return;
          window.__symmetric_marker_pulse_installed = true;

          if (!window.document.getElementById('symmetric-marker-pulse-styles')) {
            var style = window.document.createElement('style');
            style.id = 'symmetric-marker-pulse-styles';
            style.textContent = '' +
              '@keyframes marker-pulse-glow-stock {' +
              '  0% {' +
              '    transform: scale(1);' +
              '    filter: drop-shadow(0 0 2px rgba(0, 255, 255, 0.45));' +
              '  }' +
              '  50% {' +
              '    transform: scale(1.44);' +
              '    filter: drop-shadow(0 0 8px #00ffff) drop-shadow(0 0 16px rgba(0, 255, 255, 0.85));' +
              '  }' +
              '  100% {' +
              '    transform: scale(1);' +
              '    filter: drop-shadow(0 0 2px rgba(0, 255, 255, 0.45));' +
              '  }' +
              '}' +
              '@keyframes marker-pulse-glow-order {' +
              '  0% {' +
              '    transform: scale(1);' +
              '    filter: drop-shadow(0 0 2px rgba(0, 255, 255, 0.45));' +
              '  }' +
              '  50% {' +
              '    transform: scale(1.50);' +
              '    filter: drop-shadow(0 0 8px #00ffff) drop-shadow(0 0 16px rgba(0, 255, 255, 0.85));' +
              '  }' +
              '  100% {' +
              '    transform: scale(1);' +
              '    filter: drop-shadow(0 0 2px rgba(0, 255, 255, 0.45));' +
              '  }' +
              '}' +
              '@keyframes marker-pulse-glow-map {' +
              '  0% {' +
              '    transform: scale(1);' +
              '    filter: drop-shadow(0 0 4px rgba(0, 255, 255, 0.6));' +
              '  }' +
              '  50% {' +
              '    transform: scale(1.45);' +
              '    filter: drop-shadow(0 0 12px #00ffff) drop-shadow(0 0 24px rgba(0, 255, 255, 0.95));' +
              '  }' +
              '  100% {' +
              '    transform: scale(1);' +
              '    filter: drop-shadow(0 0 4px rgba(0, 255, 255, 0.6));' +
              '  }' +
              '}' +
              '#viz-master-frame .marker-pulsing {' +
              '  animation: marker-pulse-glow-stock 1.1s ease-in-out infinite !important;' +
              '  transform-box: fill-box !important;' +
              '  transform-origin: center center !important;' +
              '  z-index: 99999 !important;' +
              '}' +
              '#viz-master-frame .stock-market-token.marker-pulsing, #viz-master-frame [id^="stock-token-"].marker-pulsing {' +
              '  animation: marker-pulse-glow-stock 1.1s ease-in-out infinite !important;' +
              '  transform-box: fill-box !important;' +
              '  transform-origin: center center !important;' +
              '  z-index: 99999 !important;' +
              '}' +
              '#viz-master-frame .entity-order-token.marker-pulsing {' +
              '  animation: marker-pulse-glow-order 1.1s ease-in-out infinite !important;' +
              '  transform-box: fill-box !important;' +
              '  transform-origin: center center !important;' +
              '  z-index: 99999 !important;' +
              '}' +
              '#viz-master-frame .map-token.marker-pulsing, #viz-master-frame svg g.map-token.marker-pulsing {' +
              '  animation: marker-pulse-glow-map 1.1s ease-in-out infinite !important;' +
              '  transform-box: fill-box !important;' +
              '  transform-origin: center center !important;' +
              '  z-index: 99999 !important;' +
              '}' +
              '#viz-master-frame div.marker-pulsing, #viz-master-frame span.marker-pulsing, #viz-master-frame th.marker-pulsing {' +
              '  display: inline-block !important;' +
              '  position: relative !important;' +
              '}' +
              '#viz-master-frame .stock-market-token, #viz-master-frame [id^="stock-token-"], #viz-master-frame .map-token, #viz-master-frame .major-corporation-cell, #viz-master-frame [id^="status_major_"] {' +
              '  cursor: pointer !important;' +
              '  pointer-events: auto !important;' +
              '}';
            window.document.head.appendChild(style);
          }

          function resolveMarker(target) {
            if (!target || !target.closest) return null;

            // 1. Stock Market Marker
            var stockEl = target.closest('.stock-market-token, [id^="stock-token-"]');
            if (stockEl) {
              var sCorp = stockEl.getAttribute('data-corp') ||
                          (stockEl.id && stockEl.id.replace('stock-token-', ''));
              if (sCorp) return { corpId: String(sCorp), type: 'stock' };
            }

            // 2. Map Marker
            var mapEl = target.closest('.map-token, [class*="map-token-"]');
            if (mapEl) {
              var mCorp = mapEl.getAttribute('data-corp');
              if (!mCorp && mapEl.className) {
                var cls = String(mapEl.className.baseVal || mapEl.className);
                var match = cls.match(/map-token-([^\s]+)/);
                if (match) mCorp = match[1];
              }
              if (mCorp) return { corpId: String(mCorp), type: 'map' };
            }

            // 3. Status Table Marker
            var statusEl = target.closest('[id^="status_major_"], .major-corporation-cell');
            if (statusEl) {
              var stCorp = statusEl.getAttribute('data-corp');
              if (!stCorp && statusEl.id) {
                stCorp = statusEl.id.replace('status_major_', '');
              }
              if (!stCorp) {
                var tr = statusEl.closest('tr[data-corp]');
                if (tr) stCorp = tr.getAttribute('data-corp');
              }
              if (stCorp) return { corpId: String(stCorp), type: 'status' };
            }

            // 4. Entity Order Marker
            var orderEl = target.closest('.entity-order-token');
            if (orderEl) {
              var oCorp = orderEl.getAttribute('data-corp');
              if (oCorp) {
                return { corpId: String(oCorp), type: 'order' };
              }
            }

            return null;
          }

          function clearPulsing() {
            var root = window.document.getElementById('viz-master-frame');
            if (!root) return;
            var pulsing = root.querySelectorAll('.marker-pulsing');
            for (var i = 0; i < pulsing.length; i++) {
              pulsing[i].classList.remove('marker-pulsing');
            }
          }

function setPulsingForOthers(corpId, currentType) {
  clearPulsing();
  if (!corpId) return;

  var root = window.document.getElementById('viz-master-frame');
  if (!root || !root.isConnected) return;

  var wantedCorp = String(corpId);
  var safeCorp = (window.CSS && CSS.escape) ? CSS.escape(wantedCorp) :
    wantedCorp.replace(/[^A-Za-z0-9_-]/g, '\\$&');

  function matchingByCorp(selector) {
    var nodes = root.querySelectorAll(selector);
    var matches = [];
    for (var i = 0; i < nodes.length; i++) {
      var nodeCorp = nodes[i].getAttribute('data-corp');
      if (String(nodeCorp) === wantedCorp) matches.push(nodes[i]);
    }
    return matches;
  }

  // Pulse Stock Market token if not the trigger. Select broadly, then compare
  // data-corp literally so IDs such as B&O never enter a CSS selector.
  if (currentType !== 'stock') {
    var stockTokens = matchingByCorp('.stock-market-token');
    var stockById = root.querySelector('#stock-token-' + safeCorp);
    if (stockById && stockTokens.indexOf(stockById) < 0) stockTokens.push(stockById);
    for (var s = 0; s < stockTokens.length; s++) {
      stockTokens[s].classList.add('marker-pulsing');
    }
  }

  // Pulse Map token(s) if not the trigger.
  if (currentType !== 'map') {
    var mapTokens = matchingByCorp('.map-token');
    var mapByClass = root.querySelectorAll('.map-token-' + safeCorp);
    for (var mc = 0; mc < mapByClass.length; mc++) {
      if (mapTokens.indexOf(mapByClass[mc]) < 0) mapTokens.push(mapByClass[mc]);
    }
    for (var m = 0; m < mapTokens.length; m++) {
      mapTokens[m].classList.add('marker-pulsing');
    }
  }

  // Pulse Status Table card if not the trigger.
  if (currentType !== 'status') {
    var statusEls = matchingByCorp('th.major-corporation-cell, tr[data-corp]');
    var statusById = root.querySelector('#status_major_' + safeCorp);
    if (statusById && statusEls.indexOf(statusById) < 0) statusEls.push(statusById);
    for (var st = 0; st < statusEls.length; st++) {
      if (String(statusEls[st].tagName).toLowerCase() === 'tr') {
        var heading = statusEls[st].querySelector('th.major-corporation-cell');
        if (heading) heading.classList.add('marker-pulsing');
      } else {
        statusEls[st].classList.add('marker-pulsing');
      }
    }
  }

  if (currentType !== 'order') {
    var orderTokens = matchingByCorp('.entity-order-token');
    for (var o = 0; o < orderTokens.length; o++) {
      orderTokens[o].classList.add('marker-pulsing');
    }
  }
}
          var activeCorp = null;
          var activeType = null;

          window.document.addEventListener('mouseover', function(e) {
            if (!e.target || !e.target.closest || !e.target.closest('#viz-master-frame')) return;
            var info = resolveMarker(e.target);
            if (info) {
              if (activeCorp === info.corpId && activeType === info.type) return;
              activeCorp = info.corpId;
              activeType = info.type;
              setPulsingForOthers(info.corpId, info.type);
            }
          }, true);

          window.document.addEventListener('mouseout', function(e) {
            if (!e.target || !e.target.closest || !e.target.closest('#viz-master-frame')) return;
            if (!activeCorp) return;
            var toInfo = resolveMarker(e.relatedTarget);
            if (!toInfo) {
              clearPulsing();
              activeCorp = null;
              activeType = null;
            }
          }, true);
        }
      end

      def render
        self.class.install_marker_pulse
        StockMarketAnimation.capture_pre_render

        @space_style_2d = {
          position: 'relative',
          display: 'inline-block',
          padding: "#{PAD}px",
          width: "#{WIDTH_TOTAL - (2 * PAD) - (2 * BORDER)}px",
          height: "#{HEIGHT_TOTAL - (2 * PAD) - (2 * BORDER)}px",
          border: "solid #{BORDER}px rgba(0,0,0,0)",
          margin: '0',
          verticalAlign: 'top',
        }

        @box_style_2d = @space_style_2d.merge(
          border: "solid #{BORDER}px rgba(0,0,0,0.2)",
          color: color_for(:font2),
        )

        grid = if @game.stock_market.hex_market?
                 grid_hex
               elsif @game.stock_market.one_d?
                 if !(zigzag = @game.stock_market.zigzag).nil?
                   grid_zigzag(zigzag)
                 else
                   grid_1d
                 end
               else
                 grid_2d
               end

        grid_props = {
          style: {
            width: 'max-content',
            height: 'max-content',
            overflow: 'visible',
            margin: '0',
            padding: '0',
          },
        }

        grid_elm = h(:div, grid_props, grid)
        legend_elm = render_legend

        StockMarketAnimation.animate_movements

        top_row_props = {
          style: {
            display: 'flex',
            flexDirection: 'row',
            alignItems: 'flex-start',
            width: 'max-content',
          },
        }

        elements = [h(:div, top_row_props, [grid_elm, legend_elm].compact)]

        if @game.respond_to?(:par_chart) && @game.par_chart
          elements << h(:div, {
                          attrs: { id: 'stock-market-par-chart' },
                          style: { marginTop: '1.25rem', width: 'max-content' },
                        }, [h(View::Game::ParChart, game: @game)])
        end

        if @game.respond_to?(:loan_chart) && @game.loan_chart
          elements << h(:div, {
                          attrs: { id: 'stock-market-loan-chart' },
                          style: { marginTop: '1.25rem', width: 'max-content' },
                        }, [h(View::Game::LoanChart, game: @game)])
        end

        timeline_elm = render_timeline
        elements << timeline_elm if timeline_elm

        container_props = {
          attrs: { id: 'dashboard-stock-market-container' },
          style: {
            display: 'flex',
            flexDirection: 'column',
            width: 'max-content',
            alignItems: 'flex-start',
            gap: '1.25rem',
          },
        }

        h(:div, container_props, elements)
      end
    end

    DashboardStockMarket = DashboardStock
  end
end
