module View
  module Game
    class DashboardBank < Snabberb::Component
      include Lib::Settings
      include Actionable
      include View::Game::Dashboard::RailcardHelper

      needs :game, store: true
      needs :train_handler, default: nil
      needs :show_loan_table, default: false, store: true

      FONT_STD = '"Helvetica Neue", Helvetica, Arial, sans-serif'
      FONT_MONEY = '"Courier New", Courier, monospace'
      FONT_CASH = '"Arial Black", Gadget, sans-serif'
      COLOR_CASH = '#4b0082' # Dark Purple (Indigo)
      COLOR_MONEY = 'var(--color-money-text, #4c1d95)'
      COLOR_BANK_GREEN = 'var(--bg-market-zone, #e6f4ea)'

      def current_entity
        @game.round.active_step&.current_entity ||
          (@game.round.respond_to?(:current_entity) ? @game.round.current_entity : nil) ||
          @game.current_entity
      rescue NotImplementedError, StandardError
        nil
      end

      def actions_for(entity)
        return [] unless entity

        actions = []
        if @game.round.respond_to?(:actions_for)
          begin
            actions.concat(@game.round.actions_for(entity) || [])
          rescue NotImplementedError, StandardError
          end
        end
        step = @game.round.active_step
        if step.respond_to?(:actions)
          begin
            actions.concat(step.actions(entity) || [])
          rescue NotImplementedError, StandardError
          end
        end
        if step.respond_to?(:current_actions)
          begin
            actions.concat(step.current_actions || [])
          rescue NotImplementedError, StandardError
          end
        end
        actions.compact.map(&:to_s).uniq
      end

      def active_entity
        current_entity
      end

      def train_available_count(train, variant_name = nil, from_pool: false)
        return '∞' if train.respond_to?(:unlimited) && train.unlimited
        return 0 if train.respond_to?(:rusted) && train.rusted

        if from_pool || @game.depot.discarded.include?(train)
          @game.depot.discarded.count do |t|
            (!t.respond_to?(:rusted) || !t.rusted) && (t.name == train.name || t.sym == train.sym)
          end
        else
          count = @game.depot.upcoming.count do |t|
            (!t.respond_to?(:rusted) || !t.rusted) &&
              (t.name == train.name || t.sym == train.sym ||
                (variant_name && t.respond_to?(:variants) && t.variants&.key?(variant_name)))
          end
          count = 1 if count.zero? && train.owner == @game.depot && !@game.depot.discarded.include?(train)
          count
        end
      end

      def train_entity_for_variant(train, variant_name, price)
        return train unless train
        return train if variant_name.nil? || variant_name.to_s == train.name.to_s

        variant_train = train.dup
        if variant_train.respond_to?(:variant=) &&
           variant_train.respond_to?(:variants) &&
           variant_train.variants&.key?(variant_name.to_s)
          begin
            variant_train.variant = variant_name.to_s
            return variant_train
          rescue StandardError
          end
        end

        if train.respond_to?(:variants) && train.variants
          v_spec = train.variants[variant_name.to_s] || train.variants[variant_name]
        end
        variant_train.instance_variable_set(:@name, variant_name.to_s)
        variant_train.instance_variable_set(:@price, price) if price
        if v_spec.is_a?(Hash)
          variant_train.instance_variable_set(:@distance, v_spec[:distance]) if v_spec.key?(:distance)
          variant_train.instance_variable_set(:@rusts_on, v_spec[:rusts_on]) if v_spec.key?(:rusts_on)
          variant_train.instance_variable_set(:@obsolete_on, v_spec[:obsolete_on]) if v_spec.key?(:obsolete_on)
          variant_train.instance_variable_set(:@discount, v_spec[:discount]) if v_spec.key?(:discount)
        end
        variant_train
      rescue StandardError
        train
      end

      def depot_pool_trains
        return [] unless @game.respond_to?(:depot) && @game.depot

        discarded = @game.depot.respond_to?(:discarded) ? (@game.depot.discarded || []) : []
        discarded.reject { |t| t.respond_to?(:rusted) && t.rusted }
                 .reject { |t| train_available_count(t, from_pool: true).to_s == '0' }
                 .uniq(&:name)
      end

      def depot_fresh_trains
        return [] unless @game.respond_to?(:depot) && @game.depot

        upcoming = @game.depot.respond_to?(:upcoming) ? (@game.depot.upcoming || []) : []
        upcoming = upcoming.reject { |t| t.respond_to?(:rusted) && t.rusted }
        return [] if upcoming.empty?

        discarded = @game.depot.respond_to?(:discarded) ? (@game.depot.discarded || []) : []

        # Retain buyable step view across turns if available
        step = @game.round.active_step
        buy_step = step if step.respond_to?(:buyable_trains)
        buy_step = @game.round.steps.find { |s| s.respond_to?(:buyable_trains) } if !buy_step && @game.round.respond_to?(:steps)

        if buy_step
          entity = active_entity || (@game.respond_to?(:current_entity) ? @game.current_entity : nil) || @game.corporations&.first
          if entity
            begin
              buyable = buy_step.buyable_trains(entity) || []
              fresh = buyable.select do |t|
                !discarded.include?(t) &&
                  (upcoming.include?(t) || ((t.respond_to?(:from_depot?) && t.from_depot?) || t.owner == @game.depot))
              end
              fresh = fresh.reject { |t| t.respond_to?(:rusted) && t.rusted }
              return fresh.uniq(&:name) if fresh.any?
            rescue StandardError
            end
          end
        end

        [upcoming.first].compact.uniq(&:name)
      end

      def render_train_cells(item, type, _index)
        train = item[:train]
        variant_name = item[:variant_name]
        price = item[:price]

        entity = active_entity
        step = train_purchase_step(entity)

        train_buyable_step =
          actions_for(entity).include?('buy_train')

        card_classes = %w[game-card card-train]
        click_handler = nil

        variant_is_buyable =
          train_buyable_step &&
          entity && entity.respond_to?(:cash) &&
          train_variant_buyable?(
            step,
            entity,
            train,
            variant_name
          )

        if variant_is_buyable
          can_afford =
            entity.cash >= price

          if can_afford
            card_classes << 'action-buy'
            card_classes << 'clickable'

            click_handler = lambda {
              variant_str = variant_name.to_s
              display_train = train_entity_for_variant(train, variant_name, price)

              if @train_handler
                @train_handler.call(
                  train,
                  price,
                  variant_str,
                  type
                )
              else
                if train_will_rust_now?(display_train, type)
                  rust_slugs = train_rust_slugs(display_train)
                  %x{
                    if (typeof window !== 'undefined' && window.triggerRustExplosion && #{rust_slugs}.length > 0) {
                      window.triggerRustExplosion(#{rust_slugs});
                    }
                  }
                end

                process_action(
                  Engine::Action::BuyTrain.new(
                    entity,
                    train: train,
                    price: price,
                    variant: (
                      if variant_str == train.name.to_s
                        nil
                      else
                        variant_str
                      end
                    )
                  )
                )
              end
            }
          end
        end

        available_count = train_available_count(train, variant_name, from_pool: (type == 'pool'))
        rem_text = train.respond_to?(:unlimited) && train.unlimited ? '(∞)' : "(#{available_count})"
        dom_id = "bank_train_#{type}_#{train.id}_#{variant_name}".gsub(/[^a-zA-Z0-9_-]/, '_')
        # Diagnostic attributes expose the precise eligibility gate in the browser DOM.
        debug_entity = entity
        debug_step = step
        debug_actions = actions_for(debug_entity)
        debug_buyable = begin
          debug_step && debug_step.respond_to?(:buyable_trains) ? Array(debug_step.buyable_trains(debug_entity)) : []
        rescue StandardError
          []
        end
        debug_attrs = {
          'data-bank-entity' => debug_entity&.name.to_s,
          'data-bank-entity-class' => debug_entity.class.to_s,
          'data-bank-cash' => debug_entity.respond_to?(:cash) ? debug_entity.cash.to_s : '',
          'data-bank-step' => debug_step.class.to_s,
          'data-bank-actions' => debug_actions.join(','),
          'data-bank-train-id' => train.id.to_s,
          'data-bank-engine-trains' => debug_buyable.map { |t| "#{t.id}:#{t.name}" }.join(','),
          'data-bank-matched' => debug_buyable.include?(train).to_s,
          'data-bank-variant-ok' => train_variant_buyable?(debug_step, debug_entity, train, variant_name).to_s,
          'data-bank-affordable' => (debug_entity.respond_to?(:cash) && debug_entity.cash >= price).to_s,
        }
        display_train = train_entity_for_variant(train, variant_name, price)
        card_el = render_railcard(variant_name.to_s, card_classes, click_handler, entity: display_train)

        card_td = h('td.left', { key: "#{dom_id}_card", style: { padding: '2px 4px', verticalAlign: 'middle' } }, [
          h(:div, { attrs: { id: dom_id }.merge(debug_attrs), style: { display: 'inline-flex', alignItems: 'center' } }, [card_el]),
        ])

        info_td = h('td.right', { key: "#{dom_id}_info", style: { padding: '2px 4px', verticalAlign: 'middle', whiteSpace: 'nowrap' } }, [
          h(:div, { style: { display: 'flex', alignItems: 'center', gap: '0.4rem', justifyContent: 'flex-end' } }, [
            h(:span, { style: { fontFamily: FONT_CASH, color: COLOR_CASH, fontWeight: 'bold', fontSize: '0.82rem' } },
              @game.format_currency(price)),
            h(:span,
              { style: { fontFamily: FONT_STD, fontSize: '0.82rem', fontWeight: 'bold', color: '#000000', minWidth: '1.8rem', textAlign: 'right' } }, rem_text),
          ]),
        ])

        [card_td, info_td]
      end

      def render_empty_train_cells(type, index)
        [
          h('td.left', { key: "empty_#{type}_card_#{index}", style: { padding: '4px 6px', verticalAlign: 'middle' } }, ''),
          h('td.right',
            { key: "empty_#{type}_info_#{index}", style: { padding: '4px 6px', verticalAlign: 'middle', whiteSpace: 'nowrap' } }, ''),
        ]
      end

      def displayed_train_variants(train)
        variants = train.respond_to?(:variants) ? (train.variants || {}) : {}
        if !variants.empty?
          variants.each_with_object({}) do |(name, data), result|
            actual_name = data.respond_to?(:[]) ? (data[:name] || data['name'] || name) : name
            price = data.respond_to?(:[]) ? (data[:price] || data['price'] || train.price) : train.price
            result[actual_name] = price
          end
        elsif train.respond_to?(:names_to_prices) && train.names_to_prices && !train.names_to_prices.empty?
          train.names_to_prices
        else
          { train.name => train.price }
        end
      end

      # Match the Action Hub's engine-based train candidate selection.
      # The bank additionally requires corporation cash, not emergency buying power.
      def train_variant_buyable?(step, entity, train, variant_name)
        return false unless step && entity && step.respond_to?(:buyable_trains)
        return false unless Array(step.buyable_trains(entity)).include?(train)

        return false if step.respond_to?(:can_buy_train?) && !step.can_buy_train?(entity, train)

        if step.respond_to?(:buyable_train_variants) && train.respond_to?(:variants)
          allowed = Array(step.buyable_train_variants(train, entity))
          variants = train.variants || {}
          return variants.any? do |name, data|
            next false unless allowed.include?(data)

            actual_name = data.respond_to?(:[]) ? (data[:name] || data['name'] || name) : name
            actual_name.to_s == variant_name.to_s
          end
        end

        true
      rescue StandardError
        false
      end

      def train_purchase_step(entity)
        @game.round.active_step(entity)
      rescue ArgumentError
        @game.round.active_step
      rescue StandardError
        nil
      end

      def render_trains_table
        pool_trains = depot_pool_trains
        fresh_trains = depot_fresh_trains

        return nil if pool_trains.empty? && fresh_trains.empty?

        pool_items = []
        pool_trains.each do |train|
          displayed_train_variants(train).each do |variant_name, price|
            pool_items << {
              train: train,
              variant_name: variant_name,
              price: price,
            }
          end
        end

        fresh_items = []
        fresh_trains.each do |train|
          displayed_train_variants(train).each do |variant_name, price|
            fresh_items << {
              train: train,
              variant_name: variant_name,
              price: price,
            }
          end
        end
        return nil if pool_items.empty? && fresh_items.empty?

        max_rows = [pool_items.size, fresh_items.size].max

        trs = [
          h(:tr, { key: 'bank_trains_header' }, [
            h(:th,
              { attrs: { colspan: 2 }, style: { width: '50%', textAlign: 'center', fontFamily: FONT_STD, fontSize: '0.8rem', fontWeight: 'bold' } }, 'Pool'),
            h(:th,
              { attrs: { colspan: 2 }, style: { width: '50%', textAlign: 'center', fontFamily: FONT_STD, fontSize: '0.8rem', fontWeight: 'bold' } }, 'Fresh'),
          ]),
        ]

        max_rows.times do |i|
          p_cells = pool_items[i] ? render_train_cells(pool_items[i], 'pool', i) : render_empty_train_cells('pool', i)
          f_cells = fresh_items[i] ? render_train_cells(fresh_items[i], 'fresh', i) : render_empty_train_cells('fresh', i)

          trs << h(:tr, { key: "bank_trains_row_#{i}" }, [p_cells[0], p_cells[1], f_cells[0], f_cells[1]])
        end

        h(:table, trs)
      end

