            trs << h(:tr, [
              h('td.left', { style: { fontFamily: FONT_STD } }, 'Loan Value'),
              h('td.right',
                { style: { fontFamily: FONT_MONEY, fontWeight: 'bold', color: COLOR_MONEY, fontVariantNumeric: 'tabular-nums' } }, @game.format_currency(lv)),
