# frozen_string_literal: true

require_relative 'ai_expert_rules'
unless defined?(Engine::AutoRouter)
  if RUBY_ENGINE == 'opal'
    require 'engine/auto_router'
  else
    require_relative '../../../../../lib/engine/auto_router'
  end
end

module View
  module Game
    module Dashboard
      class DashboardAiPlayer
        @execution_locks = {}
        @last_invocations = {}

        class << self
          def play(game, routes = [], &process_block)
            @execution_locks ||= {}
            @last_invocations ||= {}
            key = game.object_id
            return false if @execution_locks[key]

            fingerprint = invocation_fingerprint(game)
            now =
              if RUBY_ENGINE == 'opal'
                `Date.now()`.to_f
              else
                Process.clock_gettime(Process::CLOCK_MONOTONIC) * 1000.0
              end
            previous = @last_invocations[key]
            if previous && previous[:fingerprint] == fingerprint && (now - previous[:time]) < 300
              `console.warn("[AI Expert] Duplicate invocation suppressed.")`
              return false
            end

            @last_invocations[key] = { fingerprint: fingerprint, time: now }
            @execution_locks[key] = true
            begin
              new(game, routes, &process_block).play
            ensure
              @execution_locks.delete(key)
            end
          end

          def reset!(game = nil)
            @execution_locks ||= {}
            @last_invocations ||= {}
            if game
              key = game.object_id
              @execution_locks.delete(key)
              @last_invocations.delete(key)
            else
              @execution_locks.clear
              @last_invocations.clear
            end
          end

          private

          def invocation_fingerprint(game)
            round = game.round
            step = round&.active_step
            entity = begin; step.current_entity if step.respond_to?(:current_entity); rescue StandardError; nil; end
            entity ||= begin; round.current_entity if round.respond_to?(:current_entity); rescue StandardError; nil; end
            entity ||= begin; game.current_entity if game.respond_to?(:current_entity); rescue StandardError; nil; end
            count = if game.respond_to?(:actions)
                      Array(game.actions).size
                    elsif game.respond_to?(:raw_actions)
                      Array(game.raw_actions).size
                    else
                      0
                    end
            [round&.object_id, step&.object_id, entity&.object_id, count].join(':')
          rescue StandardError
            game.object_id.to_s
          end
        end

        def initialize(game, routes = [], &process_block)
          @game = game
          @routes = routes || []
          @process_block = process_block
          @tile_eval_cache = {}
          @token_eval_cache = {}
          @random_target_train_count = {}
        end

        def play
          step = @game.round&.active_step
          return false unless step

          entity = current_acting_entity(step)
          return false unless entity

          round_before = @game.round
          actions = generate_legal_actions(step, entity)
          actions = apply_share_strategy(actions, entity)
          if actions.any? { |action| action.is_a?(Engine::Action::LayTile) }
            actions = actions.reject { |action| action.is_a?(Engine::Action::Pass) }
          end
          return false if actions.empty?

          command_types = actions.map do |action|
            if action.is_a?(Engine::Action::Pass)
              :pass
            elsif action.is_a?(Engine::Action::SellShares) &&
                  entity.respond_to?(:corporation?) &&
                  entity.corporation?
              :issue
            else
              :other
            end
          end

          if command_types.all? { |type| %i[pass issue].include?(type) }
            action = actions.sample

            return false unless action_belongs_to_entity?(action, entity)
            return false unless execution_context_unchanged?(round_before, step, entity)

            @process_block.call(action)

            return true
          end

          draft_action = AiExpertRules.select_draft_action(actions, @game)
          if draft_action
            return false unless action_belongs_to_entity?(draft_action, entity)
            return false unless @game.round.equal?(round_before)
            return false unless @game.round.active_step.equal?(step)
            return false unless current_acting_entity(step).equal?(entity)

            @process_block.call(draft_action)
            return true
          end

          choose_actions = actions.select { |action| action.is_a?(Engine::Action::Choose) }

          if choose_actions.any?
            action = AiExpertRules.select_uniform_choice(actions)

            return false unless action_belongs_to_entity?(action, entity)
            return false unless @game.round.equal?(round_before)
            return false unless @game.round.active_step.equal?(step)
            return false unless current_acting_entity(step).equal?(entity)

            @process_block.call(action)
            return true
          end

          scored = actions.map do |action|
            features = extract_features(action, step, entity, actions)
            score, rules = AiExpertRules.score_action(action, features, @game)
            { action: action, score: score, rules: rules, features: features }
          end
          scored = AiExpertRules.apply_probability_policy(scored)

          choice_items = scored.select { |item| item[:features][:action_type] == 'choose' }
          tile_items = scored.select { |item| item[:features][:action_type] == 'lay_tile' }
          winning = if choice_items.any?
                      chosen_action = AiExpertRules.select_uniform_choice(choice_items.map { |item| item[:action] })
                      choice_items.find { |item| item[:action].equal?(chosen_action) }
                    elsif tile_items.any?
                      budget_safe = tile_items.reject { |item| item[:features][:breaks_train_budget] }
                      active_tiles = budget_safe.any? ? budget_safe : tile_items

                      active_tiles.each do |item|
                        features = item[:features]
                        features[:realized_income_gain] = if features[:has_own_token]
                                                            features[:tile_rev_gain].to_i
                                                          else
                                                            0
                                                          end
                      end
                      best_key = active_tiles.map do |item|
                        [item[:features][:realized_income_gain].to_i,
                         item[:features][:projected_revenue].to_i]
                      end.max
                      tied = active_tiles.select do |item|
                        [item[:features][:realized_income_gain].to_i,
                         item[:features][:projected_revenue].to_i] == best_key
                      end
                      tied.sample
                    else
                      token_items = scored.select { |item| item[:features][:action_type] == 'place_token' }

                      if token_items.any?
                        profitable = token_items.select do |item|
                          item[:features][:token_revenue_gain].to_i.positive?
                        end

                        if profitable.any?
                          best_gain = profitable.map do |item|
                            item[:features][:token_revenue_gain].to_i
                          end.max

                          profitable.select do |item|
                            item[:features][:token_revenue_gain].to_i == best_gain
                          end.sample
                        else
                          non_tokens = scored.reject do |item|
                            item[:features][:action_type] == 'place_token'
                          end

                          if non_tokens.empty?
                            token_items.sample
                          else
                            non_tokens.sort_by! { |item| -item[:score] }
                            AiExpertRules.select_candidate(non_tokens)
                          end
                        end
                      else
                        scored.sort_by! { |item| -item[:score] }
                        AiExpertRules.select_candidate(scored)
                      end
                    end
          return false unless winning

          action = materialize_action_for_dispatch(winning[:action])
          return false unless action
          return false unless action_belongs_to_entity?(action, entity)
          unless @game.round.equal?(round_before) && @game.round.active_step.equal?(step) && current_acting_entity(step).equal?(entity)
            return false
          end

          @process_block.call(action)
          true
        rescue Engine::GameError => e
          if RUBY_ENGINE == 'opal'
            `console.warn("[AI Expert] Engine rejected selected action: " + #{e.message})`
          else
            LOGGER.warn(
              "[AI Expert] Engine rejected selected action: #{e.message}"
            )
          end

          false
        rescue StandardError => e
          if RUBY_ENGINE == 'opal'
            `console.error("[AI Expert] Error during single-action dispatch: " + #{e.message})`
          else
            LOGGER.error(
              "[AI Expert] Error during single-action dispatch: #{e.class}: #{e.message}"
            )
          end

          false
        ensure
          @tile_eval_cache.clear if @tile_eval_cache
        end

        ACTION_REGISTRY = {
          'bankrupt' => :collect_bankruptcy,
          'pass' => :collect_pass,
          'choose' => :collect_choices,
          'bid' => :collect_draft_and_bids,
          'buy_company' => :collect_draft_and_bids,
          'buy_companies' => :collect_draft_and_bids,
          'dividend' => :collect_dividends,
          'destination_connection' => :collect_destination_connections,
          'payout' => :collect_dividends,
          'withhold' => :collect_dividends,
          'half' => :collect_dividends,
          'split' => :collect_dividends,
          'buy_shares' => :collect_shares,
          'sell_shares' => :collect_shares,
          'par' => :collect_par,
          'merge' => :collect_merges,
          'assign' => :collect_assignments,
          'acquire_company' => :collect_acquire_companies,
          'special_buy' => :collect_special_buys,
          'buy_train' => :collect_trains,
          'discard_train' => :collect_trains,
          'run_routes' => :collect_routes,
          'lay_tile' => :collect_tiles,
          'place_token' => :collect_tokens,
          'issue' => :collect_issue_shares,
          'issue_shares' => :collect_issue_shares,
          'reissue' => :collect_issue_shares,
          'reissue_shares' => :collect_issue_shares,
          'corporate_sell_shares' => :collect_issue_shares,
          'redeem' => :collect_redeem_shares,
          'redeem_shares' => :collect_redeem_shares,
          'select_multiple_companies' => :collect_multiple_companies,
          'corporate_buy_shares' => :collect_redeem_shares,
        }.freeze

        OR_OPPORTUNITY_COLLECTORS = %i[
          collect_or_train_opportunities
          collect_or_company_opportunities
          collect_or_issue_opportunities
          collect_or_redeem_opportunities
        ].freeze

        BACKGROUND_ACTION_PREFIXES = ['program_'].freeze
        BACKGROUND_ACTIONS = %w[end_game log message undo redo].freeze

        def generate_legal_actions(step = nil, entity = nil)
          step ||= @game.round&.active_step
          return [] unless step

          entity ||= current_acting_entity(step)
          return [] unless entity

          step_actions = begin
            Array(step.actions(entity))
          rescue StandardError
            []
          end

          round_actions = begin
            Array(@game.round.actions_for(entity))
          rescue StandardError
            []
          end

          raw = step_actions + round_actions

          actions = raw.compact.map(&:to_s).uniq
          return [] if actions.empty?

          collectors = actions.filter_map { |name| ACTION_REGISTRY[name] }.uniq
          legal = []
          collectors.each do |collector_name|
            legal.concat(Array(send(collector_name, step, entity, actions)))
          rescue StandardError => e
            LOGGER.warn(
              "[AI ACTION REGISTRY] collector=#{collector_name} entity=#{entity_label(entity)} " \
              "failed=#{e.class}: #{e.message}"
            )
          end

          if operating_entity?(entity)
            OR_OPPORTUNITY_COLLECTORS.each do |collector_name|
              discovered = Array(send(collector_name, step, entity, actions))
              legal.concat(discovered)
            rescue StandardError => e
              LOGGER.warn(
                "[AI OR OPPORTUNITY] collector=#{collector_name} " \
                "entity=#{entity_label(entity)} failed=#{e.class}: #{e.message}"
              )
            end
          end

          unknown = actions.reject do |name|
            ACTION_REGISTRY.key?(name) || BACKGROUND_ACTIONS.include?(name) ||
              BACKGROUND_ACTION_PREFIXES.any? { |prefix| name.start_with?(prefix) }
          end
          if unknown.any?
            LOGGER.warn(
              "[AI UNRECOGNISED ACTION] step=#{step.class.name} entity=#{entity_label(entity)} " \
              "actions=#{unknown.join(',')}"
            )
          end

          legal = legal.compact.uniq.select { |action| action_belongs_to_entity?(action, entity) }

          if legal.empty? && actions.include?('pass')
            fallback = collect_pass(step, entity, actions)
            return fallback if fallback.any?
          end

          legal
        end

        def collect_merges(step, entity, actions)
          return [] unless actions.include?('merge')
          return [] unless defined?(Engine::Action::Merge)

          targets = []

          if step.respond_to?(:mergeable)
            begin
              targets.concat(Array(step.mergeable(entity)))
            rescue ArgumentError
              begin
                targets.concat(Array(step.mergeable))
              rescue StandardError
              end
            rescue StandardError
            end
          end

          if step.respond_to?(:mergeable_entities)
            begin
              targets.concat(Array(step.mergeable_entities))
            rescue ArgumentError
              begin
                targets.concat(Array(step.mergeable_entities(entity)))
              rescue StandardError
              end
            rescue StandardError
            end
          end

          targets.compact!
          targets.uniq!
          return [] if targets.empty?

          candidates = targets.flat_map do |target|
            [
              Engine::Action::Merge.new(
                entity,
                corporation: target,
              ),
              Engine::Action::Merge.new(
                entity,
                minor: target,
              ),
            ]
          rescue StandardError
            []
          end

          if RUBY_ENGINE != 'opal'
            candidates.select! do |action|
              trial = @game.clone(Array(@game.raw_actions))

              mapped =
                Engine::Action::Base.action_from_h(
                  action.to_h,
                  trial,
                )

              trial.process_action(
                mapped,
                add_auto_actions: true,
              ).maybe_raise!

              true
            rescue StandardError
              false
            end
          end

          candidates.uniq do |action|
            [
              action.entity&.id.to_s,
              action.corporation&.id.to_s,
              action.minor&.id.to_s,
            ]
          end
        end

        def collect_assignments(step, entity, actions)
          return [] unless actions.include?('assign')
          return [] unless defined?(Engine::Action::Assign)

          targets = []

          if step.respond_to?(:available_hex)
            Array(@game.hexes).each do |hex|
              targets << hex if step.available_hex(entity, hex)
            rescue StandardError
            end
          end

          if step.respond_to?(:assignable_corporations)
            begin
              targets.concat(Array(step.assignable_corporations(entity)))
            rescue ArgumentError
              begin
                targets.concat(Array(step.assignable_corporations))
              rescue StandardError
              end
            rescue StandardError
            end
          end

          targets.compact!
          targets.uniq!

          candidates = targets.map do |target|
            Engine::Action::Assign.new(
              entity,
              target: target,
            )
          end

          return candidates if RUBY_ENGINE == 'opal'

          candidates.select do |action|
            trial = @game.clone(Array(@game.raw_actions))
            mapped = Engine::Action::Base.action_from_h(action.to_h, trial)

            trial.process_action(
              mapped,
              add_auto_actions: true,
            ).maybe_raise!

            true
          rescue StandardError
            false
          end
        end

        def collect_acquire_companies(_step, entity, actions)
          return [] unless actions.include?('acquire_company')
          return [] unless defined?(Engine::Action::AcquireCompany)
          return [] unless @game.respond_to?(:purchasable_companies)

          companies =
            begin
              Array(@game.purchasable_companies(entity))
            rescue StandardError
              []
            end

          candidates = companies.map do |company|
            Engine::Action::AcquireCompany.new(
              entity,
              company: company,
            )
          end

          return candidates if RUBY_ENGINE == 'opal'

          candidates.select do |action|
            trial = @game.clone(Array(@game.raw_actions))
            mapped = Engine::Action::Base.action_from_h(action.to_h, trial)
            trial.process_action(mapped, add_auto_actions: true).maybe_raise!
            true
          rescue StandardError
            false
          end
        end

        def collect_special_buys(step, entity, actions)
          return [] unless actions.include?('special_buy')
          return [] unless defined?(Engine::Action::SpecialBuy)
          return [] unless step.respond_to?(:buyable_items)

          items =
            begin
              Array(step.buyable_items(entity))
            rescue StandardError
              []
            end

          candidates = items.map do |item|
            Engine::Action::SpecialBuy.new(
              entity,
              item: item,
            )
          end

          return candidates if RUBY_ENGINE == 'opal'

          candidates.select do |action|
            trial = @game.clone(Array(@game.raw_actions))
            mapped = Engine::Action::Base.action_from_h(action.to_h, trial)
            trial.process_action(mapped, add_auto_actions: true).maybe_raise!
            true
          rescue StandardError
            false
          end
        end

        def collect_multiple_companies(step, entity, actions)
          return [] unless actions.include?('select_multiple_companies')
          return [] unless defined?(Engine::Action::SelectMultipleCompanies)

          available =
            begin
              Array(step.available)
            rescue StandardError
              []
            end

          return [] if available.empty?

          required_count =
            begin
              if step.respond_to?(:cards_to_keep)
                step.cards_to_keep.to_i
              elsif step.respond_to?(:selection_count)
                step.selection_count.to_i
              else
                0
              end
            rescue StandardError
              0
            end

          if required_count <= 0
            begin
              required_count =
                step.instance_variable_get(:@cards_to_keep).to_i
            rescue StandardError
              required_count = 0
            end
          end

          selection_sizes =
            if required_count.positive?
              [required_count]
            else
              (1..available.size).to_a
            end

          candidates = []

          selection_sizes.each do |size|
            next if size <= 0
            next if size > available.size

            available.shuffle.combination(size).each do |companies|
              candidates << Engine::Action::SelectMultipleCompanies.new(
                entity,
                companies: companies,
              )

              break if candidates.size >= 50
            end

            break if candidates.size >= 50
          end

          return candidates if RUBY_ENGINE == 'opal'

          candidates.select do |action|
            trial =
              @game.clone(
                Array(@game.raw_actions)
              )

            mapped =
              Engine::Action::Base.action_from_h(
                action.to_h,
                trial,
              )

            trial.process_action(
              mapped,
              add_auto_actions: true,
            )

            trial.exception.nil?
          rescue StandardError
            false
          end
        end

        def operating_entity?(entity)
          return false unless @game.round.respond_to?(:operating?) && @game.round.operating?

          (entity.respond_to?(:corporation?) && entity.corporation?) ||
            (entity.respond_to?(:minor?) && entity.minor?)
        rescue StandardError
          false
        end

        def collect_or_train_opportunities(step, entity, actions)
          return [] unless step.respond_to?(:buyable_trains)

          collect_trains(step, entity, (actions + ['buy_train']).uniq)
        end

        def collect_or_company_opportunities(step, entity, _actions)
          buy_step = private_buy_step_for(step, entity)
          return [] unless buy_step

          collect_company_purchases(buy_step, entity)
        end

        def private_buy_step_for(default_step, entity)
          steps = if @game.round.respond_to?(:steps)
                    Array(@game.round.steps)
                  else
                    []
                  end

          found = steps.find do |candidate_step|
            next false unless candidate_step
            next false unless candidate_step.respond_to?(:buyable_companies) ||
                              candidate_step.respond_to?(:can_buy_company?)

            private_companies_for(candidate_step, entity).any?
          rescue StandardError
            false
          end

          found ||= default_step if default_step &&
            (default_step.respond_to?(:buyable_companies) || default_step.respond_to?(:can_buy_company?))
          found
        end

        def private_companies_for(step, entity)
          operating_player = if entity.respond_to?(:player?) && entity.player?
                               entity
                             elsif entity.respond_to?(:owner)
                               entity.owner
                             end
          return [] unless operating_player

          companies = if step.respond_to?(:buyable_companies)
                        begin
                          Array(step.buyable_companies(entity))
                        rescue StandardError
                          []
                        end
                      elsif step.respond_to?(:can_buy_company?) && @game.respond_to?(:companies)
                        Array(@game.companies).select do |company|
                          step.can_buy_company?(entity, company)
                        rescue StandardError
                          false
                        end
                      else
                        []
                      end

          companies.compact
            .reject { |company| company.respond_to?(:closed?) && company.closed? }
            .select do |company|
              company.respond_to?(:owner) && company.owner == operating_player && company.owner != entity
            end
        end

        def collect_or_issue_opportunities(step, entity, actions)
          supports_issue = step.respond_to?(:issuable_shares) ||
            step.respond_to?(:issueable_shares) || step.respond_to?(:issuable_bundles)
          return [] unless supports_issue

          collect_issue_shares(step, entity, (actions + ['issue_shares']).uniq)
        end

        def collect_or_redeem_opportunities(step, entity, actions)
          supports_redeem = step.respond_to?(:redeemable_shares) ||
            step.respond_to?(:redeemable_bundles)
          return [] unless supports_redeem

          collect_redeem_shares(step, entity, (actions + ['redeem_shares']).uniq)
        end

        def current_acting_entity(step)
          entity =
            begin
              step.current_entity if step.respond_to?(:current_entity)
            rescue StandardError
              nil
            end

          entity ||=
            begin
              @game.round.current_entity if @game.round.respond_to?(:current_entity)
            rescue StandardError
              nil
            end

          entity ||=
            begin
              @game.current_entity if @game.respond_to?(:current_entity)
            rescue StandardError
              nil
            end

          return nil unless entity

          return entity unless entity.respond_to?(:corporation?) &&
                               entity.corporation? &&
                               entity.respond_to?(:owner) &&
                               entity.owner

          forced_train_purchase =
            begin
              step.respond_to?(:must_buy_train?) &&
                step.must_buy_train?(entity)
            rescue StandardError
              false
            end

          return entity unless forced_train_purchase

          owner = entity.owner

          owner_actions =
            begin
              Array(@game.round.actions_for(owner)).map(&:to_s)
            rescue StandardError
              []
            end

          return entity unless owner_actions.include?('sell_shares')
          return entity unless owner.respond_to?(:shares_of)

          has_legal_owner_sale =
            Array(@game.corporations).any? do |corporation|
              owns_shares =
                begin
                  owner.shares_of(corporation).any?
                rescue StandardError
                  false
                end

              next false unless owns_shares

              bundles =
                begin
                  if @game.respond_to?(:bundles_for_corporation)
                    Array(
                      @game.bundles_for_corporation(
                        owner,
                        corporation,
                      )
                    )
                  else
                    []
                  end
                rescue StandardError
                  []
                end

              bundles.any? do |bundle|
                step.respond_to?(:can_sell?) &&
                  step.can_sell?(owner, bundle)
              rescue StandardError
                false
              end
            end

          has_legal_owner_sale ? owner : entity
        end

        private

        def entity_label(entity)
          return 'unknown' unless entity

          if entity.respond_to?(:id) && entity.id
            entity.id.to_s
          elsif entity.respond_to?(:name) && entity.name
            entity.name.to_s
          else
            entity.class.name.to_s
          end
        end

        def materialize_action_for_dispatch(action)
          return action unless action.is_a?(Engine::Action::LayTile)

          wanted = action.tile
          wanted_name = wanted.respond_to?(:name) ? wanted.name : nil
          candidates = @game.respond_to?(:tiles) ? Array(@game.tiles) : []
          supply_tile = candidates.find do |candidate|
            same_name = !wanted_name.nil? && candidate.respond_to?(:name) && candidate.name == wanted_name
            off_map = !candidate.respond_to?(:hex) || candidate.hex.nil?
            available = !@game.respond_to?(:tile_available?) || @game.tile_available?(candidate)
            same_name && off_map && available && !candidate.equal?(action.hex.tile)
          end
          return nil unless supply_tile

          Engine::Action::LayTile.new(
            action.entity,
            hex: action.hex,
            tile: supply_tile,
            rotation: action.rotation,
          )
        rescue StandardError => e
          if RUBY_ENGINE == 'opal'
            `console.warn("[AI Expert] Could not rematerialize tile action: " + #{e.message})`
          else
            LOGGER.warn(
              "[AI Expert] Could not rematerialize tile action: #{e.message}"
            )
          end
          nil
        end

        def action_belongs_to_entity?(action, expected_entity)
          return false unless action
          return true unless action.respond_to?(:entity)

          action.entity.equal?(expected_entity)
        end

        def execution_context_unchanged?(round, step, entity)
          return false unless @game.round.equal?(round)
          return false unless @game.round.active_step.equal?(step)

          current_acting_entity(step).equal?(entity)
        end

        def underscore(name)
          name.to_s
              .gsub(/([a-z\d])([A-Z])/, '\1_\2')
              .downcase
        end

        def corporation_revenue(corp)
          return 0 unless corp
          return corp.last_revenue.to_i if corp.respond_to?(:last_revenue)

          history = corp.respond_to?(:operating_history) ? corp.operating_history : nil
          history && history.last ? history.last[:revenue].to_i : 0
        rescue StandardError
          0
        end

        def next_depot_train_price(entity = nil)
          if entity && @game.respond_to?(:min_depot_price)
            begin
              price = @game.min_depot_price(entity).to_i
              return price if price.positive?
            rescue ArgumentError
              price = @game.min_depot_price.to_i
              return price if price.positive?
            rescue StandardError
            end
          end

          if @game.respond_to?(:depot) && @game.depot
            if @game.depot.respond_to?(:min_depot_price)
              price = @game.depot.min_depot_price.to_i
              return price if price.positive?
            end
            return (@game.depot.min_depot_train&.price || 0).to_i if @game.depot.respond_to?(:min_depot_train)
          end

          0
        rescue StandardError
          0
        end

        def emergency_train_sale_context?(step, entity)
          return false unless step && entity && entity.respond_to?(:player?) && entity.player?

          corporation = step.respond_to?(:current_entity) ? step.current_entity : nil
          return false unless corporation &&
                              corporation.respond_to?(:corporation?) &&
                              corporation.corporation? &&
                              corporation.respond_to?(:owner) &&
                              corporation.owner == entity

          must_buy = step.respond_to?(:must_buy_train?) && step.must_buy_train?(corporation)
          return false unless must_buy

          Array(@game.round.actions_for(entity)).map(&:to_s).include?('sell_shares')
        rescue StandardError
          false
        end

        def emergency_train_shortfall(step, entity)
          return 0 unless emergency_train_sale_context?(step, entity)

          corporation = step.current_entity
          trains = step.respond_to?(:buyable_trains) ? Array(step.buyable_trains(corporation)) : []
          cheapest = trains.filter_map { |t| t.price.to_i if t.respond_to?(:price) && t.price.to_i.positive? }.min
          cheapest ||= next_depot_train_price(corporation)
          return 0 unless cheapest.to_i.positive?

          corp_cash = corporation.respond_to?(:cash) ? corporation.cash.to_i : 0
          player_cash = entity.respond_to?(:cash) ? entity.cash.to_i : 0
          [cheapest.to_i - corp_cash - player_cash, 1].max
        rescue StandardError
          0
        end

        def evaluate_home_location_value(corp)
          return 0 unless corp && corp.respond_to?(:coordinates) && @game.respond_to?(:hex_by_id)

          coords = Array(corp.coordinates).flatten.compact
          return 0 if coords.empty?

          total = 0
          coords.each do |coord|
            hex = @game.hex_by_id(coord.to_s)
            next unless hex && hex.respond_to?(:tile) && hex.tile

            total += printed_hex_revenue(hex.tile)
            neighbors = hex.respond_to?(:neighbors) && hex.neighbors ? hex.neighbors.values : []
            Array(neighbors).compact.each do |n1|
              total += (printed_hex_revenue(n1.tile) * 0.6).to_i if n1.respond_to?(:tile) && n1.tile
              cost = n1.respond_to?(:cost) ? n1.cost.to_i : 0
              total -= (cost / 10).to_i if cost.positive?
            end
          end

          [total, 0].max
        rescue StandardError
          0
        end

        def active_operating_routes_revenue
          routes = if @routes && @routes.any?
                     @routes
                   elsif @game.round.respond_to?(:routes)
                     Array(@game.round.routes)
                   else
                     []
                   end
          return 0 if routes.empty?

          if @game.respond_to?(:routes_revenue)
            @game.routes_revenue(routes).to_i
          else
            routes.sum { |r| r.respond_to?(:revenue) ? r.revenue.to_i : 0 }.to_i
          end
        rescue StandardError
          0
        end

        def dividend_retained_cash(step, entity, kind, total_revenue)
          if step.respond_to?(:dividend_options)
            opts = step.dividend_options(entity)
            if opts.is_a?(Hash)
              info = opts[kind.to_sym] || opts[kind.to_s]
              return info[:corporation].to_i if info.is_a?(Hash) && info.key?(:corporation)
            end
          end

          case kind.to_s
          when 'withhold'
            total_revenue.to_i
          when 'half', 'split'
            (total_revenue.to_i / 2.0).floor
          else
            0
          end
        rescue StandardError
          kind.to_s == 'withhold' ? total_revenue.to_i : 0
        end

        def par_float_units_needed(corp)
          share_percent = corp.respond_to?(:share_percent) && corp.share_percent.to_i.positive? ? corp.share_percent.to_i : 10
          float_pct = if corp.respond_to?(:percent_to_float) && corp.percent_to_float
                        corp.percent_to_float.to_i
                      elsif corp.respond_to?(:float_percent) && corp.float_percent
                        corp.float_percent.to_i
                      else
                        60
                      end
          pres_pct = corp.presidents_share&.percent.to_i
          pres_pct = share_percent unless pres_pct.positive?
          ([float_pct, pres_pct].max.to_f / share_percent).ceil
        rescue StandardError
          6
        end

        def extract_features(action, step, entity, all_actions)
          f = {}
          f[:player_cash] = entity.respond_to?(:cash) ? entity.cash.to_i : 0
          cert_count =
            if entity.respond_to?(:shares) && @game.respond_to?(:num_certs)
              begin
                @game.num_certs(entity)
              rescue StandardError
                0
              end
            else
              0
            end

          cert_limit =
            if entity.respond_to?(:shares) && @game.respond_to?(:cert_limit)
              begin
                @game.cert_limit(entity)
              rescue StandardError
                999
              end
            else
              999
            end
          f[:cert_count] = cert_count
          f[:cert_limit] = cert_limit
          f[:certs_free] = cert_limit - cert_count

          my_unfloated = Array(@game.corporations).select do |c|
            c.owner == entity && (!c.respond_to?(:floated?) || !c.floated?)
          end
          f[:unfloated_presidencies] = my_unfloated.size

          can_buy_unfloated_own = all_actions.any? do |a|
            a.is_a?(Engine::Action::BuyShares) &&
              a.bundle&.corporation &&
              my_unfloated.include?(a.bundle.corporation)
          end

          case action
          when Engine::Action::Pass
            f[:action_type] = 'pass'

          when Engine::Action::BuyShares
            f[:action_type] = 'buy_shares'
            bundle = action.bundle
            corp = bundle&.corporation
            if corp
              f[:corp_id] = corp.id
              f[:is_floated] = corp.respond_to?(:floated?) ? corp.floated? : true
              f[:player_is_president] = (corp.owner == entity)
              f[:other_is_president] = (!corp.owner.nil? && corp.owner != entity)
              f[:player_percent] = entity.respond_to?(:percent_of) ? entity.percent_of(corp) : 0
              f[:corp_trains_count] = corp.respond_to?(:trains) ? corp.trains.size : 0
              f[:share_price] = bundle.price.to_i
              is_market = (@game.respond_to?(:share_pool) && bundle.owner == @game.share_pool)
              f[:source] = is_market ? :market : :ipo

              min_train = next_depot_train_price(corp)
              f[:corp_can_buy_train] = min_train.positive? ? (corp.cash.to_i >= min_train) : (corp.cash.to_i >= 100)

              opp_percents = Array(@game.players).reject { |p| p == entity }.map do |p|
                p.respond_to?(:percent_of) ? p.percent_of(corp) : 0
              end
              max_opp = opp_percents.max || 0
              f[:presidency_threatened] = (f[:player_is_president] && max_opp >= (f[:player_percent] - 10))

              f[:market_price_lt_ipo] =
                if is_market && corp.respond_to?(:par_price) && corp.par_price
                  bundle.price.to_i < corp.par_price.price.to_i
                else
                  false
                end
            end

          when Engine::Action::Par
            f[:action_type] = 'par'
            corp = action.corporation
            sp = action.share_price
            price_val = sp.respond_to?(:price) ? sp.price.to_i : sp.to_i
            f[:par_price] = price_val

            needed_shares = par_float_units_needed(corp)
            cost_to_self_float = price_val * needed_shares
            f[:can_self_float] = (f[:player_cash] >= cost_to_self_float)

            cheaper_floatable = all_actions.any? do |a|
              if a.is_a?(Engine::Action::Par) && a != action
                p = a.share_price.respond_to?(:price) ? a.share_price.price.to_i : a.share_price.to_i
                other_units = par_float_units_needed(a.corporation)
                p < price_val && (f[:player_cash] >= (p * other_units))
              else
                false
              end
            end
            f[:cheaper_floatable_par_exists] = cheaper_floatable
            f[:home_location_value] = evaluate_home_location_value(corp)

          when Engine::Action::SellShares
            f[:action_type] = if entity.respond_to?(:corporation?) && entity.corporation?
                                'issue_shares'
                              else
                                'sell_shares'
                              end
            bundle = action.bundle
            corp = bundle&.corporation
            f[:bundle_price] = bundle&.price.to_i
            f[:bundle_num_shares] = bundle.respond_to?(:num_shares) ? bundle.num_shares.to_i : 1

            if corp
              f[:corp_id] = corp.id
              f[:player_is_president_of_sold] = (corp.owner == entity)
              pres_shares = corp.presidents_share&.num_shares || 2
              f[:causes_president_dump] =
                if bundle.respond_to?(:can_dump?)
                  (corp.owner == entity) && !bundle.can_dump?(entity)
                else
                  (corp.owner == entity) && (f[:bundle_num_shares] >= pres_shares)
                end
            else
              f[:player_is_president_of_sold] = false
              f[:causes_president_dump] = false
            end

            f[:must_sell] = (step.respond_to?(:must_sell?) && step.must_sell?(entity)) || (f[:certs_free] < 0)
            f[:emergency_train_sale] = emergency_train_sale_context?(step, entity)
            shortfall = f[:emergency_train_sale] ? emergency_train_shortfall(step, entity) : 0
            f[:covers_emergency_shortfall] = f[:emergency_train_sale] && (f[:bundle_price] >= shortfall)
            f[:emergency_shortfall_overshoot] =
              f[:covers_emergency_shortfall] ? (f[:bundle_price] - shortfall) : 0

            f[:need_cash_for_unfloated_presidency] =
              (f[:unfloated_presidencies] > 0) && !can_buy_unfloated_own

            has_par_or_buy = all_actions.any? do |a|
              a.is_a?(Engine::Action::Par) || a.is_a?(Engine::Action::BuyShares)
            end
            f[:voluntary_sell_roll] =
              if !has_par_or_buy && f[:bundle_num_shares] == 1
                if f[:player_is_president_of_sold]
                  AiExpertRules.sell_own_company_shares?(@game, entity)
                else
                  AiExpertRules.sell_other_company_shares?(@game, entity)
                end
              else
                false
              end

            f[:sell_justified] =
              f[:emergency_train_sale] ||
              f[:must_sell] ||
              f[:need_cash_for_unfloated_presidency] ||
              f[:voluntary_sell_roll]

          when Engine::Action::Dividend
            f[:action_type] = 'dividend'
            f[:dividend_kind] = action.kind.to_s
            corp = entity
            f[:corp_trains_count] = corp.respond_to?(:trains) ? corp.trains.size : 0
            f[:revenue] = active_operating_routes_revenue
            retained = dividend_retained_cash(step, corp, action.kind, f[:revenue])

            has_perm = Array(corp.trains).any? { |t| permanent_train?(t) }
            perm_without_retention = can_buy_permanent_train?(corp, 0)
            perm_with_retention = can_buy_permanent_train?(corp, retained)

            f[:retention_enables_permanent_train] =
              !has_perm && !perm_without_retention && perm_with_retention
            f[:withhold_enables_permanent_train] = f[:retention_enables_permanent_train]

            min_train_price = next_depot_train_price(corp)
            corp_cash = corp.respond_to?(:cash) ? corp.cash.to_i : 0
            f[:trainless_needs_cash] =
              f[:corp_trains_count].zero? && min_train_price.positive? && (corp_cash < min_train_price)

            reaches_next_train =
              f[:trainless_needs_cash] && ((corp_cash + retained) >= min_train_price)
            f[:retention_enables_needed_train] =
              f[:retention_enables_permanent_train] || reaches_next_train

          when Engine::Action::BuyTrain
            f[:action_type] = 'buy_train'
            train = action.train
            f[:train_from_depot] =
              (train.owner == @game.depot || (train.respond_to?(:from_depot?) && train.from_depot?))
            f[:is_permanent_train] = permanent_train?(train)
            f[:train_cost] = (action.price || train.price || 0).to_i
            corp = entity
            f[:corp_trains_count] = corp.respond_to?(:trains) ? corp.trains.size : 0

          when Engine::Action::DiscardTrain
            f[:action_type] = 'discard_train'
            f[:train_cost] = (action.train&.price || 0).to_i

          when Engine::Action::LayTile
            f[:action_type] = 'lay_tile'
            eval_data = @tile_eval_cache[action] || {}
            f.merge!(eval_data)
            tile_cost = (f[:tile_cost] || calculate_tile_cost(step, entity, action.hex, action.tile)).to_i
            f[:tile_cost] = tile_cost
            corp_cash = entity.respond_to?(:cash) ? entity.cash.to_i : 0
            trains_count = entity.respond_to?(:trains) ? entity.trains.size : 0
            min_train_price = next_depot_train_price(entity)
            f[:breaks_train_budget] =
              trains_count.zero? &&
              tile_cost.positive? &&
              min_train_price.positive? &&
              (corp_cash >= min_train_price) &&
              ((corp_cash - tile_cost) < min_train_price)

          when Engine::Action::PlaceToken
            f[:action_type] = 'place_token'
            f.merge!(@token_eval_cache[action] || {})

          when Engine::Action::Choose
            f[:action_type] = 'choose'
          end

          f
        end

        def collect_pass(_step, entity, actions)
          return [] unless actions.include?('pass')
          return [] unless defined?(Engine::Action::Pass)

          action = Engine::Action::Pass.new(entity)

          if RUBY_ENGINE != 'opal'
            begin
              trial = @game.clone(Array(@game.raw_actions))

              mapped =
                Engine::Action::Base.action_from_h(
                  action.to_h,
                  trial,
                )

              trial.process_action(
                mapped,
                add_auto_actions: true,
              )

              return [] if trial.exception
            rescue StandardError
              return []
            end
          end

          [action]
        end

        def collect_choices(step, entity, actions)
          return [] unless actions.include?('choose')

          choices = if step.respond_to?(:choices_for)
                      begin; step.choices_for(entity); rescue StandardError; nil; end
                    elsif step.respond_to?(:choices)
                      begin; step.choices(entity); rescue StandardError; begin
                        step.choices
                      rescue StandardError
                        nil
                      end; end
                    end

          case choices
          when Hash
            choices.keys.map { |k| Engine::Action::Choose.new(entity, choice: k) }
          when Array
            choices.map { |c| Engine::Action::Choose.new(entity, choice: c.is_a?(Array) && c.size == 2 ? c.first : c) }
          else
            []
          end
        end

        def permanent_train?(train)
          return train.permanent? if train.respond_to?(:permanent?)
          return !train.rusts_on if train.respond_to?(:rusts_on)
          return !train.obsolete_on if train.respond_to?(:obsolete_on)

          false
        rescue StandardError
          false
        end

        def can_buy_permanent_train?(entity, extra_cash = 0)
          cash = (entity.respond_to?(:cash) ? entity.cash.to_i : 0) + extra_cash.to_i
          trains = @game.depot.respond_to?(:depot_trains) ? @game.depot.depot_trains : @game.depot.upcoming
          Array(trains).any? { |t| permanent_train?(t) && t.price.to_i <= cash }
        rescue StandardError
          false
        end

        def same_director_train?(buyer, train)
          seller = train.respond_to?(:owner) ? train.owner : nil
          seller && seller != @game.depot && buyer.respond_to?(:owner) && seller.respond_to?(:owner) && buyer.owner == seller.owner
        rescue StandardError
          false
        end

        def collect_draft_and_bids(step, entity, actions)
          legal = []

          if actions.include?('bid')
            legal.concat(
              collect_auction_bids(step, entity)
            )
          end

          if (actions & %w[buy_company buy_companies]).any?
            legal.concat(
              collect_company_purchases(step, entity)
            )
          end

          if RUBY_ENGINE != 'opal'
            legal.select! do |action|
              trial =
                @game.clone(Array(@game.raw_actions))

              mapped =
                Engine::Action::Base.action_from_h(
                  action.to_h,
                  trial,
                )

              trial.process_action(
                mapped,
                add_auto_actions: true,
              )

              trial.exception.nil?
            rescue StandardError
              false
            end
          end

          legal
        end

        def collect_auction_bids(step, entity)
          return [] unless defined?(Engine::Action::Bid)

          cash = entity.respond_to?(:cash) ? entity.cash.to_i : 0
          candidates = auction_bid_companies(step)
          return [] if candidates.empty?

          candidates.filter_map do |candidate|
            is_minor =
              candidate.respond_to?(:minor?) &&
              candidate.minor?

            is_corporation =
              candidate.respond_to?(:corporation?) &&
              candidate.corporation?

            current = current_company_bid(step, candidate)

            price =
              if is_minor
                0
              elsif current.positive?
                current + bid_increment(step, candidate)
              else
                opening_bid(step, candidate)
              end

            maximum =
              maximum_bid(
                step,
                entity,
                candidate,
                cash,
              )

            next if price.negative?
            next if price > cash
            next if price > maximum

            if step.respond_to?(:can_bid?)
              can_bid =
                begin
                  step.can_bid?(entity, candidate, price)
                rescue ArgumentError
                  begin
                    step.can_bid?(entity, price)
                  rescue ArgumentError
                    begin
                      step.can_bid?(entity, candidate)
                    rescue StandardError
                      false
                    end
                  rescue StandardError
                    false
                  end
                rescue StandardError
                  false
                end

              next unless can_bid
            end

            kwargs = { price: price }

            if is_minor
              kwargs[:minor] = candidate
            elsif is_corporation
              kwargs[:corporation] = candidate
            else
              kwargs[:company] = candidate
            end

            Engine::Action::Bid.new(
              entity,
              **kwargs,
            )
          rescue StandardError
            nil
          end
        end

        def auction_bid_companies(step)
          companies = []

          if step.respond_to?(:auctioning)
            auctioning = begin
              step.auctioning
            rescue StandardError
              nil
            end
            companies << auctioning if auctioning
          end

          companies.concat(Array(step.available)) if companies.empty? && step.respond_to?(:available)

          companies.concat(Array(step.companies)) if companies.empty? && step.respond_to?(:companies)

          companies.concat(Array(@game.companies)) if companies.empty? && @game.respond_to?(:companies)

          companies.compact.uniq.reject do |company|
            company.respond_to?(:closed?) && company.closed?
          end
        rescue StandardError
          []
        end

        def current_company_bid(step, company)
          values = []

          if step.respond_to?(:highest_bid)
            highest = begin
              step.highest_bid(company)
            rescue ArgumentError
              begin
                step.highest_bid
              rescue StandardError
                nil
              end
            rescue StandardError
              nil
            end

            if highest.respond_to?(:price)
              values << highest.price.to_i
            elsif highest.is_a?(Numeric)
              values << highest.to_i
            end
          end

          if step.respond_to?(:current_bid)
            current = begin
              step.current_bid(company)
            rescue ArgumentError
              begin
                step.current_bid
              rescue StandardError
                nil
              end
            rescue StandardError
              nil
            end

            if current.respond_to?(:price)
              values << current.price.to_i
            elsif current.is_a?(Numeric)
              values << current.to_i
            end
          end

          if step.respond_to?(:bids)
            bids = begin
              step.bids
            rescue StandardError
              nil
            end

            relevant = if bids.is_a?(Hash)
                         bids[company] ||
                           (company.respond_to?(:id) && bids[company.id]) ||
                           (company.respond_to?(:id) && bids[company.id.to_s]) ||
                           bids.values.flatten
                       else
                         bids
                       end

            Array(relevant).each do |bid|
              next if bid.respond_to?(:company) && bid.company != company

              if bid.respond_to?(:price)
                values << bid.price.to_i
              elsif bid.is_a?(Numeric)
                values << bid.to_i
              elsif bid.is_a?(Array)
                numeric = bid.reverse.find { |value| value.is_a?(Numeric) }
                values << numeric.to_i if numeric
              end
            end
          end

          values.max.to_i
        rescue StandardError
          0
        end

        def bid_increment(step, company)
          value = begin; step.min_increment(company) if step.respond_to?(:min_increment); rescue StandardError; nil; end
          value ||= begin; step.bid_increment(company) if step.respond_to?(:bid_increment); rescue StandardError; nil; end
          value = 5 unless value.to_i.positive?
          value.to_i
        end

        def opening_bid(step, company)
          value = begin; step.min_bid(company) if step.respond_to?(:min_bid); rescue StandardError; nil; end
          value ||= company.min_price if company.respond_to?(:min_price)
          value ||= company.value if company.respond_to?(:value)
          value.to_i
        end

        def maximum_bid(step, entity, company, cash)
          value = begin; step.max_bid(entity, company) if step.respond_to?(:max_bid); rescue StandardError; nil; end
          value ||= begin; step.maximum_bid(entity, company) if step.respond_to?(:maximum_bid); rescue StandardError; nil; end
          [value.nil? ? cash : value.to_i, cash].min
        end

        def collect_company_purchases(step, entity)
          return [] unless defined?(Engine::Action::BuyCompany)

          cash =
            if entity.respond_to?(:cash)
              entity.cash.to_i
            else
              0
            end

          private_companies =
            private_companies_for(
              step,
              entity,
            )

          bank_companies =
            begin
              if step.respond_to?(:buyable_bank_owned_companies)
                Array(
                  step.buyable_bank_owned_companies(entity)
                )
              elsif @game.respond_to?(:buyable_bank_owned_companies)
                Array(
                  @game.buyable_bank_owned_companies
                )
              else
                []
              end
            rescue StandardError
              []
            end

          companies =
            (
              private_companies +
              bank_companies
            ).compact.uniq

          companies.filter_map do |company|
            bank_owned =
              bank_companies.include?(company)

            if bank_owned
              price =
                if company.respond_to?(:value)
                  company.value.to_i
                else
                  0
                end

              next unless price.positive?
              next if price > cash

              Engine::Action::BuyCompany.new(
                entity,
                company: company,
                price: price,
              )
            else
              min_price =
                if step.respond_to?(:min_price)
                  begin
                    step.min_price(company)
                  rescue StandardError
                    nil
                  end
                elsif company.respond_to?(:min_price)
                  company.min_price
                else
                  1
                end

              max_price =
                if step.respond_to?(:max_price)
                  begin
                    step.max_price(entity, company)
                  rescue StandardError
                    nil
                  end
                elsif company.respond_to?(:max_price)
                  company.max_price
                else
                  cash
                end

              next if min_price.nil? || max_price.nil?

              min_price = min_price.to_i
              max_price = [max_price.to_i, cash].min

              next if max_price < min_price

              Engine::Action::BuyCompany.new(
                entity,
                company: company,
                price: max_price,
              )
            end
          rescue StandardError => e
            LOGGER.warn(
              "[AI COMPANY PURCHASE] #{e.class}: #{e.message}"
            )
            nil
          end
        end

        # Collects all legal dividend options for the current step.
        # Strategic choice between payout, half/split, and withhold is delegated
        # entirely to AiExpertRules (OR_DIV01..OR_DIV07).
        def collect_dividends(step, entity, actions)
          return [] unless (actions & %w[dividend payout withhold half split]).any?

          raw_opts =
            if step.respond_to?(:dividend_options)
              begin
                step.dividend_options(entity)
              rescue StandardError
                []
              end
            elsif step.respond_to?(:dividend_types)
              begin
                step.dividend_types
              rescue StandardError
                []
              end
            else
              []
            end

          opts =
            (raw_opts.is_a?(Hash) ? raw_opts.keys : Array(raw_opts))
              .map(&:to_s)

          opts = (actions & %w[payout withhold half split]) if opts.empty?
          opts.reject! { |option| option == 'dividend' }

          opts.map do |kind|
            Engine::Action::Dividend.new(
              entity,
              kind: kind,
            )
          end
        end

        def apply_share_strategy(actions, entity)
          actions = Array(actions)
          return actions if actions.empty?

          return apply_corporate_share_strategy(actions, entity) if entity.respond_to?(:corporation?) && entity.corporation?

          apply_player_share_focus(actions, entity)
        end

        # Preserves all legal Par, BuyShares, justified SellShares, and Pass
        # actions so AiExpertRules scores them on a unified scale.
        # Mandatory emergency train sales and engine-forced sales isolate
        # sell_actions because the engine requires a sale before anything else.
        def apply_player_share_focus(actions, entity)
          return actions unless entity.respond_to?(:player?) && entity.player?

          sell_actions =
            actions.select do |action|
              action.is_a?(Engine::Action::SellShares)
            end

          step = @game.round.active_step

          return sell_actions if emergency_train_sale_context?(step, entity) && sell_actions.any?

          forced_sale =
            sell_actions.any? do |action|
              features =
                extract_features(
                  action,
                  step,
                  entity,
                  actions,
                )

              features[:must_sell]
            rescue StandardError
              false
            end

          return sell_actions if forced_sale

          # In normal Stock Rounds, restrict optional sales to 1-share bundles
          # and let AiExpertRules decide between Par, BuyShares, SellShares, and Pass.
          actions.reject do |action|
            action.is_a?(Engine::Action::SellShares) &&
              action.bundle.respond_to?(:num_shares) &&
              action.bundle.num_shares.to_i > 1
          end
        end

        def apply_corporate_share_strategy(actions, entity)
          issue_actions = actions.select do |action|
            action.is_a?(Engine::Action::SellShares)
          end

          redeem_actions = actions.select do |action|
            corporate_redeem_action?(action)
          end

          if redeem_actions.any? &&
             AiExpertRules.redeem_shares?(@game, entity)
            return redeem_actions
          end

          if issue_actions.any? &&
             AiExpertRules.issue_shares?(@game, entity)
            return issue_actions
          end

          alternatives = actions.reject do |action|
            issue_actions.include?(action) ||
              redeem_actions.include?(action)
          end

          alternatives.empty? ? actions : alternatives
        end

        def corporate_redeem_action?(action)
          classes = []

          classes << Engine::Action::Redeem if defined?(Engine::Action::Redeem)
          classes << Engine::Action::RedeemShares if defined?(Engine::Action::RedeemShares)
          classes << Engine::Action::CorporateBuyShares if defined?(Engine::Action::CorporateBuyShares)
          classes << Engine::Action::BuyShares if defined?(Engine::Action::BuyShares)

          classes.any? { |klass| action.is_a?(klass) }
        end

        def share_action_corporation(action)
          return action.bundle.corporation if action.respond_to?(:bundle) && action.bundle

          if action.respond_to?(:shares)
            share = Array(action.shares).first
            return share.corporation if share&.respond_to?(:corporation)
          end

          nil
        rescue StandardError
          nil
        end

        def collect_shares(step, entity, actions)
          return [] if entity.respond_to?(:corporation?) && entity.corporation?
          return [] unless entity.respond_to?(:shares)

          legal = []
          player_cash = entity.respond_to?(:cash) ? entity.cash : 0
          cert_limit = @game.respond_to?(:cert_limit) ? @game.cert_limit(entity) : 999
          current_certs = @game.respond_to?(:num_certs) ? @game.num_certs(entity) : 0

          if actions.include?('buy_shares')
            candidate_bundles = []

            if step.respond_to?(:buyable_shares)
              begin
                candidate_bundles.concat(
                  Array(step.buyable_shares(entity))
                )
              rescue StandardError
              end
            end

            if step.respond_to?(:buyable_bundles)
              begin
                candidate_bundles.concat(
                  Array(step.buyable_bundles(entity))
                )
              rescue StandardError
              end
            end

            if candidate_bundles.empty?
              @game.corporations.each do |corporation|
                next unless corporation.ipoed || corporation.share_price

                ipo_shares =
                  if corporation.respond_to?(:ipo_shares) &&
                     corporation.ipo_shares&.any?
                    corporation.ipo_shares
                  elsif corporation.respond_to?(:shares)
                    corporation.shares
                  else
                    []
                  end

                unissued =
                  ipo_shares.select do |share|
                    share.owner == corporation ||
                      (
                        share.respond_to?(:from_depot?) &&
                        share.from_depot?
                      )
                  end

                unissued = ipo_shares if unissued.empty?

                unissued.uniq(&:percent).each do |share|
                  candidate_bundles <<
                    if share.respond_to?(:to_bundle)
                      share.to_bundle
                    else
                      Engine::ShareBundle.new(share)
                    end
                end

                pool =
                  (@game.share_pool if @game.respond_to?(:share_pool))

                pool_shares =
                  if pool.respond_to?(:shares_of)
                    pool.shares_of(corporation)
                  else
                    []
                  end

                if pool_shares.empty? &&
                   @game.respond_to?(:bank) &&
                   @game.bank.respond_to?(:shares_of)
                  pool_shares =
                    @game.bank.shares_of(corporation)
                end

                pool_shares.uniq(&:percent).each do |share|
                  candidate_bundles <<
                    if share.respond_to?(:to_bundle)
                      share.to_bundle
                    else
                      Engine::ShareBundle.new(share)
                    end
                end
              end
            end

            candidate_bundles.compact.uniq.each do |candidate|
              bundle =
                if candidate.respond_to?(:num_shares)
                  candidate
                elsif candidate.respond_to?(:to_bundle)
                  candidate.to_bundle
                elsif defined?(Engine::ShareBundle)
                  Engine::ShareBundle.new(candidate)
                else
                  candidate
                end

              next unless bundle

              if step.respond_to?(:can_buy?)
                begin
                  next unless step.can_buy?(entity, bundle)
                rescue StandardError
                  next
                end
              end

              price =
                if bundle.respond_to?(:price)
                  bundle.price.to_i
                else
                  0
                end

              next if price > player_cash

              shares_count =
                if bundle.respond_to?(:num_shares)
                  bundle.num_shares
                elsif bundle.respond_to?(:shares)
                  bundle.shares.size
                else
                  1
                end

              next if current_certs + shares_count > cert_limit

              if step.respond_to?(:did_sell?)
                begin
                  next if step.did_sell?(
                    bundle.corporation,
                    entity,
                  )
                rescue StandardError
                end
              end

              shares =
                if bundle.respond_to?(:shares) &&
                   bundle.shares&.any?
                  bundle.shares
                else
                  Array(bundle)
                end

              kwargs = {
                shares: shares,
              }

              if bundle.respond_to?(:percent) &&
                 bundle.percent
                kwargs[:percent] = bundle.percent
              end

              if bundle.respond_to?(:share_price) &&
                 bundle.share_price
                kwargs[:share_price] = bundle.share_price
              end

              legal <<
                Engine::Action::BuyShares.new(
                  entity,
                  **kwargs,
                )
            end
          end

          if actions.include?('sell_shares')
            corporations =
              @game.corporations.select do |corporation|
                entity.shares_of(corporation).any?
              rescue StandardError
                false
              end

            corporations.each do |corporation|
              bundles = []

              if step.respond_to?(:sellable_bundles)
                begin
                  bundles.concat(
                    Array(
                      step.sellable_bundles(
                        entity,
                        corporation,
                      )
                    )
                  )
                rescue StandardError
                end
              end

              if step.respond_to?(:bundles_for_corporation)
                begin
                  bundles.concat(
                    Array(
                      step.bundles_for_corporation(
                        entity,
                        corporation,
                      )
                    )
                  )
                rescue StandardError
                end
              end

              if @game.respond_to?(:bundles_for_corporation)
                begin
                  bundles.concat(
                    Array(
                      @game.bundles_for_corporation(
                        entity,
                        corporation,
                      )
                    )
                  )
                rescue StandardError
                end
              end

              if @game.respond_to?(:sellable_bundles)
                begin
                  bundles.concat(
                    Array(
                      @game.sellable_bundles(
                        entity,
                        corporation,
                      )
                    )
                  )
                rescue StandardError
                end
              end

              bundles.compact.uniq.each do |bundle|
                if step.respond_to?(:can_sell?)
                  can_sell =
                    begin
                      step.can_sell?(
                        entity,
                        bundle,
                      )
                    rescue StandardError
                      false
                    end

                  next unless can_sell
                end

                shares =
                  if bundle.respond_to?(:shares) &&
                     bundle.shares&.any?
                    bundle.shares
                  else
                    Array(bundle)
                  end

                next if shares.empty?

                kwargs = {
                  shares: shares,
                }

                if bundle.respond_to?(:percent) &&
                   bundle.percent
                  kwargs[:percent] = bundle.percent
                end

                if bundle.respond_to?(:share_price) &&
                   bundle.share_price
                  kwargs[:share_price] = bundle.share_price
                end

                legal <<
                  Engine::Action::SellShares.new(
                    entity,
                    **kwargs,
                  )
              end
            end
          end

          return legal if RUBY_ENGINE == 'opal'

          legal.select do |action|
            trial = @game.clone(Array(@game.raw_actions))

            mapped =
              Engine::Action::Base.action_from_h(
                action.to_h,
                trial,
              )

            trial.process_action(
              mapped,
              add_auto_actions: true,
            )

            trial.exception.nil?
          rescue StandardError
            false
          end
        end

        # Generates up to two Par candidates per unstarted corporation:
        # 1. The highest legal par price where the player can afford the initial
        #    president certificate (preserving 1837 par generation).
        # 2. The highest legal par price where the player can afford the entire
        #    float requirement (enabling SR03 and SR04 in AiExpertRules).
        def collect_par(step, entity, actions)
          return [] unless actions.include?('par')

          legal = []

          if step.respond_to?(:companies_pending_par)
            pending = Array(step.companies_pending_par).first

            if pending
              corporation =
                if pending.respond_to?(:corporation?) && pending.corporation?
                  pending
                elsif pending.respond_to?(:all_abilities)
                  share_ability = pending.all_abilities.find do |ability|
                    ability.respond_to?(:type) &&
                      ability.type == :shares &&
                      ability.respond_to?(:shares) &&
                      ability.shares&.any?
                  end

                  share_ability&.shares&.first&.corporation
                end

              if corporation
                prices =
                  begin
                    Array(step.get_par_prices(entity, corporation))
                  rescue StandardError
                    []
                  end

                best_price = prices
                  .map { |entry| entry.is_a?(Array) ? entry.first : entry }
                  .compact
                  .max_by do |price|
                    price.respond_to?(:price) ? price.price.to_i : price.to_i
                  end

                if best_price
                  slot =
                    begin
                      if @game.respond_to?(:par_chart) &&
                         @game.par_chart[best_price]
                        @game.par_chart[best_price].index(nil)
                      end
                    rescue StandardError
                      nil
                    end

                  kwargs = {
                    corporation: corporation,
                    share_price: best_price,
                  }
                  kwargs[:slot] = slot unless slot.nil?

                  return [
                    Engine::Action::Par.new(
                      entity,
                      **kwargs,
                    ),
                  ]
                end
              end
            end
          end

          unfloated = @game.corporations.select do |corporation|
            if corporation.respond_to?(:ipoed)
              !corporation.ipoed
            else
              begin
                !corporation.owner
              rescue StandardError
                true
              end
            end
          end

          player_cash =
            entity.respond_to?(:cash) ? entity.cash.to_i : 0

          unfloated.each do |corporation|
            if step.respond_to?(:can_par?)
              can_par =
                begin
                  step.can_par?(corporation, entity)
                rescue ArgumentError
                  step.can_par?(entity, corporation)
                rescue StandardError
                  false
                end

              next unless can_par
            end

            prices =
              if step.respond_to?(:get_par_prices)
                begin
                  Array(step.get_par_prices(entity, corporation))
                rescue StandardError
                  []
                end
              elsif @game.stock_market.respond_to?(:par_prices)
                begin
                  Array(@game.stock_market.par_prices)
                rescue StandardError
                  []
                end
              else
                []
              end

            share_percent =
              if corporation.respond_to?(:share_percent)
                corporation.share_percent.to_i
              else
                10
              end

            share_percent = 10 unless share_percent.positive?

            president_percent =
              corporation.presidents_share&.percent.to_i

            unless president_percent.positive?
              president_percent =
                share_percent
            end

            share_units_needed =
              (president_percent.to_f / share_percent).ceil

            float_units_needed =
              par_float_units_needed(corporation)

            affordable_prices = prices.filter_map do |price_entry|
              share_price =
                price_entry.is_a?(Array) ? price_entry.first : price_entry

              price_value =
                if share_price.respond_to?(:price)
                  share_price.price.to_i
                else
                  share_price.to_i
                end

              initial_par_cost =
                price_value * share_units_needed

              next if initial_par_cost > player_cash

              slot = nil

              if @game.respond_to?(:par_chart) &&
                 @game.par_chart[share_price]
                slot =
                  begin
                    @game.par_chart[share_price].index(nil)
                  rescue StandardError
                    nil
                  end

                next if slot.nil?
              end

              {
                share_price: share_price,
                price_value: price_value,
                initial_par_cost: initial_par_cost,
                self_float_cost: price_value * float_units_needed,
                slot: slot,
              }
            end

            best_overall = affordable_prices.max_by do |candidate|
              candidate[:price_value]
            end

            best_self_float = affordable_prices
              .select { |candidate| candidate[:self_float_cost] <= player_cash }
              .max_by { |candidate| candidate[:price_value] }

            selected_candidates =
              [best_overall, best_self_float]
                .compact
                .uniq { |candidate| candidate[:share_price] }

            president_shares =
              if corporation.respond_to?(:presidents_share) &&
                 corporation.presidents_share
                [corporation.presidents_share]
              else
                []
              end

            selected_candidates.each do |candidate|
              kwargs = {
                corporation: corporation,
                share_price: candidate[:share_price],
              }

              kwargs[:slot] = candidate[:slot] unless candidate[:slot].nil?

              begin
                legal << Engine::Action::Par.new(
                  entity,
                  **kwargs.merge(shares: president_shares)
                )
              rescue ArgumentError => e
                raise unless e.message.to_s.include?('unknown keyword') ||
                             e.message.to_s.include?('shares')

                legal << Engine::Action::Par.new(
                  entity,
                  **kwargs
                )
              end
            end
          end

          if RUBY_ENGINE != 'opal'
            legal.select! do |action|
              trial = @game.clone(Array(@game.raw_actions))
              mapped = Engine::Action::Base.action_from_h(
                action.to_h,
                trial,
              )

              trial.process_action(
                mapped,
                add_auto_actions: true,
              )

              trial.exception.nil?
            rescue StandardError
              false
            end
          end

          legal
        end

        def drivable_train_capacity(entity)
          limit = @game.respond_to?(:train_limit) ? @game.train_limit(entity).to_i : 1
          limit = 1 unless limit.positive?

          if defined?(Engine::AutoRouter) && entity.respond_to?(:trains) && entity.trains&.any?
            routed_count = 0
            router = Engine::AutoRouter.new(@game, ->(_msg) {})
            router.compute(
              entity,
              routes: [],
              path_timeout: 1000,
              route_timeout: 1500,
              callback: lambda do |computed_routes|
                routed_count = Array(computed_routes).count do |route|
                  route.respond_to?(:chains) && route.chains&.any?
                end
              end
            )
            return [[routed_count, 1].max, limit].min if routed_count.positive?
          end

          connected = begin; @game.graph.connected_nodes(entity); rescue StandardError; []; end
          connected = begin; @game.graph.connected_hexes(entity).keys; rescue StandardError; []; end if Array(connected).empty?
          Array(connected).empty? ? 1 : [1, limit].min
        rescue StandardError
          1
        end

        def collect_bankruptcy(step, entity, actions)
          return [] unless actions.include?('bankrupt')
          return [] unless defined?(Engine::Action::Bankrupt)
          return [] unless entity.respond_to?(:corporation?) && entity.corporation?

          step_actions =
            begin
              Array(step.actions(entity)).map(&:to_s)
            rescue StandardError
              []
            end

          return [] unless step_actions.include?('buy_train')

          must_buy =
            begin
              step.respond_to?(:must_buy_train?) &&
                step.must_buy_train?(entity)
            rescue StandardError
              begin
                @game.must_buy_train?(entity)
              rescue StandardError
                false
              end
            end

          return [] unless must_buy

          buyable_trains =
            begin
              Array(step.buyable_trains(entity))
            rescue StandardError
              []
            end

          buyable_trains.each do |train|
            variants =
              begin
                if step.respond_to?(:buyable_train_variants)
                  Array(
                    step.buyable_train_variants(
                      train,
                      entity,
                    )
                  )
                else
                  []
                end
              rescue StandardError
                []
              end

            if variants.empty?
              variants = [
                {
                  name: train.name,
                  price: train.price,
                },
              ]
            end

            variants.each do |variant|
              price =
                if variant.is_a?(Hash)
                  variant[:price] ||
                    variant['price'] ||
                    train.price
                else
                  train.price
                end

              variant_name =
                if variant.is_a?(Hash)
                  variant[:name] ||
                    variant['name']
                end

              kwargs = {
                train: train,
                price: price,
              }

              kwargs[:variant] = variant_name if variant_name

              begin
                buy_action =
                  Engine::Action::BuyTrain.new(
                    entity,
                    **kwargs,
                  )

                trial =
                  @game.clone(
                    Array(@game.raw_actions)
                  )

                mapped =
                  Engine::Action::Base.action_from_h(
                    buy_action.to_h,
                    trial,
                  )

                trial.process_action(
                  mapped,
                  add_auto_actions: true,
                )

                return [] if trial.exception.nil?
              rescue StandardError
              end
            end
          end

          action =
            Engine::Action::Bankrupt.new(entity)

          if RUBY_ENGINE != 'opal'
            begin
              trial =
                @game.clone(
                  Array(@game.raw_actions)
                )

              mapped =
                Engine::Action::Base.action_from_h(
                  action.to_h,
                  trial,
                )

              trial.process_action(
                mapped,
                add_auto_actions: true,
              )

              return [] if trial.exception
            rescue StandardError
              return []
            end
          end

          [action]
        end

        def collect_destination_connections(step, entity, actions)
          return [] unless actions.include?('destination_connection')
          return [] unless step.respond_to?(:auto_actions)

          candidates =
            begin
              Array(step.auto_actions(entity))
            rescue StandardError
              []
            end

          candidates.select! do |action|
            action.is_a?(Engine::Action::DestinationConnection) &&
              action_belongs_to_entity?(action, entity)
          end

          return candidates if RUBY_ENGINE == 'opal'

          candidates.select do |action|
            trial = @game.clone(Array(@game.raw_actions))

            mapped =
              Engine::Action::Base.action_from_h(
                action.to_h,
                trial,
              )

            trial.process_action(
              mapped,
              add_auto_actions: true,
            )

            trial.exception.nil?
          rescue StandardError
            false
          end
        end

        def collect_trains(step, entity, actions)
          legal = []

          if actions.include?('buy_train')
            forced =
              begin
                step.respond_to?(:must_buy_train?) &&
                  step.must_buy_train?(entity)
              rescue StandardError
                false
              end

            current_count =
              entity.respond_to?(:trains) ? entity.trains.size : 0

            useful_count = drivable_train_capacity(entity)

            limit =
              if @game.respond_to?(:train_limit)
                @game.train_limit(entity).to_i
              else
                useful_count + 1
              end

            limit = 1 unless limit.positive?

            target_count =
              if RUBY_ENGINE == 'opal'
                target_key = [
                  @game.round.object_id,
                  step.object_id,
                  entity.object_id,
                ].join(':')

                @random_target_train_count[target_key] ||=
                  AiExpertRules.train_target_count(
                    useful_count,
                    limit,
                  )
              else
                [useful_count.to_i, limit].min
              end

            normal_train_needed =
              current_count < target_count

            has_permanent_train =
              Array(entity.trains).any? do |train|
                permanent_train?(train)
              end

            next_depot_train =
              begin
                @game.depot.min_depot_train
              rescue StandardError
                nil
              end

            corporation_cash =
              entity.respond_to?(:cash) ? entity.cash.to_i : 0

            next_depot_price =
              next_depot_train ? next_depot_train.price.to_i : 0

            can_afford_next_train =
              next_depot_train &&
              corporation_cash >= next_depot_price

            progression_train_needed =
              !normal_train_needed &&
              !has_permanent_train &&
              next_depot_train &&
              can_afford_next_train &&
              current_count < [target_count + 1, limit].min

            cash_rich_train_needed =
              next_depot_train &&
              AiExpertRules.buy_train_when_cash_rich?(
                corporation_cash,
                next_depot_price,
              )

            trains =
              begin
                if step.respond_to?(:buyable_trains)
                  Array(step.buyable_trains(entity))
                else
                  []
                end
              rescue StandardError
                []
              end

            affordable_permanent_depot_trains =
              trains.select do |train|
                from_depot =
                  train.owner == @game.depot ||
                  (
                    train.respond_to?(:from_depot?) &&
                    train.from_depot?
                  )

                from_depot &&
                  permanent_train?(train) &&
                  corporation_cash >= train.price.to_i
              end

            permanent_train_needed =
              affordable_permanent_depot_trains.any? &&
              AiExpertRules.buy_affordable_permanent_train?

            should_buy =
              forced ||
              permanent_train_needed ||
              cash_rich_train_needed ||
              normal_train_needed ||
              progression_train_needed

            if should_buy
              trains.each do |train|
                variants =
                  begin
                    if step.respond_to?(:buyable_train_variants)
                      Array(
                        step.buyable_train_variants(
                          train,
                          entity,
                        )
                      )
                    else
                      []
                    end
                  rescue StandardError
                    []
                  end

                if variants.empty?
                  variants = [
                    {
                      name: train.name,
                      price: train.price,
                    },
                  ]
                end

                variants.each do |variant|
                  price =
                    if variant.is_a?(Hash)
                      variant[:price] ||
                        variant['price'] ||
                        train.price
                    else
                      train.price
                    end

                  variant_name =
                    if variant.is_a?(Hash)
                      variant[:name] ||
                        variant['name']
                    end

                  kwargs = {
                    train: train,
                    price: price,
                  }

                  kwargs[:variant] = variant_name if variant_name

                  action =
                    Engine::Action::BuyTrain.new(
                      entity,
                      **kwargs,
                    )

                  if RUBY_ENGINE == 'opal'
                    legal << action
                    next
                  end

                  begin
                    trial =
                      @game.clone(
                        Array(@game.raw_actions)
                      )

                    mapped =
                      Engine::Action::Base.action_from_h(
                        action.to_h,
                        trial,
                      )

                    trial.process_action(
                      mapped,
                      add_auto_actions: true,
                    )

                    legal << action if trial.exception.nil?
                  rescue StandardError
                    next
                  end
                end
              end

              if permanent_train_needed
                permanent_actions =
                  legal.select do |action|
                    train = action.train

                    from_depot =
                      train.owner == @game.depot ||
                      (
                        train.respond_to?(:from_depot?) &&
                        train.from_depot?
                      )

                    from_depot &&
                      permanent_train?(train) &&
                      corporation_cash >= action.price.to_i
                  end

                legal = permanent_actions if permanent_actions.any?
              else
                same_director_actions =
                  legal.select do |action|
                    same_director_train?(
                      entity,
                      action.train,
                    )
                  end

                if same_director_actions.any? &&
                   AiExpertRules.buy_same_director_train?(@game, entity)

                  legal = same_director_actions

                elsif same_director_actions.any?
                  alternatives =
                    legal.reject do |action|
                      same_director_actions.include?(action)
                    end

                  legal = alternatives if alternatives.any?
                end
              end
            end
          end

          if actions.include?('discard_train')
            discardable =
              if step.respond_to?(:discardable_trains)
                begin
                  step.discardable_trains(entity)
                rescue StandardError
                  []
                end
              else
                entity.respond_to?(:trains) ? entity.trains : []
              end

            Array(discardable).each do |train|
              legal <<
                Engine::Action::DiscardTrain.new(
                  entity,
                  train: train,
                )
            end
          end

          legal
        end

        def collect_issue_shares(step, entity, actions)
          return [] unless (
            actions &
              %w[
                issue
                issue_shares
                reissue
                reissue_shares
                corporate_sell_shares
                sell_shares
              ]
          ).any?

          return [] unless entity.respond_to?(:corporation?) && entity.corporation?
          return [] unless defined?(Engine::Action::SellShares)

          bundles = []

          %i[
            issuable_shares
            issueable_shares
            issuable_bundles
          ].each do |method_name|
            next unless step.respond_to?(method_name)

            result =
              begin
                step.public_send(method_name, entity)
              rescue ArgumentError
                begin
                  step.public_send(method_name)
                rescue StandardError
                  []
                end
              rescue StandardError
                []
              end

            bundles.concat(Array(result))
          end

          %i[
            issuable_shares
            issueable_shares
            emergency_issuable_bundles
          ].each do |method_name|
            next unless @game.respond_to?(method_name)

            result =
              begin
                @game.public_send(method_name, entity)
              rescue StandardError
                []
              end

            bundles.concat(Array(result))
          end

          legal =
            bundles.compact.uniq.filter_map do |candidate|
              bundle =
                if candidate.respond_to?(:to_bundle)
                  candidate.to_bundle
                else
                  candidate
                end

              shares =
                if bundle.respond_to?(:shares)
                  Array(bundle.shares)
                else
                  Array(bundle)
                end

              next if shares.empty?

              kwargs = {
                shares: shares,
              }

              kwargs[:percent] = bundle.percent if bundle.respond_to?(:percent) && bundle.percent

              kwargs[:share_price] = bundle.share_price if bundle.respond_to?(:share_price) && bundle.share_price

              Engine::Action::SellShares.new(
                entity,
                **kwargs,
              )
            rescue StandardError
              nil
            end

          return legal if RUBY_ENGINE == 'opal'

          legal.select do |action|
            trial = @game.clone(Array(@game.raw_actions))

            mapped =
              Engine::Action::Base.action_from_h(
                action.to_h,
                trial,
              )

            trial.process_action(
              mapped,
              add_auto_actions: true,
            )

            trial.exception.nil?
          rescue StandardError
            false
          end
        end

        def collect_redeem_shares(step, entity, actions)
          return [] unless (
            actions &
              %w[
                redeem
                redeem_shares
                corporate_buy_shares
                buy_shares
              ]
          ).any?

          return [] unless entity.respond_to?(:corporation?) &&
                           entity.corporation?

          raw =
            if step.respond_to?(:redeemable_shares)
              begin
                Array(step.redeemable_shares(entity))
              rescue ArgumentError
                begin
                  Array(step.redeemable_shares)
                rescue StandardError
                  []
                end
              rescue StandardError
                []
              end
            elsif step.respond_to?(:redeemable_bundles)
              begin
                Array(step.redeemable_bundles(entity))
              rescue ArgumentError
                begin
                  Array(step.redeemable_bundles)
                rescue StandardError
                  []
                end
              rescue StandardError
                []
              end
            elsif step.respond_to?(:buyable_shares)
              begin
                Array(step.buyable_shares(entity))
              rescue ArgumentError
                begin
                  Array(step.buyable_shares)
                rescue StandardError
                  []
                end
              rescue StandardError
                []
              end
            else
              []
            end

          legal =
            raw.filter_map do |candidate|
              bundle =
                if candidate.respond_to?(:to_bundle)
                  candidate.to_bundle
                else
                  candidate
                end

              shares =
                if bundle.respond_to?(:shares)
                  Array(bundle.shares).flatten.compact
                else
                  Array(bundle).flatten.compact
                end

              next if shares.empty?

              price =
                if bundle.respond_to?(:price)
                  bundle.price.to_i
                else
                  0
                end

              next if entity.respond_to?(:cash) &&
                      price > entity.cash.to_i

              kwargs = {
                shares: shares,
              }

              if bundle.respond_to?(:percent) &&
                 bundle.percent
                kwargs[:percent] = bundle.percent
              end

              if bundle.respond_to?(:share_price) &&
                 bundle.share_price
                kwargs[:share_price] = bundle.share_price
              end

              if actions.include?('corporate_buy_shares') &&
                 defined?(Engine::Action::CorporateBuyShares)

                Engine::Action::CorporateBuyShares.new(
                  entity,
                  **kwargs,
                )
              else
                Engine::Action::BuyShares.new(
                  entity,
                  **kwargs,
                )
              end
            rescue StandardError => e
              LOGGER.warn(
                '[AI REDEEM] rejected candidate: ' \
                "#{e.class}: #{e.message}"
              )
              nil
            end

          return legal if RUBY_ENGINE == 'opal'

          legal.select do |action|
            trial = @game.clone(Array(@game.raw_actions))

            mapped =
              Engine::Action::Base.action_from_h(
                action.to_h,
                trial,
              )

            trial.process_action(
              mapped,
              add_auto_actions: true,
            )

            trial.exception.nil?
          rescue StandardError => e
            LOGGER.warn(
              '[AI REDEEM] engine rejected candidate: ' \
              "#{e.class}: #{e.message}"
            )
            false
          end
        end

        def collect_routes(_step, entity, actions)
          return [] unless actions.include?('run_routes')

          active_r = @routes&.select do |r|
            r.chains.any?
          rescue StandardError
            false
          end || []

          if active_r.empty? && defined?(Engine::AutoRouter)
            begin
              router = Engine::AutoRouter.new(@game, ->(_msg) {})
              router.compute(
                entity,
                routes: [],
                path_timeout: 1500,
                route_timeout: 2000,
                callback: lambda do |computed|
                  active_r = computed.select { |r| r.chains.any? } if computed
                end
              )
            rescue StandardError => e
              if RUBY_ENGINE == 'opal'
                `console.warn("[AI Expert] AutoRouter fallback warning:", #{e.message})`
              else
                LOGGER.warn(
                  "[AI Expert] AutoRouter fallback warning: #{e.class}: #{e.message}"
                )
              end
            end
          end

          active_r = Array(active_r).select do |route|
            train = route.respond_to?(:train) ? route.train : nil
            owner = train.respond_to?(:owner) ? train.owner : nil
            next false unless owner

            owner.equal?(entity) ||
              (owner.respond_to?(:id) && entity.respond_to?(:id) && owner.id.to_s == entity.id.to_s)
          end

          [Engine::Action::RunRoutes.new(entity, routes: active_r)]
        end

